INSERT INTO `jobs` (`jobid`, `uid`, `job_title`, `company_name`, `about_company`, `vacancies`, `jobs_active`, `job_expiry`, `work_experience_min`, `work_experience_max`, `job_type`, `contract_rate`, `contract_duration`, `internship_salary`, `internship_duration`, `salary`, `job_country`, `job_state`, `job_city`, `location`, `key_skills`, `job_url`, `industry`, `functional_area`, `youtube_url`, `telecommute`, `security_clearance`, `benefits`, `requirements`, `instruction`, `description`, `how_apply`, `academic_degree`, `dress_code`, `WorkAuthorize`, `PreferredEmployment`, `us_citizen`, `gc`, `ead`, `h1b`, `corp_corp`, `w2_permanant`, `w2_contract`, `1099_contract`, `contract_hire`, `date`, `count_date`, `days_ago`, `datetime`, `country_from`, `status`, `facebook_url`, `twitter_url`, `gplush_url`, `message`) VALUES
(1135988, 74820, 'Online Support For Jenkins,Docker,Ansible (Part Time Job)', '21 st century software solutions ', '', '3', '90', '25 Jul, 2017', '3', '7', 'Part-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Bengaluru', 'Devops', '', '23', '', '', '', '', '', '', '', 'This is Hema from 21st Century Software Solutions Pvt Ltd.We are looking for a Developer who can work with us on Devops <br />\r\nTimings:8 am to 10 am IST 2hrs (Tomorrow On wards)<br />\r\nPay:14000/- INR per month<br />\r\nContact Number :891-272-8543, [HIDDEN TEXT', 'FOR HELP PLEASE USE JOBSIRE.COM', 'BACHELOR\'S', 'FORMAL', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 April, 2017', '2017-04-24', 23, '2017-04-24 07:35:30', 'IN', 'Y', '', '', '', ''),
(1140951, 87339, 'IT - Technology Architect | Data Management - Data Integration | Informatica', 'Infosys', '', '', '30', '29 Apr, 2017', '5', '8', 'Contract', 'Open', 'Long Term', '', '', '', 'US', '', '', 'Madison, WI', 'Integration, Informatica', '', '23', '', '', '', '', '', 'Top 3 responsibilities you would expect the Subcon to shoulder and execute*:<br />\r\n1. Architectural activities<br />\r\n2. High and low level design activities<br />\r\n3. Design and code reviews<br />\r\n <br />\r\n<br />\r\nIf youâ€™re interested please Give me the below details:<br />\r\nUpdated Profile-<br />\r\nCandidate details:<br />\r\nCandidate Name-       <br />\r\nCurrent location (city, state or ZIP)-  <br />\r\nPhone number-          <br />\r\nE-mail ID-       <br />\r\nSkype ID-        <br />\r\nHighest Qualification & year of passed out-<br />\r\nWork Authorization- <br />\r\nDate Of Birth(dd/mm/yy)-<br />\r\nAvailability for Interview -     <br />\r\nTotal Years of experience-    <br />\r\nOverall relevant experience-<br />\r\nAvailable to start the Project-           <br />\r\nEmployer Contact Details:', 'Need perform Architectural and design activities. Perform High level and low level design activities', 'Must Have Skills (Top 3 technical skills only) *<br />\r\n1. Informatica<br />\r\n2. Oracle and Greenplum<br />\r\n3. PL SQL<br />\r\n <br />\r\nNice to have skills (Top 2 only)<br />\r\n1. Hadoop<br />\r\n2. Business Objects', 'For further queries reach me on 408-648-2518 or drop an email to  rathna@idctechnologies.com', 'BE', '', 'US Citizen, GC', 'W2-Permanant, W2-Contract', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '30 March, 2017', '2017-03-30', 48, '2017-03-30 09:59:37', 'US', 'Y', '', '', '', ''),
(1141683, 74820, 'Apps Dev Technical Specialist', 'CITI', 'About Citi<br />\r\nCiti, the leading global bank, has approximately 200 million customer accounts and does business in more than 160 countries and jurisdictions. Citi provides consumers, corporations, governments and institutions with a broad range of financial products and services, including consumer banking and credit, corporate and investment banking, securities brokerage, transaction services, and wealth management. Our core activities are safeguarding assets, lending money, making payments and accessing the capital markets on behalf of our clients.', '2', '90', '25 Jul, 2017', '3', '9', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'United States,', 'Team City, Hermes, SVN,Experience of Job Scheduling tool like AutoSys, Control M', '', '1', '94', '', '', '', '', '', '', 'Bachelorâ€™s degree in Engineering, Business Administration, Management or related discipline<br />\r\nâ€¢ 13+ years of industry experience with Netezza/ Oracle Database with at least 2 years of real time experience with Talend ETL tool, 1 year of real-time Java/J2EE experience in Database environment, 4 year of hands on oracle Database tuning, 4 years plus of Data warehousing design concepts, 4 years Plus of Netezza Hand one experience.<br />\r\nâ€¢ Exceptional skills with Dataware Housing Design, Architecture.', 'FOR HELP PLEASE USE JOBSIRE.COM', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '20 April, 2017', '2017-04-20', 27, '2017-04-20 07:09:21', 'US', 'Y', '', '', '', ''),
(1157098, 74820, 'Admin Cum HR Executive', 'Value Wings Enterprises Pvt Ltd.', 'Company Name: Value Wings Enterprises Pvt Ltd.Company Description: <br />\r\nValue Wings Enterprises Pvt Ltd ,<br />\r\nA Human Resource Company<br />\r\nValue Wings A Human Resource Company with over 12+ years of experience in providing Human Resources Services & Solutions to business & Enterprises. We have inspired many Employees & Organizations to work more Efficiently & Effectively. We create a platform for Employers & Employees to interface With each other every day through our Various Channel & Network.<br />\r\nValue Wings with over a decade experience understands todayâ€™s HR challenges faced by companies. Our team today has the expertise to <br />\r\nDevelop : An stance of teamwork & quality in day to day work life. <br />\r\nCreate : An atmosphere fostering Challenges, Fun, Safety & Productive. <br />\r\nSeize : Opportunities signifying excellent execution, attitude & sense of importance. <br />\r\nReduce : Squander by vigorously pursuing continues improvement behaviors. <br />\r\nCommit : In doing, acting explicitly and consistently in pursuit of uncompromising quality.<br />\r\nOur HR Services & Solutions are designed to help organizations to overcome the challenges & become more informed, productive and efficient. Our services enables our clients to increase their focus on their core business while improving benefits and controlling costs.', '2', '90', '06 Jul, 2017', '0', '1', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Bangalore', ' HR executive Admin Facilities Management Admin Executive HR HR executive Admin Facilities Management Admin Executive HR  ', '', '36', '115', '', '', '', '', '', '', 'General description<br />\r\npreferably male Candidates<br />\r\nGood communication <br />\r\n-Good body language<br />\r\n-Any qualification<br />\r\n-Two Wheeler must and should<br />\r\n-Age b/w 22 to 28<br />\r\nJob description:<br />\r\n<br />\r\n-Assists office staff in maintaining files and databases.<br />\r\n-Fixing the company issues in repair and maintenance<br />\r\n-Handling the petty cash.<br />\r\n-Supporting in finding resources for the company<br />\r\n-Prepares reports, presentations, memorandums, proposals and correspondence<br />\r\n-Assigns jobs and duties to office staff as needed<br />\r\n-Monitors office operations<br />\r\n- Schedules appointments and meetings for executives and upper level staff<br />\r\n-Serves as the go-to for office inquiries and conflicts<br />\r\n-Manages staff schedules<br />\r\n-Tracks office supply inventory and approves supply orders<br />\r\n-Assists in the preparation of department budgets and expenses<br />\r\n-Supervises all administrative personnel<br />\r\n-Excellent oral and written communication skills - Detail oriented and works with a high degree of accuracy<br />\r\n-Highly organized and flexible<br />\r\n-Ability to multitask and meet changing deadlines<br />\r\n-Must be self directed and able to complete projects with limited supervision<br />\r\n-Maintains staff confidentiality<br />\r\n-Working knowledge of email, scheduling, spreadsheets and presentation software<br />\r\n <br />\r\nJob Location: Value Wings Enterprises Pvt. Ltd. First Floor, No. 1/1, old no 257/A, 46 Cross, Sangam Circle, 8th Block Jayanagar Bangalore-560070 Land Mark opp tStart Date: 07-Apr-2017End Date: 11-Apr-2017<br />\r\n ', 'Email: pavithra@valuewings.comTelephone: 9945419872', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '07 April, 2017', '2017-04-07', 40, '2017-04-07 01:57:00', 'IN', 'Y', '', '', '', ''),
(1170754, 74820, 'IT Services Consultant', 'IT Services Consultant', '', '2', '90', '25 Jul, 2017', '2', '8', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', ' AZ - Phoenix', 'Exception planning, organization and time management skills; self-starter. High level of professionalism and integrity; good judgment. Good negotiating skills. Superior work ethic and high energy level. ', '', '1', '79', '', '', '', '', '3-5 years of experience in the Managed IT Services, or IT Services industry.<br />\r\n4-year college degree or equivalent industry experience.<br />\r\nSales/business development experience, with a record of meeting and exceeding quota.<br />\r\nHigh level of financial acumen, in order to have â€œbusiness discussions with business people.â€ <br />\r\nStrong communication, presentation, listening skills.<br />\r\nAbility to effectively deliver difficult messages while emphasizing positive, future-oriented perspectives.<br />\r\nTechnical aptitude, with the ability to appropriately apply technical service base to individual customer needs.<br />\r\nHighly adaptable to changes in business direction, services, and needs from a prospect, client and All Covered perspective.', '', 'All Covered, IT Services Division of Konica Minolta Business Solutions (KMBS), is the leading national IT services company serving SMB to enterprise markets. Offering a wide variety of career opportunities, All Covered is an excellent choice for motivated IT professionals interested in a stimulating and progressive work environment. ', 'FOR HELP PLEASE USE JOBSIRE.COM', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '25 April, 2017', '2017-04-25', 22, '2017-04-25 07:46:10', 'US', 'Y', '', '', '', ''),
(1216495, 74820, 'SQL Server/ BI Corporate Trainer', 'Synergetics Information Technology Services Privat', '', '3', '90', '25 Jul, 2017', '4', '12', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Mumbai', 'SQL Trainer Business intelligence SSAS SSIS SSRS Data Mining Power Tuning SQL Server -2012 SQL Server- 2014 SQL Server-2016 PL SQL', '', '23', '123', '', '', '', '', '', '', 'SQL Server/ BI Corporate Trainer <br />\r\n<br />\r\n The role is based in the Mumbai area, you will have the ability to deliver a range of synergetic portfolio courses, to generate revenue and maintain Synergetic standard of excellence through the delivery of classroom training and courseware development. A Train the Trainer course will be part of your Induction Program to help adapt to classroom teaching. You will have excellent operational and consulting experience, with sound knowledge and a proven track record in this space. With a passion, hunger and thirst to deliver quality training to the market, you will have excellent customer facing, interpersonal and communication skills, along with the ability to work independently.<br />\r\nMicrosoft SQL Server:<br />\r\nMicrosoft SQL Server 2012<br />\r\nMicrosoft SQL Server 2014<br />\r\nMicrosoft SQL Server Analysis Service<br />\r\nMicrosoft SQL Server Reporting Service<br />\r\nMicrosoft SQL Server Integration Service<br />\r\nMicrosoft SQL Server Performance Tunning<br />\r\nTSQL Programming<br />\r\nDatabase Administration<br />\r\nMandatory requirement SQL Database trainer-<br />\r\nSQL Server 2012 â€“ Developer<br />\r\n <br />\r\nSenior Trainer<br />\r\nShould have knowledge & Delivered batches on (Minimum 10 batchesdevelopers)<br />\r\nSQL Server 2012 â€“ SQL & T-SQL<br />\r\nPTO<br />\r\nDBA â€“ Including Always ON<br />\r\nSQL Server BI â€“ SSIS/SSRS/SSAS (Tabular and Multidimensional)<br />\r\nKnowledge of SQL Server 2014 / 2016 New Features will be added advantage<br />\r\nAny of the following is also added advantage<br />\r\nAzure SQL DB<br />\r\nPOWER BI<br />\r\nTableau<br />\r\nHadoop / HDINsight<br />\r\nMain Responsibilities<br />\r\nTo delivering both public scheduled and bespoke courses<br />\r\nTo work with clients to create courses and courseware related to their requirements<br />\r\nTo deliver, depending on personal skill set, other technologies as appropriate<br />\r\nTo achieve the required quality targets as set by the Company and determined by participant evaluations<br />\r\nTo take responsibility for developing and maintaining agreed courses<br />\r\nTo maintain an up-to-date skills base through personal development and accreditation activities<br />\r\nTo complete professional certifications as appropriate<br />\r\nTo support Sales and other internal departments with specialist advice and support on an ad-hoc basis<br />\r\nSkills & Experience Required<br />\r\n4 to 5 years instructor-led IT training experience<br />\r\nProfessional work experience with any 2 of the above technologies<br />\r\nExcellent customer-facing, presentation, interpersonal and communication skills, with an ability to share expertise with others Team player who can also adapt to working solo for long periods<br />\r\nAbility to adapt to changing circumstances and cope with stressful situations<br />\r\nA passion for IT and acquiring new skills and experience<br />\r\nBe prepared to travel to different locations in the India (and sometimes abroad) with occasional stays away from home<br />\r\napplication of Technical expertise in the \'real world\'<br />\r\nExperienceâ€“ 4 to 12 years of relevant experience<br />\r\nNo. of Opening â€“ 2<br />\r\nLocation â€“ Mumbai<br />\r\n <br />\r\nVibhutiVartak.<br />\r\nHR Executive<br />\r\n022-61488912<br />\r\nSynergetics Information Technology Services Private Limited<br />\r\n', 'Email: careers@synergetics-india.com<br />\r\nTelephone: 61488912', '', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 April, 2017', '2017-04-24', 23, '2017-04-24 05:23:54', 'IN', 'Y', '', '', '', ''),
(1240233, 74820, 'Technical Lead - Bangalore', 'COGNILARITY SOLUTION PVT L', '', '3', '90', '25 Jul, 2017', '5', '10', 'Full-Time', '', '', '', '', '5', 'IN', '', '', 'Bengaluru', 'Android, Java, PHP, AWS', '', '23', '', '', '', '', '', '', '', 'Hello,<br />\r\n<br />\r\nLooking candidates for the role of Technical Lead.<br />\r\n<br />\r\nLocation :Bangalore<br />\r\n<br />\r\nExperience : 5-8 Years<br />\r\n<br />\r\nRequirements:<br />\r\n1. Android, JAVA, PHP, AWS (Mandatory)<br />\r\n2. MySQL, Angular, Node.JS (Optional)<br />\r\n3. Should be able to learn and adapt to multiple languages, software and products.<br />\r\n4. Hands on experience on Mobile App Development, Web Development and Backend Technology.<br />\r\n5. Team Lead', 'FOR FURTHER INFORMATION PLEASE CONTACT JOBSIRE.COM', 'BACHELOR\'S', 'FORMAL', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 April, 2017', '2017-04-24', 23, '2017-04-24 05:16:11', 'IN', 'Y', '', '', '', ''),
