(3122864, 74820, 'Database Expert( DBA )', 'Progno Advisor', 'Company Name: Progno Advisor', '2', '90', '06 Jul, 2017', '5', '7', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Kochi', 'Skills: Database Administrat DBA Database developer Database Development Architecture Optimization Large Database handling T-SQL Microsoft SQL Server 2012 2014  ', '', '23', '17', '', '', '', '', '', '', 'Requirements: Profound knowledge as Database Developer/ Database Architect with experience in working with large databases. Expert knowledge in T-SQL and Microsoft SQL-Server 2012 / 2014 Ideally you will have experience in object oriented software development with C#.NET and the design of software in the database environment. Ability to understand the functionality of RDBMS, Capability to build real-time and highly secure DB, Implementation of logic (using Procedures, functions etc) Good working experience with Visual Studio, SSDT, TFS and SQL Server Management Studio. Database Cloud hosting<br />\r\n', 'Email: shine@zwayam.comTelephone: 8041330123', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '07 April, 2017', '2017-04-07', 40, '2017-04-07 00:04:11', 'IN', 'Y', '', '', '', ''),
(3124613, 74820, 'HR / Account Associate (night Shift)', 'Lumen21 Infoserv Private Limited', '', '', '90', '25 Jul, 2017', '1', '3', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Navi Mumbai', 'HR Operations Joining Formalities Exit Formalities Attendance Management Employee Grievances Background Verification Training HRMS', '', '24', '32', '', '', '', '', '', '', 'HR Roles: <br />\r\nAttendance Management - Pulling the weekly attendance reports, validating the same & maintaining the attendance database on Regular basis<br />\r\nJoining Formalities - Document collection from new joinees & co-ordinating with third party verification Company for carrying out background verification & updating the same information in HR software<br />\r\nTraining - Preparing Training Calendar and organizing other training programs for employees at regular intervals.<br />\r\nHR Operations - Preparing company communication letters.<br />\r\nHRMS - Keeping all employee information up to date in the HR software & other HR records<br />\r\nVisa - Coordinate with employee for visa processing, extension of visa, from documents preparation till petition approval. Maintaining MIS of renewal dates.<br />\r\nEmployee Grievances - Coordinate with employees at regular intervals to get & address their concerns/issues, to get their opinions/feedback etc.<br />\r\nEmployee Health & Safety - Implementing health provisions for employees like medical insurance & other benefits plan.<br />\r\nAudit Policies & Compliance - Working with senior delegates on updating yearly audit policies<br />\r\nExit Formalities - Complete Exit Formalities<br />\r\nAccount Roles: <br />\r\nGenerating invoices and take care of receivables<br />\r\nFollowing up with clients on payments & receivables.<br />\r\nCalculating and checking to make sure payments, amounts and records are correct.<br />\r\nSorting out incoming and outgoing daily post and answering any queries.<br />\r\nPerforming accounting roles such as handling checks, organizing financial records, coding documents, designing and submitting company forms, as well as handling inventory records.<br />\r\nOrganize meetings, as well as update accounting and business records<br />\r\nProviding accounting and clerical assistance to the accounting department<br />\r\nTyping accurately, preparing and maintaining accounting documents and records<br />\r\nWeekly reconciliation of sales and credit card receipts<br />\r\nPreparation of MIS in consultation with Line Manager', '', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '25 April, 2017', '2017-04-25', 22, '2017-04-25 07:39:45', 'IN', 'Y', '', '', '', ''),
(3212780, 30028, 'Wordpress Developer ( 1 year)', 'Stark Edge', 'Stark Edge is a Hubspot COS Certified Agency specialized in Hubspot COS Design and Development, Inbound Marketing, SEO, PPC. We are a Inbound Marketing Certified agency that offers Hubspot services at affordable rates. Inbound marketing is an emerging phenomenon and is the proven marketing methodology for the digital age.', '1', '30', '06 May, 2017', '1', '1', 'Full-Time', '', '', '', '', '', 'IN', '', '', 'Mohali', 'Wordpress, Core PHP, HTML, CSS etc.', '', '41', '123', '', '', '', '', 'Wordpress and core PHP knowledge.<br />\r\nAble to work in Night Shift.<br />\r\n', 'Only male candidates are required for night shift with approx 1 year experience only', 'We are Hiring for Wordpress Developers!!<br />\r\n<br />\r\nExperience Required: 1 year<br />\r\n<br />\r\nLocation : Mohali<br />\r\n<br />\r\nSalary: Hike on current CTC<br />\r\n<br />\r\nShift: Night<br />\r\n<br />\r\nRequired Skills:<br />\r\n<br />\r\n* candidate must have knowledge of Core PHP and Wordpress<br />\r\n<br />\r\n* Knowledge of HTML, CSS, Javascript, jquery etc.<br />\r\n<br />\r\n* Plugin Customization & implementation.<br />\r\n<br />\r\n* Must have knowledge of Coding.<br />\r\n<br />\r\n* Able to work in Night shift.<br />\r\n<br />\r\n* Good communication skills.<br />\r\n<br />\r\nInterested people can drop Cv\'s at hr@starkedge.com or call on 0172-4800054. References are most welcome.', 'share your cv\'s at hr@starkedge.com', '', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '06 April, 2017', '2017-04-06', 41, '2017-04-06 02:59:43', 'IN', 'Y', '', '', '', ''),
