(4815727, 74820, 'PHP, WordPress, Mysql Developer', 'Exploresys', '', '3', '90', '25 Jul, 2017', '3', '6', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Pune', 'Maintenance of Websites Applications. Mysql Developer', '', '23', '79', '', '', '', '', '', '', 'Development & Maintenance of Websites & Applications.<br />\r\nWrite clean, bug free code, ensure coding quality meets industry standards.<br />\r\nResponsible for Timely delivery.<br />\r\nAnalyze and develop new features for existing websites.<br />\r\nKeep up with trends and recommend changes and updates accordingly.<br />\r\nTechnical required: PHP, LAMP, Mysql, OOPS, Cake PHP, JQuery, Wordpress, Drupal, Joomla, Zend Framework.<br />\r\nExperience in PHP, Wordpress, MySQL is mandatory.<br />\r\nDesired Candidate Profile / Education :<br />\r\n(UG - B.Tech/B.E. - Computers, BCA - Computers) / (PG - MCA - Computers)<br />\r\n1.5 - 3 Years of Experience in PHP in analyzing & developing solutions<br />\r\nGood Communication, Analytical and Team Building Skills<br />\r\nDomain Knowledge of PHP, LAMP, Mysql, OOPS, Cake PHP, JQuery, Wordpress, Wordpress Templete Creation, Drupal, Joomla, Zend Framework<br />\r\nPHP, Wordpress, MySQL Experience MUST<br />\r\n', 'Company Name: Exploresys<br />\r\nCompany Description: Exploresys<br />\r\nEmail: jobs@exploresys.comTelephone: 7721993399', 'BACHELOR\'S', 'FORMAL', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '11 April, 2017', '2017-04-11', 36, '2017-04-11 05:58:02', 'IN', 'Y', '', '', '', ''),
(4849599, 74820, 'Internal IT Recruiter/uk Recruiter/domestic Recruiter', 'ITech Consult Recruitment Private Limited', 'ITech Consult AG is a certified ISO 9001 / 2008 Swiss company with offices also located in Germany, Great Britain and Ireland. ITech Consult is specialised in delivering ICT candidates for contract work. We were founded in 1997 by IT professionals; hence we well understand what it means to be professionally supported in your search for a new project and being employed', '2', '90', '25 Jul, 2017', '1', '4', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Hyderabad', 'IT Recruitment, Social Networking Searching, Training, Non It, MS Office ,Interpersonal Skills', '', '21', '115', '', '', '', '', '', '', 'Greetings from ITECH...!!!<br />\r\n<br />\r\nWe are currently looking for IT Recruiters for our organization located in Hitech City- Hyderabad.<br />\r\n<br />\r\nJob Description:<br />\r\nCandidate should possess excellent communication and interpersonal Skills.<br />\r\nShould possess basic understanding of recruitment process.<br />\r\nRole involved searching candidates in UK and EU Market through various job portals, references and social networking sites(Training would be provided)<br />\r\nShould be well versed with MS Office.<br />\r\nShould be good team player.<br />\r\nShould be able to join ASAP.<br />\r\nWilling to work in UK shifts. Work hours Monday to Friday 1.30 PM - 10.30 PM <br />\r\nManage database on day to day activities.<br />\r\nNote: We are not interested in US IT Recruiters or Non-IT Recruiters.', 'send your cv at gchennupati@itcag.com', 'ANY GRADUATATE ', 'FORMAL', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 April, 2017', '2017-04-24', 23, '2017-04-24 07:32:16', 'IN', 'Y', '', '', '', ''),
