(6194907, 74820, 'Technical Support Engineer', 'Imaginators Try Going Beyond Hiring For Imaginator', '', '3', '90', '25 Jul, 2017', '1', '5', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Delhi', 'technical support tech support B2B Sales', '', '23', '79', '', '', '', '', '', '', 'Hi<br />\r\nwe are hiring for technical sales,technical support<br />\r\nlocationa gurgaon<br />\r\n5days working<br />\r\ntechnical sales sal 27k<br />\r\ntechnical support 32k<br />\r\nQuatrro<br />\r\n9910877518<br />\r\n8285888002', 'Email: gandhi_amit2013@yahoo.com<br />\r\nTelephone: 9910877518', 'BACHELOR\'S', 'FORMAL', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '20 April, 2017', '2017-04-26', 21, '2017-04-20 07:10:24', 'IN', 'Y', '', '', '', ''),
(6230770, 74820, 'Magento Developer', 'Saisun Outsourcing Services Pvt Ltd', '', '3', '90', '25 Jul, 2017', '2', '5', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Chennai', 'HTML CSS JQuery Javascript', '', '23', '79', '', '', '', '', '', '', 'Experience in Object oriented PHP programming, Understanding of MVC design patterns.<br />\r\n- Experience in Wordpress / Drupal / Joomla / CodeIgniter.<br />\r\n- Sound knowledge in HTML, CSS, JQuery, Javascript and Ajax is a plus.<br />\r\n- Direct knowledge of App Store / Marketplace and E-Commerce<br />\r\n', 'Company Name: Saisun Outsourcing Services Pvt LtdCompany Description: <br />\r\nSaisun Outsourcing Services Pvt Ltd<br />\r\n <br />\r\nEmail: vivek@saisungroup.comTelephone: 8109073707', '', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '25 April, 2017', '2017-04-25', 22, '2017-04-25 07:42:24', 'IN', 'Y', '', '', '', ''),
(6236652, 74820, 'Technical Project Manager - C/.net/sql Server', 'HUQUO CONSULTING PVT. LTD.', '', '3', '90', '25 Jul, 2017', '8', '13', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Gurgaon, Delhi', 'Agile Bidding  ', '', '23', '79', '', '', '', '', '', '', 'Manage projects end-to-end by demonstrating strong project management skills and following project management standards <br />\r\n<br />\r\n- Be the face of the organization and manage customer expectations on deliverables by regularly communicating with Client / Analysts / Developers / Testers and all other project stake holders <br />\r\n<br />\r\n- Lead team to develop, test, support and deploy desktop, custom web, and mobile applications in a .Net environment, keeping up with project processes and deadlines. <br />\r\n<br />\r\n- Assist in creating proposals, RFP, bidding, estimation etc. for new opportunities <br />\r\n<br />\r\n- Assist junior team members in understanding and writing a quality code, conducting code reviews with developers, code refactoring. Also, assist and support projects with their technological challenges <br />\r\n<br />\r\n- Work in a multi-project environment and if required, own the responsibility of end to end delivery <br />\r\n<br />\r\n- Research and evaluate new software related technologies and products. Development of prototypes for new technology initiatives and product review/selection/recommendation <br />\r\n<br />\r\n- Adhere to best practices, standards and procedures including quality and delivery methodologies. <br />\r\n<br />\r\n- Support existing application and provide best possible solution to Client errors/problems <br />\r\n<br />\r\n- Contribute to the recruitment process within the organization <br />\r\n<br />\r\nQUALIFICATIONS & SKILLS : <br />\r\n<br />\r\nEducation : Any Graduate (B Tech, B.E-All Streams, BCA, MSc(IT), MCA & MBA Preferred) <br />\r\n<br />\r\n- Overall Experience : 10 Years and above <br />\r\n<br />\r\nRelevant Experience : <br />\r\n<br />\r\n- Project Management: 2 years + <br />\r\n<br />\r\n- C # Dot Net: 6 years +; MS certifications preferred <br />\r\n<br />\r\n- SQL Server: 4 years+ <br />\r\n<br />\r\n- Agile / Scrum: 4 years + <br />\r\n<br />\r\nAdditional Skills (If Any) : <br />\r\n<br />\r\n- Excellent Communication Skills <br />\r\n<br />\r\n- Strong positive attitude and a demonstrated ability to accomplish complicated projects <br />\r\n<br />\r\n- Self-motivated with leadership Skills<br />\r\n', 'Company Name: HUQUO CONSULTING PVT. LTD.<br />\r\nEmail: manoj@huquo.com<br />\r\nTelephone: 1244559224', 'BACHELOR\'S', 'FORMAL', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '12 April, 2017', '2017-04-12', 35, '2017-04-12 05:27:07', 'IN', 'Y', '', '', '', '');
