(6633940, 74820, 'Fresher PHP Developer (PHP & Mysql, Ajax, HTML , Javascript , CSS) - Jaipur', 'Iskylar Technologies', '', '2', '90', '25 Jul, 2017', '1', '2', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Jaipur', 'php developer fresher php developer fresher jobs in jaipur', '', '23', '124', '', '', '', '', '', '', 'iSkylar Technologies is hiring fresher PHP Developers with basis knowledge of OOPs and Core PHP. Only Graduate candidates will apply.<br />\r\nCandidate will go through the tremendous learing process after selection.<br />\r\nStiped will be provided for first 2-3 months after that candidate will be appointed as a full time PHP developer at iSkylar.<br />\r\nTechnical Requirement<br />\r\nCandidate should be well versed in PHP/Mysql development of applications in PHP, AJAX and HTML.<br />\r\nWeb Designing, Java Scripts, CSS Knowledge Must<br />\r\nGood knowledge of relational databases, version control tools and of developing web services<br />\r\nBenefits<br />\r\nAttractive salary<br />\r\nBest Professional Experience<br />\r\nOpportunity for Career & Professional Growth<br />\r\nHealthy Work Environment<br />\r\n<br />\r\nEmail: hr@iskylar.comTelephone: 8947932368', 'Email: hr@iskylar.comTelephone: 8947932368', 'BACHELOR\'S', 'FORMAL', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '12 April, 2017', '2017-04-12', 35, '2017-04-12 05:02:09', 'IN', 'Y', '', '', '', ''),
(6730396, 74820, 'Walkin Drive for - HR Recruiter at HGS Bangalore', 'Hinduja Global Solutions', '', '', '90', '25 Jul, 2017', '1', '3', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Bengaluru', 'Recruitment Volume Hiring Interviewing HR Customer Experience Management Consumer Electronics Public Sector', '', '41', '41', '', '', '', '', '', '', 'Dear Job Seeker,<br />\r\n<br />\r\nTop MNC Hinduja Global Solutions - HGS is hiring for HR Recruiter in Bangalore .<br />\r\n<br />\r\nCome, be a part of the growing organization!<br />\r\nWe are currently hiring graduates for the position of HR Recruiter.<br />\r\n<br />\r\nQualification:<br />\r\nGraduate in any stream for candidates with experience<br />\r\nMBA is a mandate for Freshers<br />\r\n<br />\r\nExperience:<br />\r\nMBA Freshers or Max upto 2 years experience in recruitement<br />\r\n<br />\r\nJob Description: <br />\r\n<br />\r\n-As a Recruiter one is responsible for identifying talent that meets the specific customers requirements. <br />\r\n-Posting and sourcing candidates through various - Job sites, social networking sites etc.<br />\r\n-Preliminary screening/short-listing the right qualitative profile against the given requirement.<br />\r\n-Coordinating with the Team to know the feedback of the candidates and improve sourcing based on the discussions.<br />\r\n-Conduct initial HR interviews (Telephonic) to check technical skills, communication Skills, interest levels, etc.<br />\r\n-Follow up on the feed backs.<br />\r\n-Closing the positions within the stipulated time.<br />\r\n-Following up with the candidate after the offer is made<br />\r\n<br />\r\nDesired Skills and Abilities:<br />\r\n<br />\r\n* Good command over English<br />\r\n* Good knowledge in End to End Hiring<br />\r\n* Basic knowledge of BPO.<br />\r\n* Should have good understanding or worked on Contract staffing<br />\r\n<br />\r\nPositions: 3<br />\r\n<br />\r\nWalkin Interview :<br />\r\n<br />\r\nHGS House,<br />\r\n614 Vajpayee Nagar, Next to IBIS Hotel,<br />\r\nHosur Main Road, Bommanahalli, <br />\r\nBangalore.<br />\r\n<br />\r\nKindly note that we have multiple branches of HGS on the same Hosur Main Road. Please ensure that you reach the right branch-HGS-House - Bommanhalli<br />\r\n<br />\r\nInterview Date - 27th April to 28th April 2017<br />\r\n<br />\r\nInterview Time: 11.00 am - 5.00 pm<br />\r\n<br />\r\nContact HR person: Navya<br />\r\n<br />\r\n(Please mention \"To meet HR Navya\" On top of your resume)<br />\r\n<br />\r\nInterested candidates can walk in directly and refer your friends <br />\r\n<br />\r\nRegards,<br />\r\nNavya', '', 'Bachelor\'s', ' Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '25 April, 2017', '2017-04-25', 22, '2017-04-25 07:52:56', 'IN', 'Y', '', '', '', ''),
