(6923897, 81342, 'PHP Developer', 'Virtue Logics', '', '10', '30', '06 May, 2017', '1', '3', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Panchkula', 'Core php, laravel, yii, codeginiter', '', '23', '40', '', '', '', '', '', '', '    Strong knowledge of PHP web frameworks {such as Laravel, Yii, etc} as well as of Nodejs, Angularjs, reactjs, MongoDB,Linux OS,Javascript,Jquery.<br />\r\n<br />\r\n    Having sound knowledge of Core PHP,  CMS like wordpress, magento, joomla, drupal etc.<br />\r\n<br />\r\n    Basic understanding of front-end technologies, such as JavaScript, HTML5, and CSS3.<br />\r\n<br />\r\n    Experience in Client Handling and Team Handling.<br />\r\n<br />\r\n    Knowledge of object oriented PHP programming<br />\r\n<br />\r\n    Strong knowledge of the common PHP or web server exploits and their solutions.<br />\r\n<br />\r\n    Integration of multiple data sources and databases into one system.<br />\r\n<br />\r\n    Familiarity with limitations of PHP as a platform and its workarounds.<br />\r\n<br />\r\n    Creating database schemas that represent and support business processes.<br />\r\n<br />\r\n    Familiarity with SQL/NoSQL databases and their declarative query languages.<br />\r\n<br />\r\n    Proficient understanding of code versioning tools, such as Git.<br />\r\n<br />\r\n<br />\r\n<br />\r\n', '', '', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '06 April, 2017', '2017-04-06', 41, '2017-04-06 05:30:23', 'IN', 'Y', '', '', '', ''),
(7031458, 74820, '      Technical Lead', 'Future Focus Infotech Pvt. Ltd. ', '', '', '90', '25 Jul, 2017', '4', '9', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Bangalore', ' Xml Asp C# .net Sql Server Javascript', '', '23', '79', '', '', '', '', '', '', '4+ years of experience of C#.NET, ASP.Net Web Forms. ASP.Net MVC and JavaScript programming, with an understanding of object-oriented programming.<br />\r\n2+ years Experience with DNN (formerly DotNetNuke) CMS Platform module development.<br />\r\nGood experience designing, developing, and supporting web applications.<br />\r\nMust be experienced in Microsoft SQL server. Specifically database design t-sql, and stored procedures.<br />\r\nMust be experienced in Internet Information Server (IIS) and Visual Studio.<br />\r\nExperience building and consuming REST APIs and XML/SOAP based Web Services and Web service concepts.<br />\r\nMust have strong UI skills.<br />\r\nStrong understanding of requirements, converting them to modules, web browsers and how they function.<br />\r\nKnowledge of web security concerns and preventive measures.<br />\r\nStrong analytic skills; ability to troubleshoot issues and offer solutions.<br />\r\nCreating Simple/complex custom DNN modules Skins<br />\r\nDebugging existing DNN modules<br />\r\nManage DNN server upgrades and patches. ', 'https://www.headhonchos.com/jobs/Technical-Lead-IT-Information-Technology-IT-Technology-Software-Services-Bangalore-1092368.html?Siteid=Indeed-JIT-XML&keyword=1092368&utm_source=Indeed-JIT-XML&utm_medium=Indeed_Xml', 'BACHELOR\'S', 'FORMAL', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '19 April, 2017', '2017-04-19', 28, '2017-04-19 06:59:43', 'IN', 'Y', '', '', '', ''),
(7032121, 74820, 'Lab Support Technical/Laboratory Specialist - UC Medical Center - Pathology(Job Number: 040744)', 'UC HEALTH', '', '3', '90', '25 Jul, 2017', '1', '12', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', ' UC Medical Center - 234 Goodman Street - Cincinnati, OH', ' Excellent written and verbal communication skills are required. Good teaching, time management, organizational, and planning skills are required. Excellent interpersonal skills are required. Leadership experience is required. ', '', '1', '119', '', '', '', '', '', '', 'Provides technical expertise supporting specimen collection, specimen processing and customer service functions in the laboratory. Provides training and competency assessment for laboratory support personnel and external customers. ', 'FOR HELP PLEASE USE JOBSIRE.COM', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '21 April, 2017', '2017-04-21', 26, '2017-04-21 07:21:15', 'US', 'Y', '', '', '', '');
