(12975246, 83624, 'Urgent Requirement for PHP Developer', 'Bridging Healthcare Technology', '', '2', '0', '', '2', '5', 'Full-Time', '', '', '', '', '3', '', '', '', 'Chandigarh', 'core PHP,Zend framework', '', '23', '41', '', '', 'Y', '', '', '', 'Hi All,<br />\r\n<br />\r\nWe have an Urgent Requirement for PHP Developer<br />\r\n<br />\r\nExp:- 3-5 years<br />\r\nSal:- Best in industry<br />\r\nLocation:- Chandigarh<br />\r\nNP:- Immediate Joinee<br />\r\n<br />\r\nIf interested,Please share your Resume at rachna@docmate.com or can call us at 9814405616<br />\r\n', 'send your updated resume at rachna@docmate.com', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 November, 2016', '2016-11-24', 174, '2016-11-24 03:59:20', 'IN', 'Y', '', '', '', ''),
(13015658, 34047, 'Operations Executive', 'www.mitramind.net', '', '02', '0', '', '0', '3', 'Full-Time', '', '', '', '', '3', '', '', '', 'Kolkata, ', '', '', '21', 'Select Functional Area', '', '', 'Y', 'Provident Fund<br />\r\nTransport Allowance<br />\r\nSat-Sun Holiday (fixed)<br />\r\nPerformance linked incentive', '1. Interacting with US based candidates over phone<br />\r\n2. Asking preliminary questions for screening purpose<br />\r\n3. Maintaining database in MS Excel and email etiquettes', '', 'Immediate requirement for RPO unit of a Kolkata based IT company (HQ in USA). <br />\r\nProfile involves calling prospective candidates from USA, and conduct a preliminary screening related to technical recruitment.  <br />\r\nNo sales/marketing/survey targets. Training will be provided. Customer service background preferred.  <br />\r\n<br />\r\nMandatory skills - Excellent command over English and strong knowledge of telephone etiquettes <br />\r\nFixed Shift - 7.30 PM to 4.30 AM (Mon - Fri) <br />\r\nSalary - Upto INR 14000.00/m + PF + TA <br />\r\nLocation - Newtown, Rajarhat   <br />\r\nConnect via LinkedIn or email at mitramind@gmail.com  <br />\r\n<br />\r\n*T & C (consultation charges) Apply ', 'Email at mitramind@gmail.com ', 'Minimum 10+2 completed in any stream of study', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '04 November, 2016', '2016-11-04', 194, '2016-11-04 03:03:02', 'IN', 'Y', '', '', '', ''),
(13203339, 0, ' Senior Java/Big Data Developer', 'Avani Technology Solutions', '', '2', '90', '08 Jun, 2017', '6', '10', 'Full-Time', '', '', '', '', '12', 'US', '', '', 'New York, NY', 'Big Data, core java, Python, Spark', '', '23', '40', '', '', '', '', '', '', 'Senior Java/Big Data Developer <br />\r\nNew York, NY<br />\r\n<br />\r\nC2H (Only Citizens and GC\'\'s)<br />\r\n<br />\r\n1. Spark <br />\r\n2. Core Java <br />\r\n3. Python <br />\r\n4. Machine Learning <br />\r\n<br />\r\nThey are looking for candidates with at least 2 yearsâ€™ experience in big data, 7-10 years overall (Non-negotiable is the Big Data Experience Experience with sourcing data. <br />\r\n<br />\r\nTop 4 skills: <br />\r\nSpark <br />\r\nCore Java <br />\r\nPython <br />\r\nMachine Learning <br />\r\n<br />\r\nImportance of Communication Skills <br />\r\nvery important - they want someone who can be interactive and engaging with the team. <br />\r\n<br />\r\nNice to Have Skills <br />\r\nsourcing data<br />\r\n', 'www.avanitechsolutions.com<br />\r\n +1-888-874-8112 X 203', 'MCA/B Tech./ M Tech.', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '10 March, 2017', '2017-03-10', 68, '2017-03-09 21:13:58', 'US', 'Y', '', '', '', ''),
(13212820, 74820, 'Vice President - Sales & Marketing', 'Columbia Asia Hospital', '', '', '90', '12 Jun, 2017', '10', '20', 'Full-Time', '', '', '', '', '6', 'IN', '', '434686', 'Bengaluru', 'Marketing Budget, Sales Achievement, Brand Building, Events, Marketing Programs, Strategic Planning, International Marketing, New Business, Marketing Planning, Profitability', 'http://india.columbiaasia.com/career/life-at-columbia-asia/overview', '31', '106', '', '', '', '', 'FINANCIAL RESPONSIBILITIES:<br />\r\n<br />\r\nTo ensure expense and target lines of Sales & Marketing department is within budget.<br />\r\n<br />\r\nPROCESS RESPONSIBILITIES:<br />\r\n<br />\r\nDisplay leadership role to sales & marketing across company. <br />\r\nEnsure team motivation & development is always high. <br />\r\nEnsure the team is delivering results as per their agreed goals and KRA. <br />\r\nPreparing and achieving sales targets with companys strategic plan. <br />\r\nStrategic planning for the international marketing. <br />\r\nDevelop and drive new business plans to achieve over company revenue targets. <br />\r\nExplore and advice on emerging new markets & products. <br />\r\nPrepare domestic & international marketing Budget <br />\r\nTrack Market changes and suggest ways and means to sat on top of the competition. <br />\r\nBusiness continuity with existing clients/vendors. Interdepartmental coordination, hospital legal, R&D, supply chain etc.<br />\r\nEstablish marketing contacts with corporate, insurers and other third party purchasers of health care services. Conduct presentations to these organisations of the services and facilities offered by Columbia Asia hospitals. Organise direct negotiations and contacts for services with these organisations. <br />\r\n<br />\r\nParticipate in these negotiations through the provision of information about prices or costs, suggested health care package programs, news way and better ways of conducting marketing programs or other data as requested by the Unit head or CEO.<br />\r\n<br />\r\nEstablish contacts with smaller health care facilities, including clinics and diagnostic centres for the purpose of obtaining referral business to the hospital.<br />\r\n<br />\r\nCoordinate and manage specific requirements requested by third party customers, i.e., customised reports etc., Respond to all enquiries by third party customers. Refer all complaints to the customer service department, but monitor complaints to assure that responses to third party customers are made on timely basis.<br />\r\n<br />\r\nOrganise and conduct various community related programmes, CAMPS, and other programs developed by the communication department of the company e.g.,<br />\r\n<br />\r\na)	Health talks and community education programmes<br />\r\nb)	Health camps : client contact programmes<br />\r\nc)	CME programmes, wellness programmes, Columbia kids programme<br />\r\nd)	Soccer programme<br />\r\ne)	Special events<br />\r\n<br />\r\nDevelop an annual marketing plan and budget for the entire company and the units.<br />\r\n<br />\r\nAssists the Finance Department of the Hospital in debt collection when necessary.<br />\r\n<br />\r\nUtilize the data bases of the hospital, as developed by the sales and marketing department of the company, for direct mailings to former patients, GPs in the market area of the hospital, other parties that may refer patients to the hospital and to third party payers.<br />\r\n<br />\r\nMonitor the business of competitors in the market. Provide an overview of the market scenario to the CEO.<br />\r\n<br />\r\nResponsible for timely setting of KRA and review as per the PMS guidelines<br />\r\n<br />\r\nEnsure your team participate in REDS activities', '', 'Analysing business potential, conceptualising & executing strategies to drive sales, augment turnover and achieving desired targets. Develop a strategic plan to promote revenue, profitability and growth. Full responsibility for sales & marketing, managing agreed targets, controls and systems, Forge long-term relationship with customers, business partners and other associates. Optimize time to market and implement best industry practices, Leadership, efficient team building, culture building and training. Brand conceptualization and responsibility for brand building as per Columbia Asia guidelines. <br />\r\n', 'Contact Saikat at 91-80-40211000', 'Marketing, Advertising, MR, PR, Media Planning', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '14 March, 2017', '2017-03-14', 64, '2017-03-14 03:38:23', 'IN', 'Y', '', '', '', ''),
(13429805, 80864, 'NodeJs', 'Aziels Technologies Pvt Ltd', '', '', '0', '', '1', '7', 'Full-Time', '', '', '', '', '6', '', '', '', 'Gurgaon, ', '', '', '23', '16', '', '', 'Y', '', '', '', '<br />\r\nProfile Description:<br />\r\nWe are looking for a Server side developer and team leader with strong hands-on experience to<br />\r\nwork on a very interesting cloud based distributed system. A strong understanding of front-end<br />\r\nWEB technologies is necessary as well.<br />\r\n<br />\r\nSkills And Qualifications<br />\r\nâ€¢ Proven experience working with Node.js<br />\r\nâ€¢ Proven experience developing server side applications using other languages<br />\r\nâ€¢ Understanding the nature of asynchronous programming and its quirks and workarounds<br />\r\nâ€¢ Deep understanding of Event Driven solutions<br />\r\nâ€¢ Basic understanding of front-end technologies, such as HTML5, and CSS3<br />\r\nâ€¢ Basic understanding on the design and implementation of cloud based distributed<br />\r\nredundant services is a big advantage.<br />\r\n<br />\r\n5 days Working', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '12 November, 2016', '2016-11-12', 186, '2016-11-12 05:27:48', 'IN', 'Y', '', '', '', ''),
(13574056, 62906, 'Senior Software Engineer (.net with Cloud', 'Nucleus Business Solutions', '', '8', '0', '', '3', '13', 'Full-Time', '', '', '', '', '', '', '', '', 'Hyderabad, ', 'C# .Net MVC (azure OR AWS)', '', '23', '36', '', '', 'Y', '', '', '', 'Desired Educational qualification:<br />\r\nBE/B.Tech/MCA or equivalent<br />\r\n <br />\r\nExperience:<br />\r\nOverall 6+ years of hands-on development experience<br />\r\n4.5+ years of hands-on C# development experience<br />\r\n <br />\r\nTechnical Skills:<br />\r\nShould have strong programming skill with ability to write optimized and reusable code.<br />\r\nDemonstrated experience developing enterprise applications using Object Oriented Programming, .NET Framework, ASP.NET and SQL Server programming.<br />\r\n <br />\r\nShould be Proficient on following areas of .NET(.Net 3.0 â€“4.6)<br />\r\nIn coding C#, ASP.NET<br />\r\nXML, HTML 5, JavaScript JQuery, Angular JS, JSON, REST and AJAX<br />\r\nDevelopment of Windows services, Web services, SOAP, WFC services<br />\r\nMultithreading<br />\r\nDevelopment of Data Access Modules using ADO.NET, Linq, Entity Framework<br />\r\nDebugging/troubleshooting in .Net<br />\r\n<br />\r\nShould have good experience/knowledge on following:<br />\r\nWindows Presentation Foundation / Silverlight <br />\r\nISS<br />\r\nSQL Server 2005-2014<br />\r\nKnowledge of development with ASP.NET MVC/ MVP/MVVM<br />\r\nKnowledge on Cloud platforms Microsoft Azure, AWS Technologies', '', 'B.Tech / M.Tech / MCA', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '15 September, 2016', '2016-09-15', 244, '2016-09-15 08:47:52', 'IN', 'Y', '', '', '', ''),
(13645614, 0, 'Project Architect', 'PGAL', '', '1', '90', '29 Jun, 2017', '10', '16', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Dallas, TX', 'Architectural ', '', '6', '98', '', '', '', '', '', '', 'Responsibilities / Qualifications:<br />\r\n<br />\r\nQUALIFICATIONS/RESPONSIBILITIES:<br />\r\n<br />\r\nPGAL is seeking a talented licensed Project Architect with 10+ years of experience who is interested in contributing to and thriving in a positive, studio environment. Our firm performs a wide range of project types for both private and public clients, and has a culture that is energetic, collaborative and open.<br />\r\n<br />\r\nMust be able to manage and produce documents on multiple projects concurrently in a fast-paced environment. Responsibilities include all phases of design through construction administration, project management and client contact. Effectively demonstrate technical detailing and problem-solving skills on complex project types.<br />\r\n<br />\r\nRequirements:<br />\r\n<br />\r\nBachelor\'s degree in Architecture or related field<br />\r\n<br />\r\nUS Architectural license, preferably in Texas<br />\r\n<br />\r\nKnowledge of Microsoft Office and proficiency in AutoCAD required.<br />\r\n<br />\r\nREVIT experience<br />\r\n<br />\r\nProficiency in 3D Studio or Sketch-up is a plus<br />\r\n<br />\r\nMust be legally authorized to work in the United States for any employer without sponsorship.<br />\r\n<br />\r\nPGAL offers a diverse and energetic working environment and benefits package including medical, dental, vision, and 401(k) plans.<br />\r\n<br />\r\nPGAL is an equal opportunity / E-verify employer. Protected veterans and persons with disabilities under applicable state and federal law are encouraged to apply.<br />\r\n<br />\r\nSALARY:<br />\r\n<br />\r\nBased upon qualifications.<br />\r\n<br />\r\nAVAILABILITY:<br />\r\n<br />\r\nImmediately<br />\r\n<br />\r\nCONTACT:<br />\r\n<br />\r\nTo apply, please send your resume and work samples to careers@pgal.com and indicate which position as well as location you are applying to in your email.<br />\r\n<br />\r\n<br />\r\nAn Equal Opportunity Employer Females/ Minorities/ Veterans/Disabled', 'careers@pgal.com', 'Bachelor\'s degree in Architecture ', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '31 March, 2017', '2017-03-31', 47, '2017-03-31 03:17:47', 'US', 'Y', '', '', '', ''),
(13707123, 0, 'Director of Organizational Effectiveness and Communications', 'Princeton University', '', '1', '90', '27 Jun, 2017', '7', '10', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Princeton, NJ', ' maintenance of the Finance & Treasury policy library,', '', '1', '56', '', '', '', '', '', '', 'Overview The Office of Finance and Treasury seeks a dynamic Director of Organizational Effectiveness and Communications to be a proactive partner on the Vice President Finance & Treasurerâ€™s senior leadership team. The successful candidate will lead the organizationâ€™s training, communications and division effectiveness initiatives in collaboration with many key stakeholders. The role works closely with Human Resources, the Provostâ€™s Office and others in facilitating the framework and processes to hire, cultivate and retain a skilled, diverse and inclusive work force in Finance and Treasury.<br />\r\n<br />\r\nThe Director represents the Finance & Treasury Division on university projects, including planning, budgeting, policy, and communication initiatives.<br />\r\n<br />\r\nThe Director provides leadership for the Divisionâ€™s Training and Communications organization, providing a high-quality business and financial curriculum to campus partners, leveraging the tools and systems launched in a recent overhaul of the universityâ€™s financial structure and systems. This role ensures that Finance and Treasury implements a carefully designed communications strategy, including web, print and electronic platforms that educates, informs and energizes internal and external audiences. In addition, the Director plays a leadership role in both external and internal communications strategies and implementation.<br />\r\n<br />\r\nThe successful candidate will be someone who functions successfully in a positive, mission-driven, and results-oriented culture; possesses a strategic and analytical approach to decision-making and problem-solving; possess strong interpersonal and communication skills; and have a high degree of sensitivity to organizational culture. This person must have proven ability to develop and maintain collaborative relationships at multiple levels across an organization.<br />\r\n<br />\r\nResponsibilities Primary duties include:<br />\r\n<br />\r\nTraining<br />\r\n<br />\r\n    Play a leadership role with Finance & Treasury senior leadership and Human Resources and the Provostâ€™s office to determine functional training and development needs and implement appropriate solutions.<br />\r\n<br />\r\n    Create opportunities for students to engage with Finance & Treasury, enriching the student and staff experience of University community.<br />\r\n<br />\r\nCommunications<br />\r\n<br />\r\n    Lead the development of the major external communications of the Division, including the published Annual Report of the Treasurer.<br />\r\n<br />\r\n    Identify and develop new external communication strategies to enhance organizational readiness and transparency.<br />\r\n<br />\r\n    Maximize and assess effectiveness of websites and other communication vehicles.<br />\r\n<br />\r\nDivision Workplace Effectiveness<br />\r\n<br />\r\n    Lead, integrate and support diversity and inclusion planning and assessment for the Division of Finance and Treasury.<br />\r\n<br />\r\n    Lead and plan division wide events to foster a vibrant organizational culture focused on the mission.<br />\r\n<br />\r\n    Partner with Human Resources and Finance and Treasury leadership to provide resources for managers on job description development, recruitment, hiring, orientation, performance management and professional development.<br />\r\n<br />\r\n    Oversee new employee onboarding and direct division orientation activities.<br />\r\n<br />\r\n    Coordinate the annual review and merit increase processes<br />\r\n<br />\r\n    Enhance the competency-based position structure by linking competencies to the full continuum of employee-related activity, including sourcing, hiring, training, evaluating and creating career paths for advancement.<br />\r\n<br />\r\n    Develop programming for managers to facilitate educational, skills and leadership development.<br />\r\n<br />\r\n    Assist the Vice President and Treasurer with developing learning resources for senior leadership.<br />\r\n<br />\r\nDivision Assessment<br />\r\n<br />\r\n    Develop and implement a program of employee engagement assessment.<br />\r\n<br />\r\n    Work with senior leadership to develop regular assessments of customer satisfaction.<br />\r\n<br />\r\nPolicy Coordination<br />\r\n<br />\r\n    Ensure Finance & Treasury policies are coordinated, consistent, and effectively communicated.<br />\r\n<br />\r\nDirect the maintenance of the Finance & Treasury policy library, including policy templates and policy-writing style guides.<br />\r\n<br />\r\n    Act as resource for faculty, staff, and students seeking guidance on Finance & Treasury related policies.<br />\r\n<br />\r\nQualifications Essential Qualifications<br />\r\n<br />\r\n    Bachelorâ€™s degree<br />\r\n<br />\r\n    7-10 years of related work experience<br />\r\n<br />\r\n    Strong leadership skills and demonstrated record of success at senior leadership level of an organization<br />\r\n<br />\r\n    Exceptional communication skills: writing; public presentation; facilitation<br />\r\n<br />\r\n    Strategic planning and analytical skills<br />\r\n<br />\r\n    Demonstrated ability to energetically handle multiple assignments and respond quickly to changing organizational needs and priorities<br />\r\n<br />\r\n    Evidence of self-motivation and the ability to work both independently and with others, with high personal standards representative of Princeton Universityâ€™s commitment to excellence.<br />\r\n<br />\r\n    Solid decision-making skills, proactive problem-solving skills, and outstanding judgment. <br />\r\n<br />\r\n    Proficiency with Microsoft Office applications<br />\r\n<br />\r\nPreferred Qualifications<br />\r\n<br />\r\n    Advanced degree in organizational development, human resources or related field<br />\r\n<br />\r\n    Knowledge of human resources practices and/or human resources certifications<br />\r\n<br />\r\n    Experience at Princeton or an institution similar to Princeton<br />\r\n<br />\r\nPrinceton University is an Equal Opportunity/Affirmative Action Employer and all qualified applicants will receive consideration for employment without regard to age, race, color, religion, sex, sexual orientation, gender identity or expression, national origin, disability status, protected veteran status, or any other characteristic protected by law. EEO IS THE LAW<br />\r\n<br />\r\nSalary Grade ADM, 080 Standard Weekly Hours 36.25 Eligible for Overtime No Benefits Eligible Yes Essential Services Personnel (see policy for detail) No Physical Capacity Exam Required No<br />\r\nAbout this company<br />\r\nChartered in 1746, Princeton is the fourth-oldest college in the nation. The ambience of its earliest days is palpable in historic landmarks on campus, most notably Nassau Hall, which in 1783 was the temporary capitol of the United States. From such a distinctive beginning grew something greatÃ‚Â­a community of learning that continues to evolve, providing abundant opportunities to talented students from around the world. Today, more than 700 faculty members, who are leaders in their respective disciplines, instruct Princeton\'s 4,600 undergraduate students and 2,000 graduate students. Hailing from all 50 states and more than 60 countries, Princeton\'s students represent a wide variety of economic, racial, ethnic, social, cultural, and religious backgrounds. These students enrich the campus community with their ideas and experiences and, above all, their desire to learn. Teaching and Research Princeton simultaneously strives to be one of the leading research universities and the most outstanding undergraduate college in the world. As a research university, it seeks to achieve the highest levels of distinction in the discovery and transmission of knowledge and understanding, and in the education of graduate students. At the same time, Princeton is distinctive among research universities in its commitment to undergraduate teaching. All faculty members at Princeton are expected to teach as well as engage in scholarly research. The University provides its students with academic, extracurricular, financial, and other resourcesÃ‚Â­in a residential community committed to diversity in its student body, faculty, and staffÃ‚Â­that help them achieve at the highest scholarly levels and prepare them for positions of leadership and lives of service in many fields of human endeavor. Through the scholarship and teaching of its faculty, and the many contributions to society of its alumni, Princeton seeks to fulfill its informal motto: \"Princeton in the Nation\'s Service and in the Service of All Nations.\" Working at Princeton With an overall workforce of 5,500 benefits-eligible employees, Princeton University is the largest private employer in Mercer County and one of the largest in central New Jersey. The employees of Princeton University are one of its most valuable resourcesÃ‚Â­the campus is full of talented and dedicated people who together make important contributions to the life and fabric of the community. The human resources of Princeton are remarkably diverse, including master glassblowers, program and budget analysts, Nobel and Pulitzer Prize winners, skilled office specialists, carpenters, and electricians. Princeton offers competitive salaries and a comprehensive benefits program that is responsive to the needs of its diverse staff. Princeton\'s comprehensive benefits program includes health and life insurance coverage, pension benefits, flexible spending accounts, income protection in the event of short- and long-term disabilities, and benefits for employee education and children\'s tuition grants and loans. A Vibrant Neighborhood The town of Princeton, which has a population of approximately 30,000 residents, has tree-lined streets, specialty shops, restaurants, parks, and a friendly and safe atmosphere. It is located midway between New York City and Philadelphia. An excellent transportation network of bus, rail, and highways puts Princeton within easy reach (an hour or less) of these major urban centers. Princeton\'s main campus consists of more than 6 million square feet of space in 160 buildings on 500 acres. Part of Princeton\'s history as a community is its tradition of serving as a congenial, stimulating haven for study and research for scholars from all parts of the world. Neighbor institutions include the Princeton Theological Seminary and the renowned Institute for Advanced Study. Walking paths and bicycle trails thread through their grounds and by Lake Carnegie, through Herrontown Woods, Marquand Park, and along the Delaware and Raritan Canal. The community offers a resident repertory theater, three orchestras, ballet, chamber music, and several choral groups. Princeton is ideally situated to host traveling art shows, dance and musical groups, and solo performers, in addition to visiting academicians and dignitaries from the world of public affairs. While maintaining its identity as a university town, Princeton\'s location has attracted a number of major corporations that have located primary research or corporate offices in the area. The proximity of scholars, writers, artists, scientists, and business professionals promotes a stimulating intellectual climate.', '', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '29 March, 2017', '2017-03-29', 49, '2017-03-29 07:16:09', 'US', 'Y', '', '', '', ''),
(13923424, 0, 'Civil Engineers Freshers', 'Professional HR Services', '', '1', '90', '03 Jul, 2017', '0', '1', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Asansol', 'Civil Engineers', '', '16', '117', '', '', '', '', '', '', 'Civil engineer has to Work In office for road mapping.Candidate must have Diploma/Degree in civil fresher or experience', 'email id- hrservices06@gmail.com<br />\r\ncall or whatsapp:-8271288891,9031871775<br />\r\n <br />\r\nEmail: hrservices06@gmail.com<br />\r\nTelephone: 8271288891', 'B-tech(mech/EEE/civil/ETC/CSE)', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '04 April, 2017', '2017-04-04', 43, '2017-04-03 22:06:56', 'IN', 'Y', '', '', '', ''),
(14024133, 0, 'Reporter', 'Vanguard Human Resource Consultant Pvt Ltd.', '', '2', '90', '18 Jun, 2017', '2', '4', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Noida', 'Reporter ', '', '28', '77', '', '', '', '', '', '', 'Eligibility Criteria: Candidate Should have 2-4 years of exp in Delhi/NCR Region Any Sector will do. Graduation in Journalism Pref. Salary up to-20k(Negotiable)', 'Email: anamika@vanguardhrconsulting.com<br />\r\nTelephone: 1204573291', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '20 March, 2017', '2017-03-20', 58, '2017-03-20 02:21:26', 'IN', 'Y', '', '', '', ''),
(14035618, 0, 'Assistant Manager-EDP', 'CIEL HR Services Pvt Ltd.', '', '1', '90', '25 Jul, 2017', '5', '7', 'Full-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Bangalore', 'Administration of the on board PMS POS System ', '', '23', '29', '', '', '', '', '', '', 'Administration and management of Windows NT servers (create new users, check event log, upgrade software, Microsoft exchange setup and maintenance, check daily backup, restore on demand, and archive data on cd-rom)<br />\r\n  Administration and management of windows workstations: install/update software, support and help-desk for users, troubleshooting, routine checks, monitor software installations, report illegal software use/installations.<br />\r\n  Administration of the on board PMS & POS System<br />\r\n  Network distribution rack: patch connections as required.<br />\r\n  Plan network extension: office network to be extended into additional offices. Arrange cabling, work out specifications, get quotations from store manager, and supervise installation of hardware, software installations and workstation setup.<br />\r\n  Arrange repairs of malfunctioning hardware with supplier(s).<br />\r\n  Arrange purchase of new equipment through established suppliers.<br />\r\n  Follow procedures and routines for purchasing equipment and software: request quotations, get written approval, sign delivery note, check delivery, report discrepancies, and approve invoices before payment.<br />\r\n  Keep inventory of hardware and software up-to-date. Monitor software licenses status and ensure compliance with license agreements. Responsible that no unlicensed software is in use.<br />\r\n  Training: train new users in the basics of the system: windows, email, intranet, ms office, in-house applications (invoice manager, human resource database), PMS and POS etc.<br />\r\n  Upgrade software: check out available upgrades of software in use. Always look out for ways to increase productivity, pre-select, evaluate and propose to management for purchase.<br />\r\n  System maintenance log: keep and update a logbook of system maintenance routines, frequent faults, along with solutions to problems.<br />\r\n  Coordinate support for accounting software and electronic banking software.<br />\r\n  Full mastery of mission-critical applications: nt, ms exchange server, ms outlook, ms office, internet explorer , coral draw, visio, adobe acrobat, front-page, Adonis, stock control software, invoice manager, human resource database, win fax I have read and discussed the above and I fully understand the descript.', 'Email: sivakumar@cielhr.com<br />\r\nTelephone: 9843922218', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '26 April, 2017', '2017-04-26', 21, '2017-04-26 07:26:54', 'IN', 'Y', '', '', '', '');
