(23329275, 0, 'Virtualization Engineer', 'Connectpro Management Consultants Pvt Ltd', '', '1', '90', '25 Jul, 2017', '3', '8', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Bangalor', 'Develop maintain Linux kernel device drivers. ', '', '23', '131', '', '', '', '', '', '', 'Responsible for Linux and Xen feature enablement for ARM processor.<br />\r\nDirectly interface with Xen and linux open source communities in accordance with processes<br />\r\nDevelop and maintain Linux kernel and device drivers.<br />\r\nWrite quality C and ARM assembly code following the code style of the Linux kernel and Xen hypervisor.<br />\r\nProvide silicon & platform design and FAEs support and system software expertise', 'Email: abhay@connectproserach.com<br />\r\nTelephone: 1126186977', 'Graduation', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '18 April, 2017', '2017-04-18', 29, '2017-04-18 06:29:14', 'IN', 'Y', '', '', '', ''),
(23425003, 0, 'Urgent opening for the accountant, Accounts Servicing, accounts in kavi nagar', 'Global Step.', '', '1', '90', '31 May, 2017', '2', '4', 'Full-Time', '', '', '', '', '', 'IN', '', '434079', 'Delhi ', 'accountant Accountant accountant ', '', '2', '100', '', '', '', '', '', '', '    Jobs Â»  Job Search  Â»  Manufacturing Jobs Â»  Urgent opening for the accountant, Accounts Servicing, accounts in kavi nagar<br />\r\n<br />\r\nUrgent opening for the accountant, Accounts Servicing, accounts in kavi nagar<br />\r\nGlobal Step.<br />\r\n<br />\r\n    2 to 4 Yrs<br />\r\n    Rs 1.5 - 2.5 Lakh/Yr<br />\r\n    Ghaziabad, Delhi<br />\r\n<br />\r\n    Skills:<br />\r\n    accountingfinanceaccountsMore<br />\r\n<br />\r\nApply<br />\r\nSend me similar jobs<br />\r\nJob Description<br />\r\n<br />\r\nurgent opening for the accountant, Accounts Servicing, accounts, accounting, finance, accountant, , finance & accounts, Accountant<br />\r\n<br />\r\nPreparing and maintaining statutory books of accounts viz, journal, ledger, cash book and subsidiaries in compliance with time & accuracy norms <br />\r\nPresenting a true and fair view of the financial position of the company by preparing financial statements viz, P&L Account, Balance Sheet and Annual reports, Budget & Reforecast <br />\r\nPreparing creditors/ debtors reconciliation statements<br />\r\nCash flow management collection and disbursals of payments<br />\r\nEnd to end Expense and Cash Management<br />\r\nDepreciation and Asset Management<br />\r\nBanking: Bank Transaction reconciliation; FEX Management<br />\r\nBanking Transactions: Import/Export Payments of Services; Documentation (Form CA filing)<br />\r\nDoing almost all functions in Accounting directly or indirectly (from book keeping to everything) <br />\r\nTaxation/MIS <br />\r\nPreparing tax plans and ensuring timely computation and filing of Income Tax, Provident Fund & TDS returns in compliance with Income Tax Act <br />\r\nFinalising the Statutory Audit Report and Tax Audit Report given by the Auditor<br />\r\nPreparing documents for questionnaire relating to Income Tax Scrutiny Cases (Assessment Proceeding and CIT Appeal cases)<br />\r\nGenerating MIS reports on manpower salary, incentives; project, location, etc. & presenting the same to the top management<br />\r\nService Management Billing for Professional Services based on hours/days (Fixed vs Scoped Projects) and timely payment mechanisms.<br />\r\nFormulating weekly report of the space sold and revenue generated<br />\r\nMaking calculation of the taxable income of the non resident individuals and filing of their Income tax return<br />\r\nLooking after Indirect Taxation VAT filing; returns; and assessments<br />\r\nService Tax Management Input/Output Calculations; Filing returns etc<br />\r\nCustoms related Matters (Imports; Import Documentation)', 'pl contact Hr geeta 9990596473<br />\r\nglobalplacementgzb@gmail.com<br />\r\n<br />\r\nEmail: mahant.enterprisesgzb@gmail.com<br />\r\nTelephone: 9990596473', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '02 March, 2017', '2017-03-02', 76, '2017-03-02 04:22:13', 'IN', 'Y', '', '', '', ''),
