(30669725, 0, ' PeopleSoft HCM Developer', 'Centraprise ', '', '1', '90', '13 Jun, 2017', '4', '14', 'Contract', 'USD 30 - 50 Per Hour', '3 - 6 Months', '', '', '11', 'US', '', '', 'Montvale, NJ', ' App Designer, Application Engine, Application package, Core HR, ESS, MSS,', '', '1', '40', '', '', '', '', '', '', 'PeopleSoft HCM Developer<br />\r\nDuration: 6 Months<br />\r\nLocation: Montvale, NJ<br />\r\n1. Should have intermediate level experience<br />\r\n2. Technical Professionals 5 to 7 years in PeopleSoft Technical- HCM.<br />\r\n3. Hands on experience with People Tools like App Designer, Application Engine, Application package, People Code and SQR<br />\r\n4. Should have strong technical experience on PeopleSoft HCM 9.2 (Core HR, ESS, MSS, position Management)<br />\r\n5. Should have hands on experience on Advanced Application Package People Code and Component/Page modification.<br />\r\n6. Should have expertise on Application Engine with Component Interface for loading data into PeopleSoft.<br />\r\n7. Fluid Page development as a plus.<br />\r\n8. Integration Broker experience as a plus.<br />\r\n9. PUM experience as a plus.<br />\r\n', 'Ashok<br />\r\nCentraprise<br />\r\nEdison, NJ<br />\r\nwww.centraprise.com<br />\r\n +1-609-357-4737', 'MCA/B Tech./ M Tech.', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '15 March, 2017', '2017-03-15', 63, '2017-03-15 01:51:01', 'US', 'Y', '', '', '', ''),
(30819131, 44316, 'Hiring For Online Bidder / BDE', 'FCS INNOVATIONS', '', '2', '0', '', '6', '1', 'Full-Time', '', '', '', '', '', '', '', '', 'Chandigarh, ', '', '', '23', 'Select Functional Area', '', '', 'Y', '', '', '', 'Currently we have an opening for the profile of online bidder/BDE<br />\r\n<br />\r\nJob Details:<br />\r\n<br />\r\n1.Must have experience in Online Bidding on the portals like Upwork, Freelancer etc.<br />\r\n<br />\r\n2. Must have excellent communication skills (verbal and written both).<br />\r\n<br />\r\n3.Creating pipeline of projects in web design,development and Digital marketing<br />\r\n<br />\r\n4.Lead generation and sales prospecting across Country.<br />\r\n<br />\r\n5. Revenue realization by generating business leads from Internet/Other sources.<br />\r\n<br />\r\n6.Able to work under pressure and meet deadlines .<br />\r\n<br />\r\n7.Capability to develop project plans and to manage multiple projects to completion.<br />\r\n<br />\r\n8. Good Connectivity With Team.<br />\r\n<br />\r\nExperience: Min 1 years <br />\r\n<br />\r\nContact us: 01722541021, 8196048781<br />\r\n', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '19 January, 2017', '2017-01-19', 118, '2017-01-19 04:55:15', 'IN', 'Y', '', '', '', ''),
(30973709, 0, 'Assistant Bodyshop Manager', 'Savy HR Management', '', '1', '90', '26 Jun, 2017', '2', '5', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'New Delhi', 'Assistant Bodyshop Manager', '', '7', '57', '', '', '', '', '', '', 'Hii Candidates,<br />\r\n<br />\r\n <br />\r\n<br />\r\nWe have an urgent hiring for Assistant Bodyshop Manager in Automobile company.<br />\r\n<br />\r\n <br />\r\n<br />\r\nJob Profile : Assistant Bodyshop Manager<br />\r\n<br />\r\nExperience : mini 2 year <br />\r\n<br />\r\nSalary : 3lacs pa. (according to experience)<br />\r\n<br />\r\nLacation :Delhi ( mayapuri)<br />\r\n<br />\r\nEssential:<br />\r\n<br />\r\nCandidate should have minimum 2 year experience in Assistant Bodyshop Manager in automobile sector .<br />\r\n<br />\r\n <br />\r\n<br />\r\nIntrested candidates mail me your cv on my given mail id or contact me.<br />\r\n<br />\r\n <br />\r\n<br />\r\nRegards<br />\r\n<br />\r\nvaishali<br />\r\n<br />\r\nvaishalisavy.hr@gmail.com<br />\r\n<br />\r\n011-65105584', 'Email: vaishalisavy.hr@gmail.com<br />\r\nTelephone: 011-65105584', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '28 March, 2017', '2017-03-28', 50, '2017-03-28 00:38:43', 'IN', 'Y', '', '', '', ''),
