(32079410, 87339, 'Civil Engineer ', 'AS Group', '', '', '0', '', '0', '1', 'Full-Time', '', '', '', '', '', '', '', '', 'Bangalore, ', '', '', '13', 'Select Functional Area', '', '', 'Y', '', 'Company Name: AS GroupCompany Description: <br />\r\n <br />\r\n <br />\r\nEmail: hr.talks@outlook.comTelephone: 9818209928', '', 'We are having INTERVIEW FOR Civil Engineer Jobs For the Position Of Site Engineer & Quality Engineer<br />\r\nInterview Timings :- 10 am to 5 pm<br />\r\nPlease find the skills required as below :-<br />\r\nQualification: <br />\r\nBE/B.TECH/DIPLOMA <br />\r\nStream:- Civil Engineer<br />\r\nSKILLS:- <br />\r\nBASIC CONCEPT Civil Engineer<br />\r\nADVANTAGES:- <br />\r\n1. OPPORTUNITY TO JOIN THE FASTEST GROWING ORGANIZATION. <br />\r\n2. LUCRATIVE PACKAGES<br />\r\nBetween the Ages of 18 to 35<br />\r\nCall- 9818209928,8744844298', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '04 October, 2016', '2016-10-04', 225, '2016-10-03 19:43:10', 'IN', 'D', '', '', '', ''),
(32439111, 0, 'Accounting Clerk', 'Beyond Vision', '', '2', '90', '21 Jun, 2017', '3', '7', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Milwaukee, WI', 'Accounting - General, Customer Service - General, Admin - Data Entry/Billing', '', '2', '62', '', '', '', '', 'COMPETENCIES<br />\r\n<br />\r\n    Ethical Conduct.?<br />\r\n<br />\r\n    Time Management.<br />\r\n<br />\r\n    Problem Solving<br />\r\n<br />\r\n    Customer Service.<br />\r\n<br />\r\n    Organization Skills.<br />\r\n<br />\r\n    Financial Management.<br />\r\n<br />\r\n    Project Management.<br />\r\n<br />\r\n    Personal Effectiveness/Credibility.<br />\r\n<br />\r\n    A passion and commitment to fulfilling our mission and vision.<br />\r\n<br />\r\n    REQUIRED EDUCATION AND EXPERIENCE<br />\r\n     <br />\r\n<br />\r\n    A two-year degree in accounting or 3 to 5 years of experience in the accounting field. Strong experience in accounts receivable is highly desired.<br />\r\n<br />\r\n    Accurate keyboarding skills of 40 w.p.m. with 95 percent accuracy.<br />\r\n<br />\r\n    Strong computer skills especially working with Excel, Outlook, and ERP systems.<br />\r\n<br />\r\n    Excellent verbal and written communication skills. The ability to effectively develop relationships and trust with internal and external customers (both on the phone and in-person).<br />\r\n<br />\r\n    Detail oriented and the ability to do the task right the first time.<br />\r\n<br />\r\n    Experience working in a manufacturing environment preferred.<br />\r\n<br />\r\n    We offer:<br />\r\n<br />\r\n     A culture that values delighting our customers, constant improvement, and fun!<br />\r\n<br />\r\n    â€¢ The opportunity to help create quality jobs and upward mobility for people who are blind or visually impaired.<br />\r\n<br />\r\n     <br />\r\n<br />\r\n    Learn more about Beyond Vision at www.beyondvision.com<br />\r\n', '', 'Beyond Vision is a non-profit social enterprise dedicated to the mission of providing career opportunities for people who are blind or visually impaired. Whether itâ€™s in our manufacturing and assembly plant, our new state-of the art call center, or in our retail locations on government facilities nationwide, we provide quality employment for people who are legally blind. We are now seeking a talent and efficient Accounting Clerk to join our team and our mission.<br />\r\n<br />\r\n <br />\r\n<br />\r\nUnder the direct supervision of the Controller, the Accounting Clerk will be responsible for the effective administration of accounts receivable for the entire organization, data entry of customer orders, and general customer service to our government and commercial customers.<br />\r\n <br />\r\n<br />\r\nESSENTIAL FUNCTIONS:<br />\r\n<br />\r\n* Post customer payments by recording cash, checks, credit card transactions, and other EFT payments according to department policies and practices.<br />\r\n<br />\r\n* Ensure that all customer information is collected and set up in ERP system<br />\r\n<br />\r\n* Complete timely and accurate entry of customer orders into the ERP system for various departments. Orders may be electronic or paper.<br />\r\n<br />\r\n* Complete daily invoicing of customer orders. Ensure timely and accurate billing to customers.<br />\r\n<br />\r\n* Resolves collections by examining customer payment plans, payment history, credit line; coordinating contact with business unit leaders to ensure timely payment by customers.<br />\r\n<br />\r\n* Maintain all accounts receivable reports. Work with Business Unit leaders to ensure timely payment by customers. Develop strategies for past due accounts.<br />\r\n<br />\r\n* Maintain accurate and up-to-date electronic and paper records.<br />\r\n<br />\r\n* Provide accounts receivable reporting and be the \"corporate owner\" of accounts receivable.<br />\r\n<br />\r\n* Complete Wisconsin Rehabilitation Tax Credit forms for customers as required.<br />\r\n<br />\r\n* Complete Flash Sales Reporting on a weekly basis.<br />\r\n<br />\r\n* Handle customer service questions, requests, and issues. Work independently or with business unit leaders and other staff to ensure timely resolution to customer orders<br />\r\n<br />\r\n* Work with Business Unit leaders to establish bill of materials and routing for production parts.<br />\r\n<br />\r\n* Review work order travelers to verify proper closure and appropriate material issuance.<br />\r\n<br />\r\n* Work collaboratively and engage with internal and external customers<br />\r\n<br />\r\n<br />\r\n', 'Tel: 414.778.5800 â€¢ Fax: 414.778.5805<br />\r\n5316 West State Street â€¢ Milwaukee, Wisconsin 53208', '10+2', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '23 March, 2017', '2017-03-23', 55, '2017-03-23 02:50:56', 'US', 'Y', '', '', '', ''),
