(47641828, 60470, 'Business development Executive', 'Technofacts', '', '3', '0', '', '4', '9', 'Full-Time', '', '', '', '', '', '', '', '', 'Hyderabad, ', '', 'http://www.techno-facts.com', '29', '43', '', '', 'Y', '', '', '', 'Work activities<br />\r\nâ€¢	Identifying new markets and business opportunities and arranging meetings with potential customers<br />\r\nâ€¢	Visiting potential customers for new business and developing and maintaining relationships<br />\r\nâ€¢	Making accurate cost calculations to provide customers with quotations<br />\r\nâ€¢	Negotiating the terms of an agreement with a view to closing sales<br />\r\nâ€¢	Attending trade exhibitions, events and demonstrations to represent the employing organization<br />\r\nâ€¢	Advising on forthcoming product developments and discussing special promotions<br />\r\nEducation & Experience<br />\r\n<br />\r\nâ€¢	Graduate with min 2 years of Sale experience<br />\r\nâ€¢	Post graduate with 1 year of Sale experience<br />\r\nâ€¢	Experience in same domain will be added advantage<br />\r\nâ€¢	People from Insurance & Real-estate sales domain are not eligible for this position<br />\r\n<br />\r\n', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 November, 2016', '2016-11-24', 174, '2016-11-24 04:41:48', 'IN', 'Y', '', '', '', ''),
(47672034, 0, 'Team Lead Sales', 'ARG..', '', '1', '90', '19 Jun, 2017', '1', '3', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Delhi', 'Sales  Business Development  Team Handling ', '', '29', '114', '', '', '', '', '', '', 'Researching and identifying sales opportunity, generating leads, target identification and classification<br />\r\n<br />\r\nÂ· Reaching out to new customers and making presentations or pitches outlining the benefits of product<br />\r\n<br />\r\nÂ· Understanding the client requirements and then customizing the product as per their needs<br />\r\n<br />\r\nÂ· Ensuring minimum targets are met with added incentives<br />\r\n<br />\r\nÂ· Maintaining relationship with all potential and existing clients<br />\r\n<br />\r\nÂ· Reviewing their team performance and aim at exceeding their targets.<br />\r\n<br />\r\nÂ· . To ensure systematic follow-up with the client to take the sales pitch to time-bound closure.<br />\r\n<br />\r\nÂ· Meet company\'s performance expectations<br />\r\n<br />\r\nÂ· Should have laptop.', 'ARG E COM PVT LTD', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '21 March, 2017', '2017-03-21', 57, '2017-03-21 02:26:37', 'IN', 'Y', '', '', '', ''),
(47729533, 0, 'HIRING FOR CUSTOMER RELATIONS OFFICER- 9986563344', 'Proficient 360 HR Solutions Hiring For Proficient ', '', '1', '90', '26 Jun, 2017', '0', '3', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Bangalore', 'Communication Skills Customer Service Languages BPO Communication', '', '9', '12', '', '', '', '', '', '', 'LOOKING FOR AN OPPORTUNITY IN BPO <br />\r\n<br />\r\nREACH US FOR BEST BPO JOBS!!!<br />\r\n<br />\r\n <br />\r\n<br />\r\nROLE: CUSTOMER RELATIONS OFFICER<br />\r\n<br />\r\n <br />\r\n<br />\r\nWORK FOR 5 DAYS A WEEK<br />\r\n<br />\r\nONLY DAY SHIFT FOR WOMEN AND MUCH MORE.<br />\r\n<br />\r\n <br />\r\n<br />\r\nJob Description<br />\r\n<br />\r\nInbound Customer Service:<br />\r\n<br />\r\n <br />\r\n<br />\r\nRequirement:<br />\r\n<br />\r\nGood communication skills<br />\r\n<br />\r\nFreshers/experience dynamic individuals<br />\r\n<br />\r\nFlair for customer service and retention<br />\r\n<br />\r\nBasic tech knowledge<br />\r\n<br />\r\nShould Know one of the south Indian languages<br />\r\n<br />\r\nFlexible to work in shifts<br />\r\n<br />\r\n <br />\r\n<br />\r\n Interested candidates can call 9071018700/9986593344 or mail @ proficient360@gmail.com<br />\r\n<br />\r\n WALK IN-<br />\r\n<br />\r\nPROFICIENT360 HR SOLUTIONS<br />\r\n<br />\r\nNo 401, 2nd Floor, 6th B main, HRBR Layout, 2nd Block, Kalyan Nagar, Bangalore 560043.<br />\r\n<br />\r\nLAND MARK: NEXT TO BANASWADI COSOPOLITON CLUB (80FT ROAD)<br />\r\n<br />\r\nRegards,<br />\r\n<br />\r\nProficient360', '    Company Name: Proficient 360 HR Solutions Hiring For Proficient 360 HR Solutions<br />\r\n    Email: proficient360@gmail.com<br />\r\n    Telephone: 9071018700', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '28 March, 2017', '2017-03-28', 50, '2017-03-28 00:29:10', 'IN', 'Y', '', '', '', ''),
(47883597, 74820, 'Dell Boomi Architect', 'Simplion', '', '', '30', '06 Apr, 2017', '1', '3', '', 'Open', '6 - 12 Months', '', '', '', 'US', '', '', 'Ridgeland, MS', 'Dell Boomi', '', '23', '', '', '', '', '', 'Â·         Familiarity with Boomi Atmosphere or other visual-based integration middleware platforms like TIBCO, WebMethods, Oracle Fusion, MuleSoft, WSO2<br />\r\nÂ·         At least 8+ years of application integration development and/or design;  Proven ability to design and optimize application and data integration processes across disparate systems.<br />\r\nÂ·         Atleast 3+ years of experience in Application architecture.<br />\r\nÂ·         Experience with enterprise integration tools, middleware technologies, and application and data integration patterns including ESB, MOM, JMS, SOAP/REST web services, databases<br />\r\nÂ·         Having decent knowledge on ETL tools.<br />\r\nÂ·         Practical experience implementing services oriented architecture design and enabling technologies including messaging, XML, JSON, web services, and HTTP<br />\r\nÂ·         Experience with Cloud and Software-as-a-Service paradigm and enabling technologies<br />\r\nÂ·         Excellent communication skills', '', 'Â·         Work closely with customer and Horne LLP partners to gather requirements and design complex business application and data integration solutions<br />\r\nÂ·         Translate business processes and requirements into technical integration requirements and designs; Evaluate new applications to assess integration approach<br />\r\nÂ·         Experience in providing multiple solutions and recommendations.<br />\r\nÂ·         Provide architecture-level infrastructure recommendations, configuration, and sizing requirements to support the Dell Boomi product suite; Be a product expert of Dell Boomi applications including the AtomSphere integration platform and API Management.<br />\r\nÂ·         Recommend best practices for implementing, managing, and governing integrations using the Boomi AtomSphere integration platform<br />\r\nÂ·         Define and promote the adoption of best practices of Dell Boomi\'s products across the internal and external user community', 'Shawn Casey<br />\r\nEmail: shawn@simplion.com', '', '', 'ANY', 'Corp-Corp, W2-Contract, 1099-Contract', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '07 March, 2017', '2017-03-07', 71, '2017-03-06 15:57:49', 'US', 'D', '', '', '', ''),
(47929624, 0, 'Mayfair Rent-A-Car Seasonal Positions', 'Ewald Automotive Group', '', '', '90', '22 Jun, 2017', '5', '9', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', ' Oconomowoc, WI', ' seasonal, sales clerk, outside sales, call center, training, recruiting, wireless, resume, cell phone, internet sales, advertising sales, marketing, insurance, finance, consulting, mortgage broker, automotive, auto sales, car sales, product specialist, technical sales, retail, auto salesman, salesman, salespeople, salespeople,', '', '7', '108', '', '', '', '', '', '', 'Mayfair Rent-A-Car, Wisconsin\'s largest privately owned Rental Car Company, has openings for part time to possible full time seasonal positions.  Our business expands greatly during the Spring Summer and Fall.  With that in mind, we need seasonal part time rental agents in Wauwatosa, Oconomowoc, Cudahy, Kenosha, Racine, and Franklin.  <br />\r\n<br />\r\nMayfair Rentâ€“Aâ€“Car, a division of the Ewald Automotive Group, has an exciting career opportunity for Rental Agents to join our growing team. This position allows for flexible hours working during the Mayfair Rent-A-Car operating hours. Mayfair Rent-A-Car is open Monday through Friday from 7am to 6pm and Saturday 8am to noon.<br />\r\nSundays off!  Cudahy has extended hours of 8-5pm Saturday and Sunday.<br />\r\n<br />\r\nAPPLY TODAY at https://workforcenow.adp.com/jobs/apply/posting.html?client=ewaldauto&ccId=19000101_000001&type=JS&lang=en_US<br />\r\n<br />\r\nEwald Automotive Group is a family owned company and a leader in the automotive industry. Since 1964, we have provided award winning sales and service throughout Southeastern Wisconsin. Mayfair Rentâ€“Aâ€“Car, with locations in Brown Deer, Cudahy, Franklin, Hartford, Kenosha, Oconomowoc, Racine, Waukesha and Wauwatosa, is the leading independent car and van rental company in Wisconsin.<br />\r\n<br />\r\nAs a Rental / Customer Service Agent, you will have the opportunity to assist customers in person, as well as over the telephone, in satisfying their rental needs. Other responsibilities include processing rental transactions, delivery and pickup of vehicles, inventory management, sales and marketing activities, and vehicle preparation. This is a hands on position for a person desiring a challenging position with a variety of duties.<br />\r\n<br />\r\nSuccessful candidates will have an outgoing personality, excellent communication skills, and be dependable with good attention to details. A high school diploma with previous customer service, retail or sales experience is required. In addition a valid driverâ€™s license with a good driving record is a must.<br />\r\n', 'https://workforcenow.adp.com/jobs/apply/posting.html?client=ewaldauto&ccId=19000101_000001&type=JS&lang=en_US', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 March, 2017', '2017-03-24', 54, '2017-03-24 04:53:05', 'US', 'Y', '', '', '', ''),
(47966955, 0, 'Community Sales', 'Gaia Consulting and Solutions Pvt. Ltd. Hiring For', '', '2', '90', '21 Jun, 2017', '1', '4', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Chennai/Madras', 'Sales Executive Channel Sales ', '', '26', '116', '', '', '', '', '', '', 'We have job opening for Sales with ISP based company.<br />\r\n<br />\r\nJob Location: Chennai<br />\r\n<br />\r\nExp: 2 -4yrs<br />\r\n<br />\r\nAge Limit â€“ 22 -30yrs<br />\r\n<br />\r\nSalary: Best in the Industry<br />\r\n<br />\r\nRole Description<br />\r\n1. Responsible to sell the company products / Services to targeted customers in the assigned number of projects.<br />\r\n<br />\r\n2. Experience in community sales is must.<br />\r\n<br />\r\n3. Should have decent communication.<br />\r\n<br />\r\n4. Customer Handling Skills.<br />\r\n<br />\r\nIf interested, Kindly revert back with your updated profile to tamil@gcs.co.in and refer you friends also that would be appreciated.If not relevant to you kindly ignore this mail.', 'Email: tamil@gcs.co.in<br />\r\nTelephone: 8608491831', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '23 March, 2017', '2017-03-23', 55, '2017-03-23 03:10:52', 'IN', 'Y', '', '', '', ''),
(48002050, 13174, 'CustomerCare Executive', 'Globez Professional Solutions Pvt Ltd', '', '15', '0', '', '0', '3', 'Full-Time', '', '', '', '', '3', '', '', '', 'Kolkata', 'Customer Focus, Customer Service, Listening, Phone skills , Verbal Communication,  Interpersonal Savvy ,Multi tasking, Strong communication skills', '', '9', '9', '', '', 'Y', 'ADDITIONAL BENEFITS:<br />\r\n- Fixed off on Saturday & Sunday.<br />\r\n- Free Pick up and drop facilities provided for the employees both ways.<br />\r\n- 8 hours shift (fixed shift available)<br />\r\n- Lucrative incentives.<br />\r\n- COMPLIMENTARY LUNCH/DINNER.<br />\r\n- Pantry / Cafeteria facilities are available.', '', '', 'Hi, <br />\r\nWe looking for Customer care Executive for one of our esteemed client based in Kolkata. Interested candidates contact as soon as possible.<br />\r\n<br />\r\nCCE(CUSTOMER CARE EXECUTIVE)<br />\r\nJOB DESCRIPTION:<br />\r\n- Responsible for initiating calls to potential clients using a prepared selling script<br />\r\n- Promoting and selling products and services of company.<br />\r\n- A wide degree of creativity and latitude is expected.<br />\r\n- Provide customers with product and service information.<br />\r\n- Work productively whilst maintaining exceptional call/data quality standards in line with<br />\r\ntargets.<br />\r\n- Contribute to the team through open and regular communication with peers / supervisors.<br />\r\n- Maintain regular and punctual attendance in line with company policies and procedures.<br />\r\n- Perform other duties commensurate with the post as per Client and Management guidelines<br />\r\n<br />\r\nSKILLS:<br />\r\n- Customer Focus<br />\r\n- Customer Service<br />\r\n- Listening, Phone skills<br />\r\n- Verbal Communication<br />\r\n- Interpersonal Savvy<br />\r\n- Multi tasking<br />\r\n- Good communication skills in English.<br />\r\n<br />\r\nELIGIBILITY:<br />\r\n- Gender: Both Male & Female candidates , may apply.<br />\r\n- Education : 10+2 / Graduate in any stream<br />\r\n- Experienced and Fresher may apply.<br />\r\n- Age: Between 18â€“30 may apply.<br />\r\n<br />\r\nDESIRED PROFILE:<br />\r\n- Goal oriented.<br />\r\n- Positive attitude.<br />\r\n- Good interpersonal skills.<br />\r\n- Good lateral thinking<br />\r\n- Willing to take cold calls.<br />\r\n- Stress tolerance<br />\r\n<br />\r\n<br />\r\n', 'send resume at globez2016@gmail.com / call 9831004655', '10+2 /Any Graduate', 'Formal', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '05 January, 2017', '2017-01-05', 132, '2017-01-05 05:25:36', 'IN', 'Y', '', '', '', ''),
(48119034, 0, 'Urgent Opening for Software Support Engineer for Kolkata', 'D.S. Infotech Private Limited', '', '1', '90', '08 Jun, 2017', '0', '1', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Kolkata', 'SQL-Server SQL / PL SQL ', '', '23', '56', '', '', '', '', '', '', 'Dear Candidate,<br />\r\n<br />\r\n <br />\r\n<br />\r\nPlease read the complete message carefully.<br />\r\n<br />\r\nGreetings from D.S. Infotech!!<br />\r\n<br />\r\nWe have an open position for Software Support Engineer, details are furnished below.<br />\r\n<br />\r\nPosition â€“ Helpdesk Support<br />\r\n<br />\r\nLocation â€“Kolkata<br />\r\n<br />\r\nNos of opening â€“ 02<br />\r\n<br />\r\nSkill â€“ Should have working experience on SQL, PLSQL and SQL Server.<br />\r\n<br />\r\nAdept in writing performance optimised SQL queries.<br />\r\n<br />\r\nPossess good Troubleshooting and Analytical skills.<br />\r\n<br />\r\nExperience â€“ 06 months to 01 Years<br />\r\n<br />\r\nSalary â€“ Rs. 7000/- in hand<br />\r\n<br />\r\nJob Description â€“ Candidate should have adequate knowledge to support software.<br />\r\n<br />\r\nEducation qualification â€“ B.E., B. Tech, BSC â€“ IT, BCA, MCA<br />\r\n<br />\r\nRequest you to please share the requirement to your friends or relatives.<br />\r\n<br />\r\nThanks and Regards<br />\r\n<br />\r\nPrabir Mondal<br />\r\nD.S.Infotech Pvt. Ltd.<br />\r\nOrbit, 1, Garstin Place,<br />\r\n1st Floor, Unit-1G,<br />\r\nKolkata-700 001. <br />\r\nPh-22100841 / 40668156<br />\r\nemail: p.mondal@dsinfotech.com', 'Email: p.mondal@dsinfotech.com<br />\r\nTelephone: 40668156', 'BTECH/BE in CSE or equivalent', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '10 March, 2017', '2017-03-10', 68, '2017-03-09 21:07:02', 'IN', 'Y', '', '', '', '');
