(50183340, 74820, 'BPO | Call Center | Fresher | Hindi BPO | International BPO', 'Hiring for Reliance JIO/ Flipkart/ Amazon/ Paytm', '', '', '90', '12 Jun, 2017', '0', '1', 'Full-Time', '', '', '', '', '2', 'IN', '', '434079', 'Delhi', 'INTERNATIONAL BPO, CALL CENTER, VOICE PROCESS, CUSTOMER SERVICE, DOMESTIC BPO', '', '9', '14', '', '', '', '', '', 'Interview Timing 9:00AM To 5:00PM', 'RELIANCE JIO / PayTM / Snapdeal /AMAZON/ FLIPKART / AIRTEL / VODAPHONE / SHOPCLUES AND MANY MORE BPO.... Call Center Executive Call - 8800924925<br />\r\n<br />\r\nOpenings in Day Shifts or Night Shifts<br />\r\n<br />\r\nCandidate with good customer service skills would be preferred.<br />\r\n<br />\r\nCandidate must have 0 year of experience in Customer Support Voice Process (Call Center).<br />\r\n<br />\r\nCandidate having prior experience in Customer Service industry will be an advantage<br />\r\n<br />\r\nSelected candidates will have choice to work either in Day or Night shifts.<br />\r\n<br />\r\nCandidates with backlogs/arrears in their degree can also apply.<br />\r\n<br />\r\nResponsible for dealing with either Domestic or International Clients.<br />\r\n<br />\r\nResponsible for dealing with Clients Queries.<br />\r\n<br />\r\n<br />\r\nInterview Timings : 9:30 Am - 5:30 Pm<br />\r\n<br />\r\nWalk In for BPO interview with your Updated Resume and photocopy of qualification documents.<br />\r\n<br />\r\nSALARY<br />\r\n<br />\r\n9000-13000 PLUS INCENTIVES UP TO 6000 IN DOMESTIC BPO<br />\r\n<br />\r\n12000-25000 FOR INTERNATIONAL BPO(BOTH SIDE CAB FOR<br />\r\n<br />\r\nINTERNATIONAL BPO)<br />\r\n<br />\r\nContact US :- <br />\r\n<br />\r\nSONIA 8800924925<br />\r\n<br />\r\nSONAM 9891067666<br />\r\n<br />\r\nADITYA 9811207222<br />\r\n<br />\r\nAKANSHA 8800937788<br />\r\n<br />\r\nSANAYA 8800399933<br />\r\n<br />\r\nSNEHA 9205242342', 'Contact Sonia at 8800924925', 'Any Postgraduate and Graduate', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '14 March, 2017', '2017-03-14', 64, '2017-03-14 04:04:30', 'IN', 'Y', '', '', '', ''),
(50224060, 87339, 'Chief Security Officer', 'UNION BANK OF INDIA', '', '1', '0', '', '20', '30', 'Contract', 'Lumpsum compensation of R', '', '', '', '7', '', '', '', 'Mumbai', '', 'http://www.unionbankofindia.co.in/abt_recruitmentaspx.aspx', '10', 'Select Functional Area', '', '', 'Y', 'Fill in the required details in the word file of the Application Format and take a print out of duly filled Application Form. Attach your latest Passport size photograph on the application form and sign it at the appropriate places. Applicants need to send following documents by email to recruitment@unionbankofindia.com and ensure that it reaches this office by 30.09.2016.<br />\r\n', 'http://www.unionbankofindia.co.in/pdf/UBRP201617ChiefSecurityOfficerEnglish%20Notification.pdf', '', 'UNION BANK OF INDIA, a leading Public Sector Bank, with Pan India Branch Network with Head Office in Mumbai, invites Applications for the post of Chief Security Officer on Contractual Basis.', '', 'Graduate in any discipline from a recognized University or any equivalent qualification recognized as such by Government authority.', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '14 September, 2016', '2016-09-14', 245, '2016-09-13 17:38:39', 'IN', 'D', '', '', '', ''),
(50316333, 31750, 'Vendor sourcing executive', 'Valuepoint Knowledgeworks', '', '3', '0', '', '0', '0', 'Full-Time', '', '', '', '', '3', '', '', '', 'Bangalore, ', 'Fresher/Exp(upto 2years), Sourcing, Client handling, screening, head hunting, signing agreement with translators, negotiation skills.', '', '21', 'Select Functional Area', '', '', 'Y', 'Performance Rewards/incentives/Perks/Health Insurance ', '(1)Innovative Sourcing<br />\r\n(2)Timeline Oriented<br />\r\n(3)Negotiation skills<br />\r\n(4)Good oral and written Communication skills<br />\r\n(5)Knowledge of MS Office<br />\r\n(6)Internet Savvy', '', 'Primary Activities:<br />\r\n(1)Sourcing Indian Language Translators for internal and external requirement on a<br />\r\nspecific target and also source for the projects which are in planning phase.<br />\r\n(2)Search new websites, links or communities, universities, agencies to source<br />\r\nIndian language translators.<br />\r\n(3)Commercial negotiation<br />\r\nSigning MSA and NDA agreements with translators<br />\r\nSecondary Activities:<br />\r\n(1)Interacting and obtaining the new requirement from QAPED team.<br />\r\n(2)Coordinate with QAPED team for evaluating the quality of the translators before<br />\r\nempanelling into database.<br />\r\n(3)Process adherence.<br />\r\n(4)Prepare Daily/Weekly/Monthly Reports<br />\r\n', 'Send your resume to shailaja.h@knowledgew.com <br />\r\ncontact on :(080)30752044 / +91 95387 77904', 'BCom, BBA, BBM, BSc, MBA', 'Formals', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '11 November, 2016', '2016-11-11', 187, '2016-11-11 03:10:19', 'IN', 'Y', '', '', '', ''),
(50317956, 69645, 'web developer ', 'US Technology International Pvt Ltd ', '', '', '0', '', '6', '8', 'Full-Time', '', '', '', '', '', '', '', '', 'Pune', '', '', '23', 'Select Functional Area', '', '', 'Y', '', '<p>html 5k, angular js ,angular css J,avascript ,oops object oriented ,data structures ,web development</p>', '', '<p>Between 6 to 8 years of relevant web development experience<br /> Strong programming background, object oriented programming, design patterns and data structures (either in Java or Microsoft .NET)<br /> Good coding skills in HTML5, CSS3, JavaScript, Angular JS, Typescript<br /> Unit testing experience in QUnit or Jasmine or similar testing framework is a strong advantage<br /> Exposure to Force.com platform is a bonus<br /> An interest and preferably working experience in agile development methodologies<br /> A team player, eager to invest in personal and team growth, curious<br /> Strong analytical, conceptual and creative thinking skills. A problem solving and pragmatic attitude</p>', '', 'UG - B.Tech/B.E. - Any Specialization, Computers, Electrical, Electronics/Telecommunication  PG - Any Postgraduate - Any Specialization, Post Graduation Not Required  Doctorate - Doctorate Not Required', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '26 August, 2016', '2016-08-26', 264, '2016-08-25 23:45:24', 'IN', 'Y', '', '', '', ''),
(50745087, 74820, 'Full Stack Developer', 'Xoriant Corporation', '', '1', '30', '', '0', '5', 'Contract', 'Open', '6 - 12 Months', '', '', '', 'US', '2998', '1184884', 'San Francisco, San Ramon', 'Oil & Gas', '', '23', 'Select Functional Area', '', '', '', 'Spring Batch - Spring Integration - Spring Security - Spring Data - OAuth 2.0 - NoSQL Databases ( Apache Cassandra, MongoDB, .. ) - Big Data - Cloud technologies - Caching technologies (Riak, Redis) - Message Queuing ( RabbitMQ, Kafka ) - Linux Shell - Cloud foundry - Linux containers - Python scripting - Big data technologies (HDFS, Apache Spark, Apache Storm) - Knowledge of other open source technologies like Ruby, Scala - HTML & HTML5 - Javascript - JQuery - CSS - Angular JS - HTML 5 - Js Package management (bower) - PolymerJs / Web components - NodeJs - LESS CSS - Play framework - Grunt - Activator framework - Cloud technologies - Knowledge of other open source Frontend libraries', ' Core Java Programming - GE Predix - Communication skills - Agile methodologies - Maven - Experience with a code repository (Git, SVN, Githubâ€¦) - Familiar with TDD or BDD - Spring Framework - Spring Boot - Node Js - RDBMS - Core Java - Java Enterprise Patterns<br />\r\n<br />\r\n', 'Experience in the Oil & Gas industry a big plus', 'Use technology expertise, Industry & competitive intelligence and deep knowledge customer preferences to conceive, evaluate, design & deliver superior product / service offerings that exceed customer expectations * Develop lasting, innovative architecture that satisfies business and customer requirements, and aligns with the long-term plan for the product/service. * Apply a strategic understanding of the timing and rationale for design choices and identifies critical design areas early in the development process. * Drive new ways of thinking, across groups within the division, to improve quality, engineering productivity, and responsiveness to feedback and changing priorities. * Find opportunities for collaboration across groups in the division, ensures that cross-team commitments are set, and achieves scale in his or her work efforts by enabling the work of others. * Tailor communication to a variety of audiences and perspectives, and anticipates issues to prevent conflict. * Choose the appropriate internal or external technologies, incorporates research, creates designs that are reused across the team, and is an excellent judge of practices that work well. * Define quality metrics, best practices and coding patterns, and provides deep expertise on the coding strategy. * Produce simple, elegant code, and resolves the most difficult problems in the product. * Resolve issues outside his or her area of responsibility and opens discussions with peers and takes action when needed to ensure the success of the product.', '', '', '', 'ANY', 'W2-Permanant', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 February, 2017', '2017-02-24', 82, '2017-02-24 06:45:25', 'US', 'Y', '', '', '', ''),
(51006379, 0, 'Immediate Need: Senior C#/.NET Developer @ Seattle, ', 'Charter Global', '', '1', '90', '02 Jul, 2017', '10', '12', 'Contract', '', '6 - 12 Months', '', '', 'Market', 'US', '', '', 'Seattle, WA', '.NET, C#, MVC, WPF,', '', '23', '22', '', '', '', '', '', '', 'Role: Senior C#/.NET Developer<br />\r\nContract : Long-term/Full time<br />\r\nLocation : Seattle, WA<br />\r\nPositions: 3<br />\r\n<br />\r\nsend resumes to rsaini at charterglobal dot com<br />\r\n<br />\r\nManager Notes: Looking for candidates that are comfortable with coding simple algorithms (queues, stacks, trees, etc and can develop logic around it.<br />\r\n<br />\r\nRequired skills:<br />\r\n.NET/ C# development experience : 10 + years Exp<br />\r\nWPF Exp<br />\r\nExperience with coding simple algorithms (queues, stacks, trees, etc and developing logic around it.<br />\r\nMVC Exp<br />\r\n<br />\r\nProcess: 1st : Tech Screen, 2nd Skype interview<br />\r\n', 'Frank Preta<br />\r\nCharter Global<br />\r\nAtlanta, GA<br />\r\nwww.charterglobal.com<br />\r\n +1-770-326-9933 X 396', 'BE/BTech', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '03 April, 2017', '2017-04-03', 44, '2017-04-03 02:17:11', 'US', 'Y', '', '', '', ''),
(51118691, 0, 'Urgently Opening for Sr. Executive Microsoft Sales SBD - CTM (MS Sales', 'VNT solutions', '', '2', '90', '20 Jun, 2017', '3', '7', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Mumbai ', 'Oracle Sales Cloud Ms Sales CTM Sales O365 Azure is Microsofts Microsoft IT Software product B2b Sales Sr. Software Sales ', '', '24', '116', '', '', '', '', '', '', 'Dear Candidate,<br />\r\n<br />\r\n <br />\r\n<br />\r\n\"Urgently Opening for Sr. Executive Microsoft Sales SBD - CTM (MS Sales)â€<br />\r\n<br />\r\n <br />\r\n<br />\r\nCompany Name: <br />\r\n<br />\r\n E. S. P. L. is one of the leading end-to-end IT consulting and solution providers in the country. In the last 25 years it has evolved from a value added partner for software products into one of the trusted Systems Integrator (SI) with an ISO 9001:2008 certification in India and is presently a Rs. 2 billion organization.<br />\r\n<br />\r\n <br />\r\n<br />\r\nExperience: - Min 3 to 7 Years <br />\r\n<br />\r\n <br />\r\nJob Position:- Senior Executive in Microsoft SBD - CTM<br />\r\n<br />\r\n <br />\r\n<br />\r\nJob Location: - Malad, Mumbai.<br />\r\n<br />\r\n<br />\r\nCTC: - 6 LPA - 8 LPA (Depending upon Experience & knowledge.) <br />\r\n<br />\r\n <br />\r\nEducational Qualification and yrs of Experience:-<br />\r\n<br />\r\n Graduates or higher with good academic record and preferably with Science in Junior College with min of 3 to 6 years of experience with at least 3.5 years in the MS business. <br />\r\n<br />\r\n <br />\r\n<br />\r\nJob Role & Responsibilities:<br />\r\n<br />\r\n Brief Job Description: What activities the job/ role entails:-<br />\r\n<br />\r\n    Responsible for managing and retaining revenue in MS defined CTM Accounts) accounts in the West region. <br />\r\n    Maximizing the revenue for the region specifically in the Cloud offerings of O365 and Azure<br />\r\n    Developing account management strategies to support growth and increase customer goodwill. Strengthening customer relationships.<br />\r\n    Responsible for farming the accounts to get a greater share of the wallet.<br />\r\n    Work in close alignment with CTM patch Managers at MS <br />\r\n<br />\r\nJob Specification: What skills, knowledge, attributes etc the candidate should possess:- <br />\r\n<br />\r\n    Strong Account management skills<br />\r\n    Good understanding of MS cloud offerings<br />\r\n    Must have spent at least 2 years as Hunter<br />\r\n    Should not have more than 3 job changes in his job career span<br />\r\n    Strong oral & written communication skills<br />\r\n    Should have worked in Mumbai region during his sales tenure<br />\r\n<br />\r\n <br />\r\n<br />\r\nIf you are interested and suitable to this profile, job location and salary package, please do send your updated CV Word Format Mark your email to HR Monali - Email: resume@vnt-s.com with subject â€œApplied for Senior Executive in Microsoft SBD - CTM at Job Location:- Malad Mumbaiâ€ <br />\r\n<br />\r\n <br />\r\n<br />\r\nWith the Following Details:-<br />\r\n<br />\r\nÂ· Relevant Exp.:- <br />\r\n<br />\r\nÂ· Current Salary:-<br />\r\n<br />\r\nÂ· Expected Salary:-<br />\r\n<br />\r\nÂ· Notice Period:-<br />\r\n<br />\r\n <br />\r\n<br />\r\nRegards,<br />\r\nHR â€“ Monali.<br />\r\n<br />\r\nresume@vnt-s.com<br />\r\n<br />\r\nVNT-Solutions<br />\r\n<br />\r\nLandline No.:- 02241239713 <br />\r\n<br />\r\n<br />\r\nMobile No.:- 7718808918 / 7 / 6<br />\r\n<br />\r\n <br />\r\n<br />\r\n <br />\r\n<br />\r\n**Would request and appreciate, if you forward this mail to your friends, and let them know about this opportunity**<br />\r\n<br />\r\n <br />\r\n**PLEASE IGNORE IF THIS REQUIREMENT IS DIFFERENT FROM YOUR CREDENTIALS**', '    Company Name: VNT solutions<br />\r\n    Email: resume@vnt-s.com<br />\r\n    Telephone: 7718808917', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '22 March, 2017', '2017-03-22', 56, '2017-03-22 01:36:12', 'IN', 'Y', '', '', '', ''),
(51142925, 74820, 'Systems Analyst', 'C-Byte Company, Inc.', '', '', '90', '12 Jun, 2017', '2', '5', 'Full-Time', '', '', '', '', '12', 'US', '', '', 'Los Angeles, CA', 'technical or sales support, or systems engineering capacity', '', '41', '36', '', '', '', '', '', '', 'Responsible for pre-sales technical support of company products. In partnership with sales teams, communicates the technical advantages of C-Byte products. Persuades customer that C-Byte can technically understand, define and provide the IT solution(s) that meets the customer\'s strategic needs. Organizes and solidifies requirements, ideas and technologies into a definition of a deliverable, such as a quote or proposal, which the customer can purchase. Prepares for presentation the reasoning and validation to substantiate the deliverable definition (e.g. white papers, analysis presentations, testimonials). Identifies, responds to and eliminates customers\' technical objections. Attempts to influence the customer\'s technology standards toward C-Byte\'s architectural vision, usage model philosophy, systems solutions expertise, or platform qualifications. Informs C-Byte management as to customers\' technical needs, requirements, and future vision in order to influence C-Byte\'s future product direction, strategy, programs and resource requirements. <br />\r\n<br />\r\nEducation and Experience: Requires a BS degree, preferably in CS or equivalent. Minimum of six years experience in a complex system environment, of which three was spent (in an UNIX environment) in a technical or sales support, or systems engineering capacity. Solid knowledge of UNIX, C programming, and at least one of the commercial RDBMs required, and an understanding of networking and desktop, client technologies. Strong verbal and written skills. Experience in system integration projects preferred. Must have had direct customer sales experience. <br />\r\n<br />\r\nTo expedite the processing of your resume, please reference 1SQWEB:SSP on your cover sheet or in the subject line of your e-mail.', '', 'Any Postgraduate and Graduate', 'Formal', 'H1B, ANY', 'W2-Permanant', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '14 March, 2017', '2017-03-14', 64, '2017-03-14 05:47:29', 'US', 'Y', '', '', '', ''),
(51146873, 0, 'Docketing Specialist', 'Michael Best', '', '1', '90', '21 Jun, 2017', '3', '5', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Milwaukee, WI', 'Admin - Secretarial and Office Mgmt, Legal - Paralegal and Support Staff, Admin - Data Entry/Billing', '', '22', '141', '', '', '', '', '<br />\r\n<br />\r\nEducation and Experience Requirements:<br />\r\n<br />\r\n    Intellectual Property experience with trademarks preferred<br />\r\n<br />\r\n    Experience in legal industry or professional service industry is preferred<br />\r\n<br />\r\n    Paralegal certificate or Bachelorâ€™s degree is a plus<br />\r\n<br />\r\n', '', 'Michael Best is seeking a Docketing Specialist to join the Intellectual Property group in the Milwaukee office. The Docketing Specialist will work closely with the Docketing Manager and Intellectual Property practice group to analyze, update, and maintain records on docketing software. Michael Best\'s rich tradition and long history is a testament to our ability to remain dynamic and responsive to the significant changes facing business over the past 168 years. Michael Best is committed to professional growth, flexibility and respect for the whole person. Our inclusive culture and collaborative approach will empower you to develop and contribute your professional best.<br />\r\n <br />\r\n<br />\r\nResponsibilities<br />\r\n<br />\r\n    Analyzing, updating, and maintaining records on docketing software<br />\r\n<br />\r\n    Follow strict guidelines<br />\r\n<br />\r\n    Integrate new client intake files<br />\r\n<br />\r\n    Create client reports<br />\r\n<br />\r\n<br />\r\nKnowledge, Skills and Abilities:<br />\r\n<br />\r\n    Detail-oriented, with excellent follow-through<br />\r\n<br />\r\n    Strong project management and prioritization skills<br />\r\n<br />\r\n    Flexibility to appropriately manage multiple tasks simultaneously<br />\r\n<br />\r\n    Demonstrated â€œclient firstâ€ mentality: responsive, flexible, adaptable<br />\r\n<br />\r\n    Proven ability to develop creative solutions<br />\r\n<br />\r\n    Quick learner<br />\r\n<br />\r\n    Superior Microsoft Office skills (e.g., Word, Excel, PowerPoint)<br />\r\n', ' T: 414.271.6560', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '23 March, 2017', '2017-03-23', 55, '2017-03-23 02:43:20', 'US', 'Y', '', '', '', ''),
(51171212, 0, 'Genpact Walk-In for Technical Support Process @ Central Blue Stone Hotel', 'Unitech Bpo Hiring For Paytm', '', '2', '90', '13 Jun, 2017', '0', '1', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Meerut', 'Voice Process Customer Service (Voice) Customer Service (Voice) Customer Service (Non-Voice)', '', '9', '11', '', '', '', '', '', '', 'Genpact Walk-In for Technical Support Process @ Central Blue Stone Hotel<br />\r\n<br />\r\n*HR JAY 8586851320<br />\r\n<br />\r\nDear Candidate,Most Welcome For Domestic And International E-Commerce Companies Flipkart / Snapdeal / Amazon / Paytm / ShopcluesCall .<br />\r\n<br />\r\n* We Have An Urgent Hiring For<br />\r\n1.Customer Care Executive<br />\r\n2.Back Office Executive<br />\r\n3.Verification Department<br />\r\n4.Servey Process<br />\r\n5.Collection Process<br />\r\n6.Inbound Voice Process<br />\r\n<br />\r\n* (No Target)Qualification - Minimum 10th, 12th, Graduation<br />\r\n<br />\r\n* Location - Delhi , Noida , Gurgaon<br />\r\nFreshers And Experience Both Candidates Can Apply<br />\r\n<br />\r\n* Salary - 12k to 15k (Domestic)<br />\r\n<br />\r\n* Salary - 18k to 20k (International)<br />\r\n<br />\r\n* Day And Night Shift Both Are AvailablePart Time And Full Time Both Are AvailableCab Facility Is Available For Both SideFor<br />\r\n<br />\r\n* More Details Call HR JAY 8586851320', 'Email: unitechbpo00@gmail.com<br />\r\nTelephone: 8586851320', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '15 March, 2017', '2017-03-15', 63, '2017-03-15 01:42:39', 'IN', 'Y', '', '', '', ''),
(51195317, 0, ' Service Support Analyst- Senior', 'Technostrides', '', '2', '90', '13 Jun, 2017', '5', '10', 'Full-Time', '', '', '', '', '11', 'US', '', '', 'Raleigh, NC', 'Service Support Analyst- Senior', '', '23', '40', '', '', '', '', '', '', 'Hi ,<br />\r\n<br />\r\n<br />\r\nRole: NCDOT - Service Support Analyst- Senior<br />\r\nDuration:4m<br />\r\nLocation: Raleigh NC<br />\r\nRate:$27/hr<br />\r\nInterview: In Person Only<br />\r\n<br />\r\n<br />\r\nDescription:<br />\r\nThe purpose of this position is to function as a Helpdesk Analyst providing consultation, support, and/or training to clients of computer or other information technology based system.<br />\r\n<br />\r\n<br />\r\nThe purpose of this position is to function as a Helpdesk Analyst providing consultation, support, and/or training to clients of computer or other information technology based system. May provide routine and non-routine support for a broad range of information related technologies, or may provide in-depth support for a narrowly defined area of technology.<br />\r\n<br />\r\nPerforms account administration (create/modify Active Directory accounts, Exchange accounts, NCID accounts and other user accounts<br />\r\nAnalyzes information provided by HR personnel and Client Services technicians in order to create and/or modify accounts for new employees and/or existing NCDOT employees.<br />\r\nIs able to use the information provided to assess data and application access.<br />\r\nIs able to troubleshoot data and application access issues and adjust Active Directory properties as needed<br />\r\n<br />\r\nDistributes Agency-wide email communications and notices related to technology issues<br />\r\nMaintains mainframe printer node configurations<br />\r\nServes as project team member and makes recommendations for routine problem solutions<br />\r\nWork on special projects which require planning of how, when and who the task will be preformed<br />\r\nRefers highly complex or difficult technical problems to a higher-level Technology Support Specialist or other technical resource for that particular technology questions<br />\r\nProvides basic support of hardware, software, applications, NCDOT internal and external users<br />\r\nServes as a technical resource on all of NCDOTâ€™s standard desktop applications to 10,000+ computer users<br />\r\nInstructs users via phone and/or email on the basic functionality of desktop applications<br />\r\nFollows detailed procedures while making recommendations for routine problem solutions<br />\r\nEnters information into call tracking system and monitors to ensure customer service needs are met for all computer and network related issues<br />\r\nCommunicates effectively in oral and written formats<br />\r\nPromotes a positive customer relationship while working with other Helpdesk staff and high level Analyst and Specialists<br />\r\nSchedules and Facilitates daily operations status calls<br />\r\nInitiates Major Incident Process (MIP) communications and conference bridges<br />\r\nMaintains Major Incident Logs<br />\r\nMaintains employee directory<br />\r\n<br />\r\n<br />\r\nSkill Required / Desired Amount of Experience<br />\r\nExcellent verbal and written communication skills Highly desired 5 Years<br />\r\nExperience with HEAT Call Tracking or similar tool, Avaya or similar call distribution tool, Microsoft Windowns, Office 2010/2013/2016, O365. Highly desired 5 Years<br />\r\nExperience and thorough knowledge in Active Directory administration, such as, creation/modification of accounts Highly desired 5 Years<br />\r\nAbility to manage tasks and meet schedules; ability to write technical documentation that is easily understood by staff and customers. Required 5 Years<br />\r\nExcellent Customer service and teamwork. Required 5 Years<br />\r\nAbility to independently resolve routine and some non-routine problems. Ability to solve problems and perform diagnostics on software and/or hardware Required 5 Years<br />\r\nAbility to identify and understand reoccurring problems and recommends solutions. Required 5 Years<br />\r\nAbility to follow complex and/or detailed technical procedures. Required 5 Years', 'Resumes<br />\r\nTechnostrides, Inc<br />\r\nManassas, VA<br />\r\nwww.technostrides.com<br />\r\n +1-703-659-1486', 'MCA/B Tech./ M Tech.', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '15 March, 2017', '2017-03-15', 63, '2017-03-15 01:54:43', 'US', 'Y', '', '', '', ''),
(51433878, 87339, 'Business Development Manager', 'Aricent Organization', '', '', '0', '', '0', '1', 'Full-Time', '', '', '', '', '3', '', '', '', 'Ahmedabad', '', '', '28', 'Select Functional Area', '', '', 'Y', '', 'Education & Experience<br />\r\n Graduate Post Graduate, Diploma, Fresherâ€™s or experienced (1-2 years)<br />\r\n Age (20 - 28 years)', '', '1. We are looking for fresher\'s and experienced for the post of Business Development Manager.<br />\r\n<br />\r\n 2. He/She shall be responsible for getting new business opportunities .<br />\r\n<br />\r\n 3. We have multiple openings at Entry level and Middle level Management. We select our New Joiners as Trainee Managers and Train and Develop them in all functional areas of Business Management.<br />\r\n<br />\r\n<br />\r\n 4. Global Training Module<br />\r\n :(GTM): Trainee Manager => Leader => Team Leader => Assistant Business Head => Business Head<br />\r\n<br />\r\n<br />\r\n ***At the time of your interview a detailed description of your job profile will be explained to you***<br />\r\n', 'ARICENT ORGANIZATION is one of the fastest growing, innovative customer acquisition firm in Ahmedabad. We are associated with a UK based firm headquartered in London with its global presence in 28 countries. We conduct Business Promotion activities for clients in various verticals e.g ITES, Telecommunications, Charities, Entertainment & Insurance to name a few.<br />\r\nEmail: hr.aricentorg@gmail.comTelephone: 9033006262', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '20 October, 2016', '2016-10-20', 209, '2016-10-19 22:01:32', 'IN', 'D', '', '', '', ''),
(51472286, 74820, 'Cloud Messaging Solutions Architect', 'Pyramid Consulting', '', '2', '30', '06 Apr, 2017', '3', '5', 'Contract', 'Open', '1 - 2 Years', '', '', '', 'US', '', '', 'Atlanta, GA or Redmond, WA', 'Cloud Architecture, SMPP, MM1, MM4, MM7, WAP, PAP, RCS ', '', '23', '', '', '', '', '', '', '', 'Senior Architect/Developer with broad array of critical knowledge in Network Messaging, Client-Server Models, Server-to-Server Models, Cloud Architecture, Networking, Security, and Federal Regulatory Compliance. Ability to create complete end-to-end architecture design, addressing call flows, high availability, geo-diversity/redundancy, fault tolerance, etc. 3-5 years of experience in this area required.<br />\r\nCandidates having knowledge/experience in Telecom Networks<br />\r\nExperience with and Strong Knowledge of Messaging Protocols: SMPP, MM1, MM4, MM7, WAP, PAP, RCS Messaging (Pager Message Mode, Large Message Mode, File Transfer, and Chat)<br />\r\nEnd-to-End Solution Architecture/Design (Networking, Capacity Engineering, Traffic Engineering, Systems, etc.).<br />\r\nIndustry Protocols (OMA, GSMA, etc.).<br />\r\nWorking knowledge of Android OS, APKs, debugging and tracing facilities.<br />\r\nExperience with IP Multimedia Subsystem (IMS) and related protocols (SIP, MSRP)<br />\r\nExperience with and Strong Knowledge of OMA NMS (Network Message Store) and NC (Notification Channel) Standards<br />\r\nIf you are interested in this position, Please revert me with details below: <br />\r\nFull Name:                                 <br />\r\nContact Number:<br />\r\nEmail:<br />\r\nVisa Status:  <br />\r\nCurrent Location:  <br />\r\nNotice Period required start the project:<br />\r\nYear of Graduation/Post Graduation:<br />\r\nSkype ID:', 'Prakash Azad<br />\r\nprakash.azad@pyramidci.com ', '', '', 'ANY', 'Corp-Corp, W2-Permanant, W2-Contract, 1099-Contract', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '07 March, 2017', '2017-03-07', 71, '2017-03-07 10:06:47', 'US', 'Y', '', '', '', ''),
(51554640, 0, 'Immediate requirement for PeopleSoft Admin position ', 'Kollasoft', '', '1', '90', '31 May, 2017', '5', '10', 'Contract', '', '3- 6 Months', '', '', '', 'US', '', '1237712', 'Minneapolis, MN', 'unix, oracle, PeopleTools/upgrades/administration.', '', '23', '', '', '', '', '', 'Must have skills : Key skills are strong unix, oracle, PeopleTools/upgrades/administration.<br />\r\nSoft skills and communication extremely important.<br />\r\n<br />\r\nPeopleSoft Administrator<br />\r\nSenior type experience with all facets of upgrades/administration/etc.<br />\r\nKey skills are strong unix, oracle, PeopleTools/upgrades/administration.<br />\r\nSoft skills and communication extremely important.<br />\r\nThey will be supporting 100 environments. Itâ€™s a Peoplesoft app upgrade project. Need People software tools.', '', 'Greetings of the Day.<br />\r\n<br />\r\nThis is Ramkrishna from Kollasoft.Inc working on PeopleSoft Admin Position opened for Minneapolis,MN. Please check the requirement and Let me know if youâ€™re interested and respond with your updated resume & salary billing rates.<br />\r\n<br />\r\nTitle : PeopleSoft Admin<br />\r\nDuration: 6+Months on W2<br />\r\nLocation: Minneapolis,MN<br />\r\nClient : Wells Fargo<br />\r\n', 'Kalyan Sharma<br />\r\nKollasoft<br />\r\nScottsdale, AZ', 'MCA/B Tech./ M Tech.', 'Formal', 'US Citizen, GC, EAD (OPT/CPT/GC/H4)', 'W2-Permanant, 1099-Contract, Contract to Hire', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '02 March, 2017', '2017-03-02', 76, '2017-03-02 03:43:40', 'US', 'Y', '', '', '', ''),
(51607864, 0, 'SENIOR PRODUCT/PROJECT ENGINEER', 'VP TOTAL SOLUTIONS', '', '1', '90', '26 Jun, 2017', '7', '15', 'Full-Time', '', '', '', '', '', 'US', '', '', 'Troy, MI', '(', '', '1', '59', '', '', '', '', 'EDUCATION:<br />\r\nBachelorâ€™s Degree in Engineering, or related field<br />\r\nPrior experience in automotive position, or related field<br />\r\nSKILLS, KNOWLEDGE AND ABILITIES:<br />\r\nProficiency in Microsoft Office<br />\r\nKnowledge of Carpet Manufacturing and Materials<br />\r\nKnowledge of Sound and Acoustic measurement processes<br />\r\nBusiness travel to Asia or Europe (up to 20%)<br />\r\n<br />\r\nCORE COMPETENCIES:<br />\r\nAdaptability/Flexibility<br />\r\nInitiative<br />\r\nIntegrity/Ethics<br />\r\nInterpersonal Skills<br />\r\n<br />\r\nJOB SPECIFIC COMPETENCIES:<br />\r\nBudgets/Cost Control<br />\r\nProblem Solving/Analysis<br />\r\nProduct Knowledge<br />\r\nResults Focus<br />\r\nSense of Urgency<br />\r\nTeamwork<br />\r\n<br />\r\n<br />\r\nThank you,<br />\r\n<br />\r\nTechnical Recruiter<br />\r\nVP Total Solutions<br />\r\n142 W. Second St. Flint, MI 48502<br />\r\nE:<br />\r\nO<br />\r\n<br />\r\nClient : CONFIDENTIAL', '', 'Job Title: Product/Project Engineer<br />\r\nLocation: Troy, MI<br />\r\nDuration: Direct Hire<br />\r\n<br />\r\nOverview<br />\r\nThe Project Engineer is responsible for design, engineering and validation of carpet, acoustic, soft trim and floor mat program. The person is also responsible to support the Operations team to ensure a smooth transition from the Engineering/Pre-production phase into Production startup.<br />\r\nResponsibilities:<br />\r\nDesign and engineer automotive interior carpet, floor mat, soft trim and acoustical projects<br />\r\nAssess design feasibility of acoustic design projects using predictive engineering methods (FEA/CAE/Development test analysis)<br />\r\nCreate Engineering Change documents and communicate with appropriate departments to process changes effectively through our organization<br />\r\nCreate or follow up on mock-up parts and prototypes that simulate the design created<br />\r\nSupport Program Management and attend meetings with information relevant to our projects<br />\r\nCreate engineering presentations, charts and documents with supporting engineering evidence or calculations that meet or confirm specifications<br />\r\nCreate Bills of Materials(BOM), Design Failure Mode and Effects Analysis (FMEA), Process FMEA, Design Verification Plan & Report (DVP&R), open issues and other engineering/PPAP related documents<br />\r\nDevelop testing plans and follow up on test set-ups, confirm test results and provide countermeasure plans for test anomalies<br />\r\nCreate engineering and design standards<br />\r\nEngineer and lead design in 3D CAD systems and create 2D drawings that communicate the engineering criteria and standards for our products<br />\r\nReport changes and change alerts in the appropriate customer system (GMES, Ford WERS, etc<br />\r\nProvide ideas and support all AGM Cost Reduction activities<br />\r\nSupport and document engineering activities per AGMâ€™s APQP process<br />\r\nProvide engineering support and documentation to AGMâ€™s Sales team on new business development activities<br />\r\nWorks with the Quality Department on the development of Operator Instructions as it relates to part assembly, components (BOM), packaging and shipping.<br />\r\nResponsible, along with the quality team, to support and resolve any supplier or customer issues as it relates to production.<br />\r\nSupport and track monthly metric activities<br />\r\nAttend customer meetings<br />\r\n<br />\r\nQUALIFICATIONS:<br />\r\nCandidate must have a desire and ability to learn<br />\r\nIndividual should possess basic understanding of carpet and acoustic design<br />\r\nDemonstrate the ability to create presentations and technical documents ', 'Deep Desai<br /><br />\r\nVP TOTAL SOLUTIONS<br /><br />\r\nFlint, MI<br /><br />\r\nwww.vpts.net<br /><br />\r\n +1-310-895-9014', 'Bachelorâ€™s Degree in Engineering,', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '28 March, 2017', '2017-03-28', 50, '2017-03-28 02:17:53', 'US', 'Y', '', '', '', ''),
(51808646, 0, 'Chartered Accounts (CA) Freshers', 'Wings Techno Solutions Hiring For Wings Techno Sol', '', '1', '90', '05 Jun, 2017', '0', '0', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Bangalore', 'Chartered Accounts General Ledger CA ', '', '1', '1', '', '', '', '', '', '', 'Hiring CA freshers for Accounts & finance <br />\r\n<br />\r\n <br />\r\n<br />\r\nAccounting Specialist:<br />\r\n<br />\r\nEducational Qualification: CA <br />\r\n<br />\r\nTotal work experience: Freshers<br />\r\n<br />\r\nKnowledge in Accounts Payable, Accounts Receivable and General ledger Process<br />\r\n<br />\r\nGood communication skills: written and verbal<br />\r\n<br />\r\nSa1lary: 4Lpa to 6Lpa + Variable & Benefits<br />\r\n<br />\r\n <br />\r\n<br />\r\nFor more details call Manasa 9148049222<br />\r\n<br />\r\nmail to wingstechnosolutions@gmail.com', 'Email: wingstechnosolutions@gmail.com<br />\r\nTelephone: 9148049222', 'CA', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '07 March, 2017', '2017-03-07', 71, '2017-03-07 01:47:58', 'IN', 'Y', '', '', '', ''),
(51822840, 0, 'Business Manager', 'Princeton University', '', '1', '90', '27 Jun, 2017', '4', '10', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Princeton, NJ', 'financial systems.', '', '10', '62', '', '', '', '', '', '', 'Overview Princeton Institute for the Science and Technology of Materials (PRISM) is searching for a Business/Grants Manager with excellent financial and organizational skills. The Business and Grants Manager reports to the Institute Manager and is responsible for oversight of all aspects of financial and grants management. Assists and acts as back-up to the Institute Manager, Finance and Administration on other job related projects and duties as needed.<br />\r\n<br />\r\nResponsibilities Oversight of grants process: pre-and post-award responsibilities including new proposal submissions, monthly forecasting, monitoring and approval of spending, progress reports and sponsored research reporting.Analysis of financial data and preparation of financial information for reports, and oversight of tracking and reconciling accounts.Approval of expenditures in accordance with account restrictions.Oversight and/or approval of all purchases, invoices and travel.Management of departmental credit cards including Concur approval and other expense activity.Mentoring for purchasing coordinator and/or grants assistant manager.Serve as back up to the facility Financial Manager.Work closely with other departments and offices to manage and reconcile financial issues.Attend all relevant training classes and stay current with changes in policies, procedures and processes pertaining to financial management and sponsored research.Other duties as assigned. Qualifications<br />\r\n<br />\r\n    Bachelorâ€™s degree with minimum of 4-6 years accounting, business and grant experience.Working knowledge of federal regulations regarding fiscal management of federal funds.Skilled in financial analysis, accounting procedures and budget reconciliations.Excellent organizational and interpersonal skills.Excellent written and verbal communication skills.Ability to exercise independent judgment to plan and prioritize diverse workload.Excellent data gathering skillsAbility to take initiative, self-motivate and function autonomously.Able to handle deadlines.Strong computer skills: experience with Microsoft Office, excellent skills in Excel.<br />\r\n    Experience with electronic proposal submission systems (i.e. grants.gov, Fastlane), and PRIME Peoplesoft system.<br />\r\n<br />\r\n    Experience in management and administration of sponsored research and grant proposals.<br />\r\n    Prior working experience in higher education.<br />\r\n<br />\r\n    Experience with University financial systems.<br />\r\n<br />\r\nThe final candidate will be required to complete a background check successfully.<br />\r\n<br />\r\nPrinceton University is an Equal Opportunity/Affirmative Action Employer and all qualified applicants will receive consideration for employment without regard to age, race, color, religion, sex, sexual orientation, gender identity or expression, national origin, disability status, protected veteran status, or any other characteristic protected by law. EEO IS THE LAW<br />\r\n<br />\r\nSalary Grade ADM, 050 Standard Weekly Hours 36.25 Eligible for Overtime No Benefits Eligible Yes Essential Services Personnel (see policy for detail) No Physical Capacity Exam Required No<br />\r\nAbout this company<br />\r\nChartered in 1746, Princeton is the fourth-oldest college in the nation. The ambience of its earliest days is palpable in historic landmarks on campus, most notably Nassau Hall, which in 1783 was the temporary capitol of the United States. From such a distinctive beginning grew something greatÃ‚Â­a community of learning that continues to evolve, providing abundant opportunities to talented students from around the world. Today, more than 700 faculty members, who are leaders in their respective disciplines, instruct Princeton\'s 4,600 undergraduate students and 2,000 graduate students. Hailing from all 50 states and more than 60 countries, Princeton\'s students represent a wide variety of economic, racial, ethnic, social, cultural, and religious backgrounds. These students enrich the campus community with their ideas and experiences and, above all, their desire to learn. Teaching and Research Princeton simultaneously strives to be one of the leading research universities and the most outstanding undergraduate college in the world. As a research university, it seeks to achieve the highest levels of distinction in the discovery and transmission of knowledge and understanding, and in the education of graduate students. At the same time, Princeton is distinctive among research universities in its commitment to undergraduate teaching. All faculty members at Princeton are expected to teach as well as engage in scholarly research. The University provides its students with academic, extracurricular, financial, and other resourcesÃ‚Â­in a residential community committed to diversity in its student body, faculty, and staffÃ‚Â­that help them achieve at the highest scholarly levels and prepare them for positions of leadership and lives of service in many fields of human endeavor. Through the scholarship and teaching of its faculty, and the many contributions to society of its alumni, Princeton seeks to fulfill its informal motto: \"Princeton in the Nation\'s Service and in the Service of All Nations.\" Working at Princeton With an overall workforce of 5,500 benefits-eligible employees, Princeton University is the largest private employer in Mercer County and one of the largest in central New Jersey. The employees of Princeton University are one of its most valuable resourcesÃ‚Â­the campus is full of talented and dedicated people who together make important contributions to the life and fabric of the community. The human resources of Princeton are remarkably diverse, including master glassblowers, program and budget analysts, Nobel and Pulitzer Prize winners, skilled office specialists, carpenters, and electricians. Princeton offers competitive salaries and a comprehensive benefits program that is responsive to the needs of its diverse staff. Princeton\'s comprehensive benefits program includes health and life insurance coverage, pension benefits, flexible spending accounts, income protection in the event of short- and long-term disabilities, and benefits for employee education and children\'s tuition grants and loans. A Vibrant Neighborhood The town of Princeton, which has a population of approximately 30,000 residents, has tree-lined streets, specialty shops, restaurants, parks, and a friendly and safe atmosphere. It is located midway between New York City and Philadelphia. An excellent transportation network of bus, rail, and highways puts Princeton within easy reach (an hour or less) of these major urban centers. Princeton\'s main campus consists of more than 6 million square feet of space in 160 buildings on 500 acres. Part of Princeton\'s history as a community is its tradition of serving as a congenial, stimulating haven for study and research for scholars from all parts of the world. Neighbor institutions include the Princeton Theological Seminary and the renowned Institute for Advanced Study. Walking paths and bicycle trails thread through their grounds and by Lake Carnegie, through Herrontown Woods, Marquand Park, and along the Delaware and Raritan Canal. The community offers a resident repertory theater, three orchestras, ballet, chamber music, and several choral groups. Princeton is ideally situated to host traveling art shows, dance and musical groups, and solo performers, in addition to visiting academicians and dignitaries from the world of public affairs. While maintaining its identity as a university town, Princeton\'s location has attracted a number of major corporations that have located primary research or corporate offices in the area. The proximity of scholars, writers, artists, scientists, and business professionals promotes a stimulating intellectual climate.', '', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '29 March, 2017', '2017-03-29', 49, '2017-03-29 07:17:56', 'US', 'Y', '', '', '', ''),
(51869389, 0, 'Sales officer Bank ', 'HR SOLUTION Hiring For HR SOLUTION', '', '1', '90', '27 Jun, 2017', '0', '3', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Noida,', 'profit centre head sales head BU Head vp coo ceo director Business head vice president chief executive officer ', '', '10', '116', '', '', '', '', '', '', 'Walking Interviews for Sales Officer In HDFC bnk.<br />\r\n<br />\r\nDesignation: Sales Officer ( BSO/CSO ) Hdfc  JOb<br />\r\n<br />\r\nLocation - Delhi/Delhi Ncr<br />\r\n<br />\r\nSalary: 15000 to 18000 + Incentives.<br />\r\n<br />\r\n(depend on experience and Interview)<br />\r\n<br />\r\nJob Description:<br />\r\n<br />\r\n1) Ensure quality sourcing of new customer and cross-sell different banking products like Loans, Credit Card and Insurance.        <br />\r\n<br />\r\n2) Generate leads of customer through field activity, direct customer meetings, references,Internet mining & market mapping.<br />\r\n<br />\r\nEligibility:<br />\r\n<br />\r\n1. Any Graduate or Post Graduate.<br />\r\n<br />\r\n2. Experience â€“ 0 to 2+ Yrs (With experience letter)<br />\r\n<br />\r\n3. Age: 20-30 years.<br />\r\n<br />\r\n4. Must have flair in sales & marketing.<br />\r\n<br />\r\n5. Should be a target & result oriented personality.<br />\r\n<br />\r\n6. Should be smart, confident and possess decent personality.<br />\r\n<br />\r\n7. Ability to build and maintain strong relationship with new and existing customers.<br />\r\n<br />\r\nDocuments Needed :<br />\r\n<br />\r\n1. Carry 2 Photographs + Updated Resume.<br />\r\n<br />\r\n2. Carry 10th , 12th , Graduation & PG Original Mark sheet + Two Photocopies each.<br />\r\n<br />\r\n3. Carry One Address Proof (Driving Licence / Voter-ID / Aadhar Card / Ration Card /<br />\r\n<br />\r\nPassport) Original + Two Photocopies.<br />\r\n<br />\r\n4. PAN Card is Compulsory ( Original & Photocopy )<br />\r\n<br />\r\n5. Experience Candidate may bring Appointment letter along with Experience letter or last 3 month Salary Slip/ Bank Statement.<br />\r\n<br />\r\nInterested Candidate Visit For The Interview: <br />\r\n<br />\r\nAT:-Building No B-16 2nd floor community center Block B-1 janak puri new Delhi 110058<br />\r\n<br />\r\nNear janak puri(EAST) metro station<br />\r\n<br />\r\nContact Person: 9818597556 meet HR shweta<br />\r\n<br />\r\n9910188427 / 9818093852<br />\r\n<br />\r\n <br />\r\n<br />\r\n OR SEND CV  hrsolution.shweta@gmail.com', 'Email: hrsolution.shweta@gmail.com<br />\r\nTelephone: 9818597556', 'Bachelor\'s', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '29 March, 2017', '2017-03-29', 49, '2017-03-29 07:32:58', 'IN', 'Y', '', '', '', ''),
