(68241760, 0, 'HR Administrative Assistant', 'QCT, LLC', '', '1', '90', '25 Jul, 2017', '4', '9', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', ' San Jose, CA', ' assistant or HR administrator, Exp with HR Software like HRIS or HRMS, PC literacy, Labor legistion knowledge, BS degree ', '', '21', '62', '', '', '', '', '', '', 'Job Summary:<br />\r\n<br />\r\nHR administrative assistant will perform a variety of personnel-related administrative tasks. This position will support the HR department in duties such as updating HR records and processing employeesâ€™ requests. The HR administrative assistant position requires excellent organizational skills and the ability to handle sensitive information confidentially.<br />\r\n<br />\r\nJob Responsibilities<br />\r\n<br />\r\n    Assists the department in carrying out various human resource programs and procedures for all company employees.<br />\r\n    Maintain employee records (soft and hard copies)<br />\r\n    Update HR databases (e.g. new hires, separations, vacation and sick leaves)<br />\r\n    Assist in payroll preparation by providing relevant data, like absences, bonus and leaves<br />\r\n    Prepare paperwork for HR policies and procedures<br />\r\n    Process employeesâ€™ requests and provide relevant information<br />\r\n    Assist in HR projects, meetings and training seminars<br />\r\n    Assist the Recruiters in scheduling and preparing interviews<br />\r\n    Manage the departmentâ€™s telephone center and address queries accordingly<br />\r\n    Prepare reports and presentations for internal communications as required<br />\r\n<br />\r\n    Performs other related duties as required and assigned.<br />\r\n<br />\r\n    Job Requirements (Includes Education/Years of Experience):<br />\r\n        Proven work experience, 1 -2 years, as an HR administrative assistant or HR administrator<br />\r\n        Hand on experience with HR software, like HRIS or HRMS<br />\r\n            PC literacy and experience with MS Office applications<br />\r\n            Knowledge of labor legislation<br />\r\n            Excellent organizational and time-management skills<br />\r\n            Teamwork skills<br />\r\n            BS degree in Human Resources or relevant field is preferred<br />\r\n<br />\r\n        Physical Demands (Do Not Delete):<br />\r\n<br />\r\n        The physical demands described here are representative of those that must be met by an employee to successfully perform the essential functions of this job.<br />\r\n<br />\r\n        While performing the duties of this job, the employee is frequently required to sit, stand, talk and hear. This position requires the ability to occasionally lift office products and supplies, up to 20 pounds.', 'Bruce Barnwell<br />\r\n<br />\r\n1010 Rincon Circle San Jose, CA, 95131 ', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '10 April, 2017', '2017-04-10', 37, '2017-04-10 05:54:51', 'US', 'Y', '', '', '', ''),
(68252377, 95107, 'Looking for Digital Marketing Executive', 'Innasoft Technologies Pvt Ltd', '', '1', '0', '', '2', '3', 'Full-Time', '', '', '', '', '', '', '', '', 'Hyderabad, ', 'SEO, SMM, Blogs, Metatags, Google Analytics, PPC', '', '9', '36', '', '', 'Y', '', '', '', 'The SEO/SMO Analyst is responsible for implementing SEO and social media strategies for clients. The SEO/SMO Analyst can quickly understand and support initiatives that will contribute to the goals and success of client campaigns. <br />\r\n<br />\r\nKey Functional Areas of Responsibility <br />\r\n<br />\r\nPerform keyword research in coordination with client business objectives to optimize existing content and uncover new opportunities <br />\r\n<br />\r\nProvide SEO analysis and recommendations in coordination with elements and structure of websites and web pages <br />\r\n<br />\r\nProvide recommendations and execute strategies for content development in coordination with SEO goals - general and keyword specific <br />\r\n<br />\r\nHelp to create and support marketing content to socialize and use for social media purposes (e.g. customer videos briefs, customer case studies, blog posts, posts from analysts and customers) <br />\r\n<br />\r\nImplement link building campaigns in coordination with client SEO goals <br />\r\n<br />\r\nAssist in development and execution of communication/content strategies via social communities in coordination with SEO goals <br />\r\n<br />\r\nKeep pace with SEO, search engine, social media and internet marketing industry trends and developments <br />\r\n<br />\r\nResearch and administer social media tools in support of clients- social media strategy <br />\r\n<br />\r\nMonitor and administer web analytics dashboards, reports and key reporting tools, and point out key areas of importance in accordance client goals <br />\r\n<br />\r\nMonitor and evaluate search results and search performance across the major search channels <br />\r\n<br />\r\nCommunication to team and management on project development, timelines, and results <br />\r\n<br />\r\nWork closely with the other team members to meet client goals <br />\r\n<br />\r\nProfessional Skills & Qualifications <br />\r\n<br />\r\n1 - 2 years experience in Search Engine Marketing (SEM) and Search Engine Optimization (SEO) <br />\r\n<br />\r\nProficiency in MS Excel, PowerPoint, and Word <br />\r\n<br />\r\nExperience with website analysis using a variety of analytics tools including Google Analytics as well as internal reporting tool <br />\r\n<br />\r\nExperience working with popular keyword tools (Google, WordTracker, Keyword Discovery, etc) <br />\r\n<br />\r\nExperience working with CMS and building/administering content in CMS environments <br />\r\n<br />\r\nDesired: Knowledge of HTML/CSS and website administrations <br />\r\n<br />\r\nBS/BA degree preferred', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '09 November, 2016', '2016-11-09', 189, '2016-11-09 07:30:02', 'IN', 'Y', '', '', '', ''),
(68384714, 67064, 'Sr.PHP Developer', 'Rajiv Infotech', '', '2', '0', '', '1', '2', 'Full-Time', '', '', '', '', '3', '', '', '', 'bengaluru', '', '', '41', '16', '', '', 'Y', '', '<br />\r\n    Handling clients projects and deliver quality works<br />\r\n    Comfortable in working with any short of team size<br />\r\n    Effort involvement to full fill clients requirement and best deliverables.<br />\r\n', '', 'Sound knowledge or working experience on PHP, ability to work as a team in collaborative environment with Designers, Developers & Testers. Enthusiasm and an interest in all technology.Experience/ knowledge of the full software development lifecycle: from requirements gathering and functional specification will be added advantage.<br />\r\n<br />\r\nRequirements<br />\r\n<br />\r\n    Qualification: BCA, MCA, BTECH, BSC in CSC or IT, MSC in CSC or IT.<br />\r\n    Min work experience 2-3 years<br />\r\n    Strong knowledge in PHP, MySQL, jQuery, Javascript and Ajax<br />\r\n    Codeigniter, CakePHP, Opencart, Magento knowledge (advantage)<br />\r\n    Ability to lead the team<br />\r\n    Good eye to test the whole project<br />\r\n    Ability to give training to junior developer.<br />\r\n    Fast in logic, coding and innovative idea to implement projects according to needs.<br />\r\n', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '28 October, 2016', '2016-10-28', 201, '2016-10-28 06:58:23', 'IN', 'Y', '', '', '', ''),
