(69044887, 72232, 'Online Bidder', 'Coding Xperts', '', '5', '0', '', '10', '20', 'Full-Time', '', '', '', '', '3', '', '', '', 'Mohali', 'Odesk, Freelancer, Guru ', '', '23', 'Select Functional Area', '', '', 'Y', '', '', '', '*Business Analyst - Bidder { Well conversant with Odesk, Freelancer, Guru }', 'Interested Candidates can share their Profile to hr.codingxperts@gmail.com <br />\r\nor contact us - 01725020009. ', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '21 November, 2016', '2016-11-21', 177, '2016-11-20 23:17:48', 'IN', 'Y', '', '', '', ''),
(69051690, 27531, 'Inside Sales executive ', 'Client of Charteredclub.com - Funded Startup', '', '2', '0', '', '1', '3', 'Full-Time', '', '', '', '', '3', '', '', '', 'delhi', 'inside sales, cold calling, real estate sale, business development executive, space selling, ', '', '29', '116', '', '', 'Y', '', '', '', '- Handle all leads calls and customer inquiries<br />\r\n<br />\r\n- Take a consultative approach, and not hard sell<br />\r\n<br />\r\n- Take accountability to manage leads of all size.<br />\r\n<br />\r\n- Own and manage relationships with prospects.<br />\r\n<br />\r\n- To be the first point of contact for all inquiries coming in and be the voice of the company.<br />\r\n<br />\r\nResponsibilities:<br />\r\n<br />\r\n- Handling customer inquiries through inbound calls from various acquisition channels.<br />\r\n<br />\r\n- Prospecting for new customers by making outbound calls (Cold and Inbound) to people who have expressed interest in our services or potential customers.<br />\r\n<br />\r\n- Work towards/maintain 100% building occupancy through achieving booked tour goals.<br />\r\n<br />\r\n- Maintaining leads data and sales records in the CRM.<br />\r\n<br />\r\n- Tracking and reporting sales performance including pipeline and acquisition results on a weekly/monthly-basis.<br />\r\n<br />\r\n- Master companyâ€™s services and offerings to facilitate sales efforts.<br />\r\n<br />\r\n- Owning the relationship with leads and operating under minimal supervision.<br />\r\n<br />\r\n- Execute strategy and process implemented by the manager.<br />\r\n<br />\r\n- Be ready to do anything and everything to help the sales team succeed.<br />\r\n<br />\r\nExperience:  1-3 yearsâ€™ experience in direct sales (Real Estate / Space Selling)', 'If interested , share your updated CV at jobs@charteredclub.com', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '02 November, 2016', '2016-11-02', 196, '2016-11-02 06:25:06', 'IN', 'Y', '', '', '', ''),
(69383012, 0, 'Branch Sales officer - Credit Card Sale (Location - Delhi & NCR )', 'Pankaj Jain. Hiring For SBI CARDS', '', '2', '90', '08 Jun, 2017', '1', '4', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Noida', 'Branch Banking ', '', '10', '', '', '', '', '', '', '', 'Direct Company Interview.<br />\r\n<br />\r\nNO CONSULTANCY CHARGES.<br />\r\nFRESHER AND EXPERIENCE BOTH CAN APPLY.<br />\r\n<br />\r\nVacancy In SBI & OBC Bank For Credit Card Sale Counter.<br />\r\n<br />\r\nInterview Address :- Exit gate no 4 from Subhash Nagar metro station than 3rd floor of central bank of India. Near metro pillar number 484.<br />\r\n<br />\r\nPankaj :- 9310105007 / 8586918739<br />\r\n<br />\r\nJob Profile For BRE & MRE<br />\r\n=) Candidate have to attend walk-in customer and apply credit card for them.<br />\r\n=) Fixed Salary.<br />\r\n=) No Field Work.<br />\r\n=) Sitting Job.<br />\r\n=) Official Work.<br />\r\n=) No Calling Work.<br />\r\n=) Age 19 to 30 Year<br />\r\n<br />\r\nDesignation :-<br />\r\n1. Branch Relationship Executive (BRE) - Salary 12 to 15 CTC<br />\r\n2. Mall Relationship Executive      (MRE) - Salary 12 TO 18 CTC<br />\r\n3. Tele Caller                              - Salary 12 to 13 CTC<br />\r\n<br />\r\n4. TEAM LEADER :-  NEGOTIABLE<br />\r\nNote :- Salary is 100% Fixed + Incentives<br />\r\n<br />\r\nQualification :- 12th, Any Graduate, Post Graduate ( Everyone can apply after 12th passed )<br />\r\n<br />\r\n<br />\r\nLocation :- DELHI & NCR<br />\r\n( NEAR BY TO CANDIDATE LOCATION )<br />\r\n<br />\r\nPankaj :- 9310105007<br />\r\nRohit   :- 8586918739', 'Location :- DELHI & NCR<br />\r\n( NEAR BY TO CANDIDATE LOCATION )<br />\r\n<br />\r\nPankaj :- 9310105007<br />\r\nRohit   :- 8586918739<br />\r\nEmail: resume.sspl@gmail.com<br />\r\nTelephone: 9310105007', 'Graduate', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '10 March, 2017', '2017-03-10', 68, '2017-03-09 21:11:07', 'IN', 'Y', '', '', '', ''),
(69425718, 74820, ' Sr. Tibco Developer', 'Sarisys', '', '', '30', '04 Apr, 2017', '4', '6', 'Contract', 'Open', '2+ Years', '', '', '', 'US', '', '', 'Saint Louis, MO', 'TIBCO', '', '23', '', '', '', '', '', 'TIBCO BW 5.X<br />\r\nTIBCO BE 5.X<br />\r\nTIBCO Streambase<br />\r\nTIBCO Live Datamart<br />\r\nREST service development (using TIBCO BW)<br />\r\nTIBCO SpotFire', 'NO H1-B', 'Understands application architectures and has good command over module platforms<br />\r\nCan convert business requirements into a design and has the ability to see through the modular issues<br />\r\nCan independently handle modular designs and can also do technical design work<br />\r\nWorked with onsite/offshore model and play the role of module lead<br />\r\nParticipates in architecture and design of solution; leads module level design and implementation; Maps the project life cycle with the project manager<br />\r\nManages the technical rollout and post-deliverable technical strategy<br />\r\nResponsible for working with Project manager to set and review overall quality of deliverables<br />\r\nA person should have at least 60-70% of TIBCO â€œdevelopmentâ€ experience. Not a support experience with minor enhancement work.<br />\r\nShould have Web Service development experience.', '', '', '', 'US Citizen, GC', 'W2-Contract, 1099-Contract', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '05 March, 2017', '2017-03-05', 73, '2017-03-04 14:57:17', 'US', 'Y', '', '', '', ''),
(69460084, 0, 'Software Quality Assurance Tester-Ludhiana', 'Bhatia Consultancy Services.', '', '2', '90', '25 Jun, 2017', '1', '2', 'Full-Time', '', '', '', '', '', 'IN', '', '', 'Ludhiana', 'Software Quality Assurance Quality Assurance SDLC Software Quality Assurance Testing ', '', '23', '52', '', '', '', '', '', '', 'position: Software Quality Assurance Tester-Ludhiana<br />\r\nQualification: MCA/BCA/B Tech<br />\r\nExperience: Minimum 1 yearexperience In IT company as tester.<br />\r\nJob Description<br />\r\nSend me Jobs like this<br />\r\n1 Should have taken training in software testing<br />\r\n2 Understanding of testing methodologies, SDLC and STLC<br />\r\n3 Evaluate manual or automated test cases and report test results<br />\r\n4 Evaluate manual test cases and report test result.<br />\r\n5 Good English<br />\r\n<br />\r\n <br />\r\n<br />\r\nFor Details, Contact:<br />\r\n<br />\r\nBhatia Consultancy Services<br />\r\n<br />\r\nPunjab', '    Company Name: Bhatia Consultancy Services.<br />\r\n    Company Description:<br />\r\n<br />\r\n    Bhatia Consultancy Services <br />\r\n<br />\r\n    Punjab<br />\r\n<br />\r\n    9501552350<br />\r\n<br />\r\n    bhatiaconsultancy@rediffmail.com<br />\r\n<br />\r\n    www.placementagency.co.in<br />\r\n    Email: info@placementagency.co.in<br />\r\n    Telephone: 9501552350', 'B-tech(mech/EEE/civil/ETC/CSE)', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '27 March, 2017', '2017-03-27', 51, '2017-03-27 02:16:02', 'IN', 'Y', '', '', '', ''),
(69688985, 31750, 'Quality Control', 'Valuepoint Knowledgeworks', '', '5', '0', '', '0', '0', 'Full-Time', '', '', '', '', '3', '', '', '', 'banglore', 'quality check, proof reading, proof reader,  quality analysis, language editing, content editing,proofer', '', '31', 'Select Functional Area', '', '', 'Y', 'Incentives/Performance Rewards/referral bonus/perks', 'We have an immediate opening for QC Executive Health in Bangalore<br />\r\n<br />\r\nEducation:-<br />\r\n* Bachelor/Master Degree in Science<br />\r\n<br />\r\nDescription:<br />\r\nPerform complete Quality check on all types of document to ensure that there are no missing/incorrect translations in the translated documents and to ensure zero defects, client satisfaction and contributing to continual improvement.R&R:-<br />\r\nTo perform a Quality check on all types of document related to Health Care to ensure that the translated file is complete (with no missing translations or others as applicable) and in accordance with the client requirement.<br />\r\nEnsuring that there are no missing translations in the translated file.<br />\r\nChecking target document accuracy with respect to source document in terms of context, grammar, flow of language for Foreign> English documents.<br />\r\nResending the files to the translator in case of any clarifications.<br />\r\nSharing feedback to the translators on their quality of work.<br />\r\nPerforming a final check on the document from the formatting point of view in order to meet the client requirements.<br />\r\nConverting the document to PDF<br />\r\nTranslator evaluation for new translator (by referring to the already approved<br />\r\ntranslated content) & suggesting whether they can be empanelled', '', 'To perform a Quality check on all types of document related to health to ensure that the translated file is complete (i.e no missing translations or others as applicable) and in accordance with the client requirement.', 'Send your resume to shailaja.h@knowledgew.com OR call on (080)30752044 / +91 95387 77904', 'BSci.(Biotechnology), BE/BTech(Biotechnology), MSci(Biotechnology), B.Pharmacy, M.Pharmacy,Health care, Life Science,', 'Formals', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '11 November, 2016', '2016-11-11', 187, '2016-11-11 03:30:25', 'IN', 'Y', '', '', '', ''),
(69800770, 74820, 'Technical Systems Analyst', 'City National Bank', '', '', '90', '12 Jun, 2017', '2', '5', 'Full-Time', '', '', '', '', '11', 'US', '', '', 'Los Angeles, CA', 'Knowledge of Windows, MSOffice, MS Project, Visio, Word, Excel, Project planning skills', '', '23', '123', '', '', '', '', 'Skills and Knowledge: <br />\r\nBachelor\'s Degree or equivalent related experience.<br />\r\nBroad knowledge and understanding of IS functions required<br />\r\nIdeal candidate has a track record of meeting deadlines and delivering high quality results. Self-motivated, with ability to work on two or more projects/tasks with moderate direction, and apply good judgment and decision-making skills.<br />\r\nMust have thorough knowledge of Windows, MSOffice, MS Project, Visio, Word, Excel.<br />\r\nExcellent project planning skills.<br />\r\nDemonstrated ability to creatively design solutions to problems.<br />\r\nStrong organizational and analytical skills.<br />\r\nExcellent verbal and written communication skills.', 'This preceding job description has been designed to indicate the general nature and level of work.', 'The Technical Systems Analyst conducts systems and needs analysis in an effort to ensure that technology solutions align with project objectives. Work directly and collaboratively with business and technical teams to deliver high quality functional IT specifications, gathering and creating specifications from other technical teams. The ideal candidate possesses and routinely provides broad knowledge on a wide range of technologies. This role requires an individual who has the ability to gather and document system requirements and translate the information collected to technology requirements including scoping documents and technical specifications.', '', 'Minimum 3 years of experience in a Technical or Business Analyst role', 'Formal', 'ANY', 'W2-Permanant', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '14 March, 2017', '2017-03-14', 64, '2017-03-14 05:24:48', 'US', 'Y', '', '', '', '');
INSERT INTO `jobs` (`jobid`, `uid`, `job_title`, `company_name`, `about_company`, `vacancies`, `jobs_active`, `job_expiry`, `work_experience_min`, `work_experience_max`, `job_type`, `contract_rate`, `contract_duration`, `internship_salary`, `internship_duration`, `salary`, `job_country`, `job_state`, `job_city`, `location`, `key_skills`, `job_url`, `industry`, `functional_area`, `youtube_url`, `telecommute`, `security_clearance`, `benefits`, `requirements`, `instruction`, `description`, `how_apply`, `academic_degree`, `dress_code`, `WorkAuthorize`, `PreferredEmployment`, `us_citizen`, `gc`, `ead`, `h1b`, `corp_corp`, `w2_permanant`, `w2_contract`, `1099_contract`, `contract_hire`, `date`, `count_date`, `days_ago`, `datetime`, `country_from`, `status`, `facebook_url`, `twitter_url`, `gplush_url`, `message`) VALUES
(69858767, 0, 'JDEdwards Business Analyst - JDE HR / Payroll modules', 'Tech Locators,', '', '1', '90', '25 Jul, 2017', '5', '10', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Sylmar, CA ', ' HR, HCM, Human Capital Management, Payroll, \"Business Analysis\", Business Analyst, JD Edwards, JDE, JDEdwards, One World, OneWorld, JDE EnterpriseOne', '', '6', '94', '', '', '', '', '', '', '<br />\r\n<br />\r\nMulti-billion dollar, nationwide company is looking for an above average JD Edwards HR and/or Payroll Business Analyst (IT) to develop their HCM module to its full potential and support the users at their various divisions. Company has been in business over 100 years, continues to be successful, and is growing! No lay-offs here.<br />\r\n<br />\r\nNote: This is a full-time, permanent positon with all the benefits, and their payroll is done in-house, not through a 3rd party.<br />\r\n<br />\r\nREQUIREMENTS:<br />\r\n<br />\r\n* Seasoned IT Business Analyst with JDEdwards experience. JDEdwards EnterpriseOne preferred.<br />\r\n<br />\r\n* Analysis, design and configuration of JDE\'s HR and/or Payroll module.<br />\r\n<br />\r\n* Understanding of JDE Table Structures to create functional designs for reports, conversions and integrations<br />\r\n<br />\r\n* Strong understanding of the SDLC from design to production support.<br />\r\n<br />\r\n* Strong customer services skills, organizational management and above average communication skills<br />\r\n<br />\r\n* Solid understanding of business practices with fundamental conceptual understanding of project management methodology<br />\r\n<br />\r\n* BA/BS degree preferred<br />\r\n<br />\r\n<br />\r\n<br />\r\nPlease submit your resume in Microsoft Word format with a completed questionnaire.<br />\r\n<br />\r\nIf you have any questions, please include them with your ad response.<br />\r\n<br />\r\nSorry, we are unable to accept third party resumes or sponsor H1B candidates at this time.<br />\r\n<br />\r\nKey: PR, Human Resources, HR, HCM, Human Capital Management, Payroll, \"Business Analysis\", Business Analyst, JD Edwards, JDE, JDEdwards, One World, OneWorld, JDE EnterpriseOne, \"Oracle EnterpriseOne\", \"Oracle E1\", E1, Los Angeles County<br />\r\n<br />\r\nPlease submit your resume in MS Word Document format. Local candidates preferred. Sorry, we are unable to sponsor H1B candidates or accept 3rd party candidates at this time.<br />\r\n', '', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '17 April, 2017', '2017-04-17', 30, '2017-04-17 05:56:18', 'US', 'Y', '', '', '', ''),
(69869087, 0, 'Technical Sales (voice)', 'SRK Menpower', '', '1', '90', '06 Jun, 2017', '0', '5', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Delhi', 'customer care international b.p.o ', '', '9', '11', '', '', '', '', '', '', 'Dear candidates<br />\r\n<br />\r\nWe are hiring for technical sales for paharganj location us ,u.k processes salary no bar for right candidate<br />\r\n<br />\r\nCall 9716687924<br />\r\n<br />\r\nOr mail sumantsharma60 @gmail.com<br />\r\n<br />\r\nSalary no bar for right candidates<br />\r\n<br />\r\nLocation paharganj', 'Email: sumantsharma60@gmail.com<br />\r\nTelephone: 9716687924', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '08 March, 2017', '2017-03-08', 70, '2017-03-08 03:47:46', 'IN', 'Y', '', '', '', ''),
(69895163, 0, 'Executive Assistant', 'Penrod', '', '2', '90', '21 Jun, 2017', '1', '5', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Milwaukee, WI', 'Admin - Secretarial and Office Mgmt, Admin - Receptionist/Clerical, Admin - Data Entry/Billing', '', '22', '62', '', '', '', 'Penrod offers its employees a creative and fast-paced working environment. We differentiate ourselves by hiring people who can grow with our company. We employ some of the brightest minds in the Midwest and invest in their personal growth, while avoiding politics.<br />\r\n <br />\r\n <br />\r\n<br />\r\nPenrod is a high-paced, self-driven, highly inclusive culture.<br />\r\n <br />\r\n <br />\r\n<br />\r\n    Flexible work arrangement.<br />\r\n    Casual dress at the office. Shorts and sandals are encouraged.<br />\r\n    Work/life integration.<br />\r\n    100% covered monthly employee premium for Health and Dental plan with Vision discount.<br />\r\n    Unlimited PTO and 10 day company holidays each year.<br />\r\n    Company outings, lunches, and happy hours.<br />\r\n    An open-concept office environment (no Dilbert-like cube farms).<br />\r\n    Personal workspaces include multiple LCD monitors and a Herman Miller chair.<br />\r\n    In-office recreation includes Ping Pong and video games.<br />\r\n    Kitchen stocked with snacks and beverages, including Keurig coffeemaker.<br />\r\n    100% coverage of expenses related to certification, testing, preparation, and exam fees.<br />\r\n    Free parking or transit to our unique office in the Historic Third Ward.<br />\r\n<br />\r\n <br />\r\n <br />\r\n<br />\r\nJoin a great team; there\'s absolutely no \'dead weight\' here.', 'Please Note:<br />\r\n <br />\r\n <br />\r\n<br />\r\nAbsolutely do not call to check on the status of your resume, you will be disqualified from consideration.<br />\r\n <br />\r\n <br />\r\n<br />\r\nTo all recruitment agencies:<br />\r\n <br />\r\n <br />\r\n<br />\r\nPenrod does not accept agency resumes. Please do not forward resumes to our jobs alias, Penrod employees, or any other company location. Penrod is not responsible for any fees related to unsolicited resumes.<br />\r\nShare<br />\r\n', '', 'Selected Wisconsin\'s â€œ#1 Best Place to Work for Young Professionalsâ€ in 2016!<br />\r\n <br />\r\n <br />\r\nThe Role<br />\r\n <br />\r\n <br />\r\n<br />\r\nPenrod, located in Milwaukeeâ€™s Historic Third Ward, is seeking a Sales Hacker / Hustler to join their rapidly growing team! We\'re looking for an energetic, dynamic, and driven individual with top-notch interpersonal skills for the role of Account Executive.<br />\r\n <br />\r\n <br />\r\n<br />\r\nOur Account Executive serves as a trusted advisor to our clients. This role is ideal for a technical consultant or sales executive with in-depth understanding of sales effectiveness. This position involves travel; willingness to do so is a must. <br />\r\n <br />\r\n <br />\r\nREQUIREMENTS<br />\r\n <br />\r\n <br />\r\n<br />\r\nWhat You Must Do To Be Successful In This Position:<br />\r\n <br />\r\n <br />\r\n<br />\r\n    Selling innovative solutions to new and existing accounts<br />\r\n    Provide dedicated account management to strategic accounts<br />\r\n    Develop and implement programs to improve customer satisfaction<br />\r\n    Cultivating leads through building partnerships with enterprise level decision makers.<br />\r\n    Strategic account planning and management of partner relationships in region<br />\r\n    Engaging companies and leading discussions around business processes<br />\r\n    Become an expert in Penrodâ€™s solutions for businesses of all sizes and adapt recommendations quickly to suit varying client needs<br />\r\n<br />\r\n <br />\r\n <br />\r\n<br />\r\nWhat Skills & Experience Weâ€™d Like You To Have:<br />\r\n <br />\r\n <br />\r\n<br />\r\n    Experience in selling professional services or technology solutions<br />\r\n    Excellent communication skills<br />\r\n    Highly motivated by client satisfaction and ability to build long-term advisory relationships<br />\r\n    Ability to lead conversations around vision and innovation<br />\r\n    A knack for complex problem solving and business analysis<br />\r\n    Self-motivated, entrepreneurial, and comfortable dealing with ambiguity<br />\r\n    Ability to effectively prioritize and manage tasks within a fast-paces environment<br />\r\n    Demonstrated ability to work and collaborate within a high-performing team<br />\r\n    A wide degree of flexibility and latitude is expected<br />\r\n    Extremely detail oriented<br />\r\n    Ability to handle stress and last-minute, urgent requests<br />\r\n<br />\r\n', 'Address: 219 N Milwaukee St, Milwaukee, WI 53202, USA<br />\r\nPhone: +1 844-244-4443', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '23 March, 2017', '2017-03-23', 55, '2017-03-23 02:37:56', 'US', 'Y', '', '', '', ''),
