(79903844, 29139, 'Urgently require FACULTY-Accounts/Economics CPT Specific', 'SBioVision Academy', '', '2', '30', '03 Apr, 2017', '1', '2', 'Part-Time', '', '', '', '', 'Industry Standards', 'IN', '', '', 'Kapoorthala, Lucknow', 'Coaching,CPT,Accounts,Economics.', '', '36', '91', '', '', '', '', 'Required languages:<br />\r\nEnglish<br />\r\nHindi', 'Salary:Best in Industry for deserving candidates.', 'This vacancy is on very urgent basis , we need a faculty who is well versed with teaching fundamentals of Accounts& general economics with short tricks & techniques to CPT students.<br />\r\n<br />\r\nDesirable:Qualified CPT<br />\r\n<br />\r\nJob Type: Part-time<br />\r\n<br />\r\nJob Location: Kapoorthala, Lucknow<br />\r\n<br />\r\nRequired education: Any UG/PG<br />\r\n<br />\r\nRequired experience : 1-3 years<br />\r\n<br />\r\nRequired language:Hindi, English<br />\r\n<br />\r\nJob Type: Part-time<br />\r\n<br />\r\nJob Location:<br />\r\n<br />\r\nLucknow, Uttar Pradesh<br />\r\nRequired education:<br />\r\n<br />\r\nBachelor\'s<br />\r\nRequired experience:<br />\r\n<br />\r\nAccounts: 1 year Teaching: 1 year<br />\r\n<br />\r\nRequired languages:<br />\r\nEnglish<br />\r\nHindi', 'Contact us at:<br />\r\nSBioVision Academy Pvt. Ltd<br />\r\n+91-73799-94440<br />\r\n+91-74088-88112<br />\r\nEmail us at: contact@sbiovisionacademy.com', 'Required education: Any UG/PG', 'Formals', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '04 March, 2017', '2017-03-04', 74, '2017-03-04 01:16:31', 'IN', 'Y', '', '', '', ''),
(79958156, 74820, 'Regulatory Affairs', 'Mankind Pharma Ltd.', '', '', '90', '12 Jun, 2017', '1', '3', 'Full-Time', '', '', '', '', '3', 'IN', '', '434079', 'Delhi', 'Regulatory Affairs, ra, dra, quality assurance, quality analyst, r&d, Drug Regulatory, Affairs', '', '31', '100', '', '', '', '', '', 'For more details please go through: www.mankindpharma.com', 'Dossier preparation & filing in Malaysia, South Africa , Brazil, Mexico, CIS, LATAM, African, Asean & other emerging markets, Response to queries within the timelines defined by regulatory authorities, Guidance to manufacturing units/R&D for product development and supporting departments for generation of technical data for dossier filings, well versed with regulatory affairs functioning & updated with the current regulations.', '', 'B.Pharma, M.Pharma', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '14 March, 2017', '2017-03-14', 64, '2017-03-14 04:12:18', 'IN', 'Y', '', '', '', ''),
(80231998, 29139, 'Immediately require FACULTY of Physics/Chemistry/Biology for NEET Courses.', 'SBioVision Academy', '', '5', '30', '03 Apr, 2017', '1', '3', 'Part-Time', '', '', '', '', '', 'IN', '', '', 'Kapoorthala, Lucknow', 'Coaching, Counselling, NEET', '', '36', '96', '', '', '', 'Salary: Best in the industry fro deserving candidate.<br />\r\nCTC upto 2,50,000 pa', 'Required education:<br />\r\n<br />\r\nBachelor\'s<br />\r\nRequired experience:<br />\r\n<br />\r\nTeaching: 2 years<br />\r\nRequired languages:<br />\r\n<br />\r\nHindi<br />\r\nEnglish', 'Qualified relevant entrance exam.', 'Candidates shall be well versed with should be an expert faculty in Physics/Chemistry/Biology for training students for JEE/ NEET.<br />\r\n<br />\r\nSkill Sets:<br />\r\n<br />\r\n> Candidate should have a great passion for teaching with tricks & techniques.<br />\r\n<br />\r\n> Should have excellent problem solving and analytical skills.<br />\r\n<br />\r\n> Must be extremely disciplined/ dependable/flexible .<br />\r\n<br />\r\n> Open to learn and deliver as per requirement.<br />\r\n<br />\r\nSalary: Best in industry.', 'Contact us at:<br /><br /><br />\r\nSBioVision Academy Pvt. Ltd<br /><br /><br />\r\n+91-73799-94440<br /><br /><br />\r\n+91-74088-88112<br /><br /><br />\r\nEmail us at: contact@sbiovisionacademy.com', 'Any Bachelors or Masters', 'Formals', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '04 March, 2017', '2017-03-04', 74, '2017-03-04 00:49:11', 'IN', 'Y', '', '', '', ''),
