(81278376, 0, 'Software Tester', 'Shreeyaan Solusmart Pvt Ltd.', '', '2', '0', '', '0', '1', 'Full-Time', '', '', '', '', '', '', '', '', 'Ahmedabad', ' Testing ', '', '23', '22', '', '', '', '', '', '', 'Experience in STLC (Software Testing Life Cycle) and Verification and; Validation process.<br />\r\nExperience in UAT (User Acceptance Testing) process.<br />\r\nCommunication is must be Good in English (written & verbal)<br />\r\nStrong teamwork skills<br />\r\nServer-side business logic, a sync messaging, multi-threading<br />\r\nStrong algorithm & problem solving skills', 'Email: hr@shreeyaansolusmart.com<br />\r\nTelephone: 9601047877', 'BE/BTech', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '22 February, 2017', '2017-02-22', 84, '2017-02-22 01:43:15', 'IN', 'Y', '', '', '', ''),
(81644487, 71821, 'Customer Service Executive', 'Triaura Solutions Pvt Ltd', '', '', '0', '', '0', '6', 'Full-Time', '', '', '', '', '', '', '', '', 'Bangalore, ', '', '', '9', 'Select Functional Area', '', '', 'Y', '', '', '', 'Hi <br />\r\nGreetings for  the day..!!!<br />\r\nExcellent Job opportunities with  Top  MNC â€¦!!<br />\r\nLocation: Bangalore (white field)<br />\r\nPosition:  customer service executive (Inbound process/BPO)<br />\r\nQualification : PUC, Diploma, Graduation, <br />\r\nSalary: <br />\r\n15000+incentives+bonous  for Fresher and 21000+incentives+bomous for Experience(voice process)<br />\r\ncommunication skills  <br />\r\nâ€¢  English, Hindi, kannada ,(Three languages are mandatory)<br />\r\nBenefits<br />\r\nâ€¢  Two way transportation facility<br />\r\n Interested Candidates Fresher or experience  can connect Call OR Message on 9148598556 OR reach us at ajish.m@triaurasolutions.com <br />\r\n<br />\r\nThanks and Regards ,<br />\r\nAjish<br />\r\n+91 9148598556<br />\r\najish.m@triaurasolutions.com<br />\r\nwww.triaurasolutions.com<br />\r\n', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '02 January, 2017', '2017-01-02', 135, '2017-01-02 07:48:29', 'IN', 'Y', '', '', '', ''),
