(82214868, 0, 'Senior Software Engineer', 'Squareroot Consulting Pvt Ltd.', '', '1', '0', '', '4', '5', 'Full-Time', '', '', '', '', '', '', '', '', 'Bangalore', 'Hibernate', '', '23', '40', '', '', '', '', '', '', 'Work in an agile environment to design and implement new features based on business requirements<br />\r\nHelp other team member in resolving technical issues<br />\r\nHelp with debugging any infrastructure and code related issues in the production environment<br />\r\nProvide estimates for development work<br />\r\nEffectively communicate with team members as well as product management.<br />\r\n<br />\r\nSkills/Experience Requirements<br />\r\nMust be familiar with advanced principles of object oriented analysis, design and programming.<br />\r\nExperience with or exposure to multi-tier website development in a Java/J2EE environment.<br />\r\nExperience with Hibernate, Groovy and Grails a plus.<br />\r\nSound knowledge of relational databases, including schema design and advanced queries. My SQL experience is a plus.<br />\r\nExcellent time management skills and ability to take responsibility for deliverables<br />\r\nAbility to work in a fast-paced, start-up environment<br />\r\nExcellent oral and written communication skills<br />\r\nAbility to work in a team environment', '', 'MCA/B Tech./ M Tech.', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '21 February, 2017', '2017-02-21', 85, '2017-02-21 08:20:57', 'IN', 'Y', '', '', '', ''),
(82369482, 0, 'Administrative Assistant', 'Aerotek', '', '2', '90', '27 Jun, 2017', '1', '4', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Washington, DC', 'please call 888-237-6835 or email accommodation@aerotek.com', '', '31', '62', '', '', '', '', '', '', 'Aerotek is looking for a qualified Administrative Assistant to work for a health care nonprofit in Washington, DC.<br />\r\nA qualified candidate will have:<br />\r\n<br />\r\n    A bachelorâ€™s degree from a 4 year accredited institution<br />\r\n    1-3 yearâ€™s of administrative experience<br />\r\n    Microsoft office experience<br />\r\n<br />\r\n<br />\r\nJob duties:<br />\r\n<br />\r\n    Scheduling<br />\r\n    Meetings coordination<br />\r\n    Calendar Management<br />\r\n    Receptionist duties<br />\r\n    Miscellaneous office duties<br />\r\n<br />\r\n<br />\r\nPlease send qualified resumes to:<br />\r\nHaily Grogan<br />\r\nAbout Aerotek:<br />\r\nOur people are everything. Since 1983, Aerotek has become a leader in recruiting and staffing services by building quality relationships that allow us to place quality people in quality jobs. With over 230 non-franchised offices, Aerotek serves 17,000 clients and 300,000 contract employees every year. To learn more, visit aerotek.com.<br />\r\nThe company is an equal opportunity employer and will consider all applications without regard to race, sex, age, color, religion, national origin, veteran status, disability, genetic information or any other characteristic protected by law.<br />\r\nIf you would like to request a reasonable accommodation, such as the modification or adjustment of the job application process or interviewing process due to a disability, please call 888-237-6835 or email accommodation@aerotek.com for other accommodation options. However, if you have questions about this position, please contact the Recruiter located at the bottom of the job posting. The Recruiter is the sole point of contact for questions about this position. ', 'please call 888-237-6835 or email accommodation@aerotek.com', 'A bachelorâ€™s degree from a 4 year accredited institution', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '29 March, 2017', '2017-03-29', 49, '2017-03-29 06:15:21', 'US', 'Y', '', '', '', ''),
(82406231, 0, 'MCA ,B,TECH FRESHERS TRAINEE PROGRAM', 'Freelancer Meenakshi', '', '2', '', '', '0', '1', 'Full-Time', '', '', '', '', '3', 'IN', '1299', '437026', 'Ghazipur, Noida, Chennai, Bhagalpur, Hyderabad, Gurgaon ', 'DIPLOMA    B.TECH    MCA. BCA   FRESHERS ', '', '23', '29', '', '', '', '', '', '', 'Dear Candidates,<br />\r\n<br />\r\n<br />\r\nGreeting of the day !<br />\r\n<br />\r\nWelcome for fresher as well as experience candidates for B.Tech / DIPLOMA /MCA Profile -0-1 yrs exp.<br />\r\nTELECOM ENG/ RF ENG / FR ENG/ FR /INSTALLATION ENG / BTS<br />\r\n/ DRIVE TEST <br />\r\nJava / ANDROID / PHP / WEB DESIGINING / SEO / IOS / <br />\r\n <br />\r\nINTERVIEW\'S GOING ON<br />\r\nInterview Timing - 11 am to 5 pm<br />\r\n<br />\r\nPosition - <br />\r\nAFTER TRAINEE Salary - 10k to 15k<br />\r\nJob Location - NOIDA sec-18 Near Metro station.<br />\r\nif you want to take more information please visit our office or cont. on the given number.<br />\r\ncont - 08375886834 /09899919372<br />\r\ncont person - Mr. Dinesh /Miss Sandhya<br />\r\n<br />\r\nNote:<br />\r\n<br />\r\nFOR INTERSHIP<br />\r\n<br />\r\nThis job is not for BPO', 'Email: meenahr02@gmail.com<br />\r\nTelephone: 8375886834', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '27 February, 2017', '2017-02-27', 79, '2017-02-27 03:17:55', 'IN', 'Y', '', '', '', ''),
(82541052, 0, 'Hiring for Registered staff Nurse.', 'Thyrocare Technologies Ltd.', '', '2', '90', '21 Jun, 2017', '0', '1', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Navi Mumbai', 'Pharmacy Nuclear Medicine Nursing LMP MS office Pharmacy Nuclear Medicine Nursing LMP MS office ', '', '31', '106', '', '', '', '', '', '', 'Thyrocare Technologies Ltd is hiring for \"Staff Nurse\".<br />\r\n<br />\r\nJob Description:<br />\r\n<br />\r\n    To perform nursing duties : role can be diverse and change<br />\r\n    Supportive to the Nueclear : Nuclear Medicine and PET-CT department<br />\r\n    International Patient Safety Goals<br />\r\n    Educate patients and their carers regarding the procedures<br />\r\n    Check women of childbearing age for LMP, Pregnancy and Breast Feeding<br />\r\n    Check Fingerstick Blood Glucose level<br />\r\n    Alert the clinician regarding IV contrast reactions<br />\r\n    Crashcart maintainance<br />\r\n    Patient Confidentiality<br />\r\n    Follow radiation protection principles covering the staff and patient under the guidance of RSO.<br />\r\n    Routine checking of essential equipment such as resuscitation equipment, crashcart and updating.<br />\r\n    Preparing indent for Clinical Consumables and Pharmacy Consumables<br />\r\n    involve in or initiate audit and research and involve in Phase 1 and Phase2 clinical trials<br />\r\n    Co-ordinate some sessions or clinics to ensure smooth running and continuity of care.<br />\r\n    Liaison with the multidisciplinary team, comprising doctors, physicists, pharmacists, radiographers, technologists and administrative staff for smooth functioning of the dept.<br />\r\n<br />\r\n <br />\r\n<br />\r\nPerson Specification:<br />\r\n<br />\r\n    Essential : expertise in Venepuncture and Cannulation<br />\r\n    To give IV contrast injections and providing medication<br />\r\n    Good communication skill<br />\r\n    MS Office<br />\r\n    Registered nurse<br />\r\n    BLS training and certification<br />\r\n    Preferred : Experience of working in Nuclear Medicine and Radiology : PET and CET<br />\r\n<br />\r\nQualification: Diploma / Course in Nursing.<br />\r\nExperience : 0 to 1 yr<br />\r\nLocation : Navi Mumbai<br />\r\nGender : Male<br />\r\n<br />\r\nCandidates intrested can send their updated resume to hrd@thyrocare.com<br />\r\n<br />\r\n <br />\r\n<br />\r\nWith Regards,<br />\r\n<br />\r\nTeam HR', 'Email: hrd@thyrocare.com<br />\r\nTelephone: 8422849980', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '23 March, 2017', '2017-03-23', 55, '2017-03-23 03:14:31', 'IN', 'Y', '', '', '', ''),
(82572614, 71821, 'Customer service Executive', 'Triaura Solutions Pvt Ltd', '', '100', '0', '', '0', '6', 'Full-Time', '', '', '', '', '3', '', '', '', 'Bangalore, ', '', '', '9', 'Select Functional Area', '', '', 'Y', 'Two Way transportations facility at free of cost +bonous+incentives', '', '', '<br />\r\nHi <br />\r\nGreetings for the day..!!! <br />\r\n<br />\r\nExcellent Job opportunities with one of our client â€¦!! <br />\r\n<br />\r\nLocation: Bangalore (white field) <br />\r\nPosition: customer service executive (Inbound process) <br />\r\n<br />\r\nsalary: <br />\r\nFresher:15000+incentives+bonous<br />\r\nExperience:21000+incentives+bonous<br />\r\n<br />\r\n<br />\r\nCommunication skills :<br />\r\n<br />\r\nâ€¢  Excellent English,  Excellent Hindi and  Kannada ,<br />\r\n<br />\r\nQualification : PUC, Diploma, Graduation,   <br />\r\n<br />\r\n<br />\r\nBenefits :<br />\r\nâ€¢ Two way transportation facility (with in 30 km)<br />\r\n<br />\r\n<br />\r\nInterested Candidates Fresher or experience can connect Call OR Message on 9148598552 OR reach us at karthik.k@triaurasolutions.com <br />\r\nF2F Interview on  Thursday   05/01/2017 at Bangalore (JP Nagar 5th phase ) <br />\r\n<br />\r\nAnd you may refer your friends. <br />\r\nNote: If you find this Job is not suitable for you, please ignore this mail<br />\r\n<br />\r\n<br />\r\nThanks and Regards ,<br />\r\nKarthik.k<br />\r\n+91 9148598552<br />\r\nkarthik.k@triaurasolutions.com<br />\r\nwww.triaurasolutions.com<br />\r\n<br />\r\n', 'Reach us at 9148598552 Or karthik.k@triaurasolutions.com', '10+2 pass Or Diploma pass OR Graduation ', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '02 January, 2017', '2017-01-02', 135, '2017-01-02 07:43:27', 'IN', 'Y', '', '', '', ''),
(82818672, 0, 'Accounting Manager, Multi-Platform Media Company in LA', 'CyberCoders', '', '1', '90', '25 Jul, 2017', '3', '7', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', ' Los Angeles, CA', 'Corporate Accounting, Excel, TV/Movie Production Lifecycle, CPA - Corporate Accounting, Excel, TV/Movie Production Lifecycle, CPA ', '', '2', '1', '', '', '', '', '', '', 'Minimum Required Skills:<br />\r\nCorporate Accounting, Excel, TV/Movie Production Lifecycle, CPA<br />\r\n<br />\r\nIf you are an Accounting Manager with experience in Corporate Accounting and understanding of TV Production Finance, please read on!<br />\r\n<br />\r\nWe are a global multi-platform media company, a leading destination for original programming serving the global Gen Z audience. We\'re a family of complementary brands, including: a global creator community, an influencer talent management company, and we connect our brands with our audience through our brand partnerships division.<br />\r\n<br />\r\nWhat You Will Be Doing<br />\r\n<br />\r\nThe Manager of Accounting role will be a liaison between Corporate Accounting, Corporate Finance, and Production. This individual must have a strong understanding of traditional & entertainment accounting, along with knowledge of production operations and production finance, to drive on-going development of our policies, processes, and reporting to strengthen the internal controls and procedures. This role is fast-paced and dynamic, which requires someone who is a self-starter, independent, and willing to wear multiple hats.<br />\r\n<br />\r\nWhat You Need for this Position<br />\r\n<br />\r\nMust-Have Skills:<br />\r\n- 6+ Years of Corporate Accounting experience (balance sheets, monthly reports, AR/AP)<br />\r\n- TV Production Accounting/Finance knowledge and experience<br />\r\n- Proven ability to lead and manage a team<br />\r\n- Strong systems skills - proficiency in MS Office skills including Word, Excel<br />\r\n- Outstanding interpersonal and communication skills<br />\r\n- Ability to understand and articulate issues using creative, production, or financial context<br />\r\n- B.A./B.S. in Accounting or Finance<br />\r\n<br />\r\nBonus Skills:<br />\r\n- CPA and/or MBA (HIGHLY preferred to have CPA)<br />\r\n- Ease/Vista experience a plusSo, if you are a Manager of Accounting with experience in Corporate & TV Production Accounting, with strong Excel skills, please apply today!<br />\r\n<br />\r\nApplicants must be authorized to work in the U.S.Please apply directly to by clicking \'Click Here to Apply\' with your Word resume!<br />\r\n<br />\r\nLooking forward to receiving your resume and going over the position in more detail with you.<br />\r\n<br />\r\n- Not a fit for this position? Click the link at the bottom of this email to search all of our open positions.<br />\r\n<br />\r\nLooking forward to receiving your resume!<br />\r\n<br />\r\nCyberCoders<br />\r\n<br />\r\n<br />\r\nCyberCoders, Inc is proud to be an Equal Opportunity Employer<br />\r\n<br />\r\nAll qualified applicants will receive consideration for employment without regard to race, color, religion, sex, national origin, disability, protected veteran status, or any other characteristic protected by law.<br />\r\n<br />\r\nYour Right to Work - In compliance with federal law, all persons hired will be required to verify identity and eligibility to work in the United States and to complete the required employment eligibility verification document form upon hire.<br />\r\n<br />\r\nCyberCoders will consider for Employment in the City of Los Angeles qualified Applicants with Criminal Histories in a manner consistent with the requirements of the Los Angeles Fair Chance Initiative for Hiring (Ban the Box) Ordinance.', '6591 Irvine Center Drive<br />\r\nSuite 200<br />\r\nIrvine, CA 92618 <br />\r\n<br />\r\ninfo@cybercoders.com', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '26 April, 2017', '2017-04-26', 21, '2017-04-26 08:09:06', 'US', 'Y', '', '', '', ''),
(82830163, 0, 'Area Credit Manager - (Exp.in Finance Co. or NBFC & Males Only) - Alwar', 'Streamsource Services.', '', '2', '90', '13 Jun, 2017', '2', '5', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Alwar', 'Collection reports Field Inspection Login Disbursement Credit Operations Personal Discussion', '', '10', '1', '', '', '', '', '', '', 'Dear Job Seeker,<br />\r\n<br />\r\n <br />\r\n<br />\r\nWe are looking for the Area Credit Manager (Experienced Only) in Alwar location - Rajasthan. Pleas find the below details.<br />\r\n<br />\r\nJob Description:<br />\r\n<br />\r\nDesignation / Position: Area Credit Manager<br />\r\n<br />\r\nEducation - Graduate in any stream but preferably M.B.A / CA <br />\r\n<br />\r\nExperience- Minimum 2 - 5 years of experience in finance company / NBFC Sector.<br />\r\n<br />\r\nCompensation - Between 25 k - 60 k per month +(Incentives + L.C + Mobile)<br />\r\n<br />\r\nIndustry - NBFC, Banking & Finance<br />\r\n<br />\r\nFunctioning Area - Loans (Business Loans & School Loans)<br />\r\n<br />\r\nAge Bracket 22 to 35 Years<br />\r\n<br />\r\nLocation - Sonipat, Panipat, Jhunjunu, Rohtak, Bhiwani, Sikar, Behror, Nagaur, Dausa, ,churu, Rewari, Mahendragarh, Faridabad, Gurgaon. Two positions and they can be from any of the above 14 locations.<br />\r\n<br />\r\nGender - Male Candidates<br />\r\n<br />\r\nK R A:<br />\r\n<br />\r\nHandling Credit operation from Login to Disbursement.<br />\r\nSupervise the operations team to prepare daily MIS, Collection reports & Policy-Deviation tracking.<br />\r\nVisit the customer at his business & residence to conduct Field Inspection & Personal Discussion. (FI & PD).<br />\r\n<br />\r\n <br />\r\n<br />\r\nPlease apply if you are interested.<br />\r\n<br />\r\n <br />\r\n<br />\r\nNote: It is an urgent requirement. Male Candidates only with relevant experience 2 - 5 years in finance company / NBFC Sector can apply for the above job.<br />\r\n<br />\r\n <br />\r\n<br />\r\nStreamsource Services,<br />\r\n<br />\r\njobs@streamsourceindia.com<br />\r\n<br />\r\n9916906580', 'Streamsource Services,<br />\r\n<br />\r\njobs@streamsourceindia.com<br />\r\n<br />\r\n9916906580', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '15 March, 2017', '2017-03-15', 63, '2017-03-15 01:34:58', 'IN', 'Y', '', '', '', ''),
(83057528, 74820, 'Informatica Developer', 'eTech Inc.', '', '', '30', '27 Mar, 2017', '7', '10', 'Full-Time', '', '', '', '', 'Market', 'US', '2999', '', 'Oakland, ', 'Informatica, ETL', 'https://www.wellsfargojobs.com/job/-/-/1251/4091345', '23', 'Select Functional Area', '', '', '', '', '7+ years of application development and implementation experience<br />\r\nA BS/BA degree or higher<br />\r\n7+ years of development and implementation experience with applications, databases, or a combination of both<br />\r\n7+ years of Informatica experience<br />\r\n5+ years of experience in application automation and integration<br />\r\n5+ years of experience with databases such as Oracle, DB2, SQL server, or Teradata<br />\r\n3+ years of UNIX experience<br />\r\n3+ years of PL/SQL experience<br />\r\n2+ years of RESTful or SOAP web services<br />\r\n2+ years of XML (Extensible Markup Language) experience<br />\r\n2+ years of business continuity planning experience<br />\r\n<br />\r\nGood verbal, written, and interpersonal communication skills<br />\r\nExperience leading projects that require integration of multiple technology systems to deliver new online functionality and user experience<br />\r\nAbility to communicate effectively with a quantitative development team about models and integration strategies<br />\r\nApplication production support experience<br />\r\nFinancial industry experience<br />\r\nWholesale banking experience<br />\r\nCommercial banking experience<br />\r\nKnowledge and understanding of originating, structuring, and executing transactions related to corporate banking or other credit related products for the most critical or complex clients<br />\r\nKnowledge and understanding of data mapping, mining, or modeling<br />\r\nGood quality review skills<br />\r\nGood analytical skills with high attention to detail and accuracy<br />\r\nAbility to understand client concerns, questions, and problems<br />\r\nAbility to understand short and long term costs, benefits, and risks of technical solutions<br />\r\nKnowledge and understanding of project management methodologies: used in waterfall or Agile development projects<br />\r\nAbility to turn preliminary or ambiguous information, ideas, or problems into well defined plans, solutions, and test scripts<br />\r\nAbility to work effectively in a team environment and across all organizational levels, where flexibility, collaboration, and adaptability are important<br />\r\nAbility to work effectively in virtual environment where key team members and partners are in various time zones and locations<br />\r\nAbility to learn and assimilate information from multiple people and sources<br />\r\nGood verbal, written, and interpersonal communication skills<br />\r\nAbility to work effectively under minimal supervision and follow specific guidelines<br />\r\n<br />\r\nOther Desired Qualifications<br />\r\n7-10 years of programming/systems analysis experience and 3-5 years of relevant experience with emphasis in applications and systems engineering development, database and middleware technologies.<br />\r\n5 years of experience in development, maintenance, and enhancement of Informatica Mappings, Work-flows, and processes<br />\r\nMore than 4 years of demonstrated experience with the Informatica suite of products<br />\r\nExperience in data warehouse and data mart environments<br />\r\nExperience in developing and deploying Informatica in Unix and Oracle 11g database environment<br />\r\nSeveral years of experience building and implementing scalable, reliable, and high-performance ETL architectures<br />\r\nAbility to architect an ETL solution and data conversion strategy<br />\r\nProficiency with RDBMS systems, SQL, Oracle PL/SQL, UNIX Shell scripting, and database optimizations<br />\r\nUnderstanding of modern software engineering principles, practices, and systems development methodologies<br />\r\nDemonstrated experience optimizing and troubleshooting poorly performing ETL mappings.<br />\r\nHas expertise in systems analysis, design and a solid understanding of development, quality assurance and integration methodologies.<br />\r\nOversees updating and testing of the business continuation plan (BCP).<br />\r\nSalesforce integration experience<br />\r\n<br />\r\n', 'Flexibility to work in a 24/7 environment, Ability to travel up to 20% of the time', 'The candidate will be involved in developing Informatica Mappings and writing complex Oracle PL/SQL programs. Other tasks involve analyzing transaction errors, troubleshooting issues in the software, developing bug-fixes, involving performance tuning efforts, must have strong Oracle PL/SQL experience - must have strong Oracle database structure creation, modification experience.<br />\r\nAdditional details<br />\r\n<br />\r\nProvides application design guidance and consultation, utilizing a thorough understanding of applicable technology, tools and existing designs.<br />\r\nAnalyzes highly complex business requirements, designs and writes technical specifications to design or redesign complex computer platforms and applications.<br />\r\nProvides coding direction to less experienced staff or develops highly complex original code.<br />\r\nIs an expert technical resource for modeling, simulation and analysis efforts.<br />\r\nVerifies program logic by overseeing the preparation of test data, testing and debugging of programs.<br />\r\nOversees overall systems testing and the migration of platforms and applications to production.<br />\r\nDevelops new documentation, departmental technical procedures and user guides.<br />\r\nHas ability to leads projects, allocate and manage resources and work of less experienced staff if needed.<br />\r\nAssures quality, security and compliance requirements are met<br />\r\nIdeal candidate will be an individual who takes ownership of a process and accountability for its day to day activities, is able to work independently or as part of a team, and seeks to work on a diverse range of programming languages and technologies', '', '', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '27 February, 2017', '2017-02-27', 79, '2017-02-26 11:43:37', 'US', 'D', '', '', '', ''),
(83068081, 0, 'Medical Coding -Wanted Microbiology Biochemistry Bioinformatics 2015 16 17 Grad', 'CORE 2 CODE', '', '2', '90', '14 Jun, 2017', '0', '2', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Thirunelveli', 'Medical coder ', '', '31', '106', '', '', '', '', '', '', 'JobProfile:- Medical Coder<br />\r\nMedical Coding is the process of converting Verbal Descriptions into numeric or alpha numeric by using ICD 10~CM, CPT and HCPCS.<br />\r\nSALARY-12kTO 17k<br />\r\nEXP-0 to 6 ( in any department with age limit 32)<br />\r\nBenefits:<br />\r\n5 Days job,Dayshift ,saturday sunday Leave,Food,Cab/Travel allowance,Certification Provided.<br />\r\nJob Location:<br />\r\nChennai,Coimbatore, Vellore, Trichy, salem, Erode, Tirunellveli,AP,Telungana,Kerala<br />\r\nEligibility<br />\r\nNursing,GNM<br />\r\nZoology<br />\r\nAdvance zoology<br />\r\nBotany<br />\r\nBiochemistry<br />\r\nBioinformatics<br />\r\nBiotech<br />\r\nBiomedical<br />\r\nMicrobiology<br />\r\nNutrition Dietician<br />\r\nEnvironmental science<br />\r\nFood Technology<br />\r\nAgriculture<br />\r\nGenetics<br />\r\nBDS, BPT, BUMS, BHMS, BSMS, BAMS<br />\r\n<br />\r\nCompany-Core2code<br />\r\nContact Person - Vidya Sr.HR<br />\r\nDesignation - Human Resource (Recruitment)<br />\r\nContact Number - 7200273695,8144611699<br />\r\nMail ID-jobs@core2code.in<br />\r\nWebsite-www.core2code.in', 'Email: jobs@core2code.in<br />\r\nTelephone: 7200273695', 'B.E. Biochemistry, B.Sc. Biochemistry, M.Sc. Biochemistry, M.E. Biochemistry', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '16 March, 2017', '2017-03-16', 62, '2017-03-16 04:41:49', 'IN', 'Y', '', '', '', ''),
(83161636, 36909, 'Business Developer', 'Creative Filament', '', '1', '0', '', '1', '2', 'Contract', '', '', '', '', '3', '', '', '', 'Kolkata, ', 'BDM, Business Developer, Online Bidder, bidder, Business, marketing', '', '41', '132', '', '', 'Y', '', '', '', '*** Criteria:<br />\r\n<br />\r\n1) Generate business through online portals, such as Upwork, Freelancer, Guru, PPH or Email Marketing etc.<br />\r\n2) Should have good communication skills both verbal and written.<br />\r\n3) Excellent online bidding skills, Email marketing, cold calling experience to generate leads.<br />\r\n4) Min 1 Year Exp. in online bidding preferred<br />\r\n5) Maintain pipeline of prospects & meeting target on regular basis<br />\r\n6) Perform project analysis & handle full sales cycle<br />\r\n7) Should be online during Working hours over Phone & Skype<br />\r\n8) Candidate must have good knowledge on technical sales<br />\r\n9) Should be from a technical background.<br />\r\n10) Preparing NDA, proposals & presentations to prospects<br />\r\n11) Achieving monthly and quarterly targets<br />\r\n12) Identifying and closing new opportunities(Technical project based on Codeigniter, WordPress, Custom PHP, MySQL, SEO, SMO, PPC, Graphics design, Mobile Application Development etc ).<br />\r\n13) Building and maintaining client relationships<br />\r\n14) Would be responsible for gaining projects from overseas for PHP/MYSQL web development, Mobile Applications, SEO, SMM, Digital Marketing, Banner Design etc.', 'Directly Send your Most Updated CV to - atanu_das1985@yahoo.co.in', 'Bachelor Degree', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '20 October, 2016', '2016-10-20', 209, '2016-10-20 12:34:53', 'IN', 'Y', '', '', '', ''),
(83195454, 0, 'Counsel', 'Plexus Corp.', '', '1', '90', '13 Jun, 2017', '7', '16', 'Full-Time', '', '', '', '', '11', 'US', '', '', 'Neenah, WI ', 'Banking Retail   Finance Banking Operations   Account Management', '', '4', '116', '', '', '', '', '', '', ' 	<br />\r\n<br />\r\nAre you someone who has experience in commercial transactions and contract management? Do you enjoy working with a diverse group of colleagues in an innovative and fast paced environment?<br />\r\n<br />\r\nIf the answer to the questions above is yes, please consider applying for the Counsel role within Plexus.<br />\r\n<br />\r\nThe primary role of Counsel is to support Plexus\' market sector organization in the creation and successful conclusion of customer contracts and commercial transactions. In addition, this position will support the Company on a broad range of corporate matters relating to the operation of Plexus, as assigned. Counsel will actively partner with corporate, international and local colleagues in support of Plexus\' regional and global strategy.<br />\r\n<br />\r\nContract Management:<br />\r\n<br />\r\n    As a critical member of the team, your main responsibility will be to support the commercial contracting process within Plexus by drafting, reviewing and negotiating commercial agreements and supporting commercial transactions relating to the engineering and manufacturing services provided by Plexus.<br />\r\n    You will have solid legal knowledge and technical abilities for contract drafting and negotiation, together with a well-developed business understanding allowing you to quickly identify risk along with the ability to provide direction to the business to mitigate such risks.<br />\r\n    You will be a true business partner, supporting sales, customer management and other functions within the organization on commercial engagements.<br />\r\n    Your knowledge and experience will allow you to continuously improve the commercial contracting process in the assigned sectors to support Plexus global strategy. <br />\r\n<br />\r\nLegal Support:<br />\r\n<br />\r\n    You will also provide legal support and advice to Plexus Management as well as different departments on legal matters and issues arising from the operational business.<br />\r\n    You will provide support to the Sr. Counsel and Asst. General Counsel to ensure continuous legal support to the organization.<br />\r\n<br />\r\nSupport and Collaboration:<br />\r\n<br />\r\n    Collaboration with other Company attorneys and paralegals on legal initiatives will be key.<br />\r\n    You will either take ownership of certain legal initiatives or collaborate and provide input on such initiatives.<br />\r\n    You will contribute to the management and implementation of strategic global initiatives through collaboration, teamwork and project management skills.<br />\r\n<br />\r\nNetworking:<br />\r\n<br />\r\n    This role will give you the opportunity to develop strong relationships with business partners and other internal functions which will help to achieve successful business outcomes.<br />\r\n<br />\r\nSkills and Abilities:<br />\r\n<br />\r\nThe preferred candidate for this role will have a particular set of skills and abilities, including but not limited to:<br />\r\n<br />\r\n    Proven experience of drafting, reviewing and negotiating commercial agreements [this is essential]<br />\r\n    Good strategic thinking, decision-making and problem solving skills as well as business sense and the willingness to be a business partner<br />\r\n    Advanced written and oral communication skills as well as negotiation and intercultural skills<br />\r\n    Self-motivated with the ability to manage multiple priorities<br />\r\n    A \'team player\' with strong interpersonal skills, self-awareness and the ability to evolve in an international environment to develop and maintain close working relationships within the organization<br />\r\n    Excellent work ethic as well as high integrity and loyalty <br />\r\n<br />\r\nEducation and Experience:<br />\r\n<br />\r\n    Juris Doctor<br />\r\n    At least 2 years practicing law<br />\r\n    A minimum of 1 year of commercial contracting experience in a corporate environment is required<br />\r\n    EMS or Defense industry experience is desirable <br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\nAll offers of employment are contingent upon successfully passing a drug screen and upon completion of a confidentiality agreement.<br />\r\n<br />\r\nOur Values and How We Lead behaviors guide our processes. Plexus does not make employment decisions based on race, color, religion, national origin, sexual orientation, gender identity, disability, or veteran status. We are proud to be an Equal Opportunity Employer (EOE) and encourage all to apply today!<br />\r\n<br />\r\nGlobally, our policy is to recruit people from wide and diverse backgrounds. However, certain positions require access to controlled goods and technologies subject to the International Traffic in Arms Regulations (ITAR) or Export Administration Regulations (EAR). Applicants for these positions may need to be \"U.S. Persons,\" which is generally defined as a U.S. citizen, permanent resident (green card holder), or individual granted political asylum.<br />\r\nWorking At Plexus 	Empowering People, Innovating Solutions, Achieving Excellence<br />\r\n<br />\r\nPlexus is a global company that values your growth and development and knows that our success is the direct result of our empowered, hard-working and dedicated people. At Plexus you can push the boundaries of innovation and discover your highest potential. Whether you\'re an experienced professional or skilled manufacturer looking to expand and enhance your career, a recent graduate ready to make an impact or a student eager to gain hands on internship experience, you can make a difference with us.<br />\r\n<br />\r\nAt Plexus we provide opportunities for growth and development at every level and encourage all employees to be leaders. The foundation of our culture is built around Our Values and How We Lead behaviors exemplified by our Plexus People: Customer Focus, Relationships & Teamwork, Integrity, Open Communication, Excellence, Prioritize Our People, Solve Problems, Be Courageous, Be Strategic, and Innovate.<br />\r\n<br />\r\nOur global operations allow us to attract people with broad and diverse backgrounds from all over the world. Discover why more than 12,500 dedicated individuals choose Plexus as the workplace of choice to grow their careers. Apply today!', '', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '15 March, 2017', '2017-03-15', 63, '2017-03-15 02:07:29', 'US', 'Y', '', '', '', ''),
(83205588, 74820, 'Spark Engineer', 'rjtcompuquest.com', '', '6', '30', '08 Apr, 2017', '1', '5', 'Contract', 'Open', '6 - 12 Months', '', '', '', 'US', '', '', 'San Ramon, CA', 'SPARK', '', '23', '', '', '', '', '', '', '', 'For specific Spark skills you will want to look for the following:<br />\r\n<br />\r\nÂ·         Scala or Python (primarily be Scala) language.<br />\r\n<br />\r\nÂ·         Streaming technologies such as MQTT, Kafka, JMS.<br />\r\n<br />\r\nÂ·         Functional programming<br />\r\n<br />\r\nÂ·         DataStreams specifically RDD and DStream abstractions.<br />\r\n<br />\r\nÂ·         Spark Transformations.<br />\r\n<br />\r\nÂ·         Flume<br />\r\n<br />\r\nÂ·         Resource management (Mesos , YARN)<br />\r\n<br />\r\n We are looking for about 6 strong dev engineers that match some of these capabilities:<br />\r\n<br />\r\n1.       Candidates with expertise in distributed systems and server sided software.<br />\r\n<br />\r\n2.       Golang skills is a plus (for 3 candidates), strong grounding in Distributed systems is a pre-requisite.<br />\r\n<br />\r\n3.       Folks that are Apache Contributors and/or committers for some of the data and messaging projects.<br />\r\n<br />\r\n4.       Candidates that have worked on building Platform components such as pub/sub messaging systems/brokers, large scale web-services/micro services, log processing pipelines, Distributed databases/middleware, object stores, worked on/contributed to stream processing frameworks like Apache Storm or Apache Apex etc.<br />\r\n<br />\r\n5.       People with good background of data structures/algorithms and are fluent in writing code.<br />\r\n<br />\r\n6.       Engineers that are hardcore Spark Engineers (3 candidates), that understand how it works internally, its memory model, ways to debug, etc.', 'Deepak Kumar<br />\r\nDirect: 310-448-1044<br />\r\nEmail ID: deepakk@rjtcompuquest.com', '', '', 'ANY', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '09 March, 2017', '2017-03-09', 69, '2017-03-08 13:42:11', 'US', 'Y', '', '', '', ''),
(83222615, 0, 'IT Solutions Director, Sales & Marketing', 'Pernod Ricard USA', '', '1', '90', '14 Jun, 2017', '10', '15', 'Full-Time', '', '', '', '', '12', 'US', '', '', 'New York, NY', 'Demonstrated experience in Marketing & Sales matters', '', '41', '61', '', '', '', 'Benefits<br />\r\n<br />\r\nPernod Ricard USA offers competitive compensation, performance bonuses and domestic & international career development opportunities.<br />\r\n<br />\r\n<br />\r\n*<br />\r\n<br />\r\n* Offers will be subject to United States local terms.<br />\r\n	<br />\r\n<br />\r\nPernod Ricard USA is an Equal Opportunity Employer of Minorities, Females, Protected Veterans, and Individuals with Disabilities', 'Skills / Competencies:<br />\r\n<br />\r\n    Ability to think conceptually and strategically while managing the IT resources of the organization<br />\r\n    Ability to interact with other IT departments that are not direct reports<br />\r\n    Excellent verbal, written, planning, managerial, and organizational skills<br />\r\n    Outstanding aptitude for project management<br />\r\n    Demonstrated experience in Marketing & Sales matters<br />\r\n    Customer oriented<br />\r\n    Coaching and mentoring abilities<br />\r\n    English mandatory', '', 'IT Solutions Director, Sales & Marketing - INF00496<br />\r\nOrganization - Pernod Ricard USA<br />\r\nPrimary Location - US-New York<br />\r\nJob - Information Systems & Technology<br />\r\nJob Type - Regular<br />\r\nJob Posting - Dec 1, 2016<br />\r\nDescription<br />\r\n<br />\r\nPosition Title: IT Solutions Director, Sales & Marketing<br />\r\n<br />\r\nPosition Location: New York, NY (Headquarters)<br />\r\n<br />\r\nPosition Summary:<br />\r\n<br />\r\nThe IT Sales and Marketing Director is responsible for setting the strategic IT direction and related roadmap for the Sales, Marketing and Corporate Communications functions for PRUSA and PRATR. The role oversees all Sales, Marketing and Corporate Communications IT demand and related support, testing and training. The main IT management processes this role oversees are Demand, Project and Portfolio. This role is critical in formulating and communicating the company\'s business technology strategy.<br />\r\n<br />\r\nKey Duties and Responsibilities:<br />\r\n<br />\r\n    Primary IT Demand leader for PRUSA and PRATR<br />\r\n    Defines Sales, Marketing and Corp. Comm. business technology strategy for affiliates<br />\r\n    Organize and manage support of project portfolio (20+ Sales & Marketing applications)<br />\r\n    Oversee Sales (Commercial), Marketing and Corp. Comm. projects from requirement through implementation<br />\r\n    Manage OPEX and CAPEX budgets related to affiliate\'s portfolio<br />\r\n    Interacts with other IT Solutions groups on projects, information exchange, landscape and other cross functional initiatives<br />\r\n    Build and cultivate critical relationships with key business partners and stakeholders<br />\r\n    Manage a team of Project Managers and Business Analysts<br />\r\n    Work closely with technology teams on project deliverables and for sequencing project portfolio<br />\r\n    Manage vendor relationships on assigned projects<br />\r\n    Research Sales & Marketing IT tools and propose innovative IT solutions to the business<br />\r\n    Insures compliance to all internal IT processes<br />\r\n    Play an important role in root cause analysis on data issues and building remediation plans. It is their role to provide the tools that allow the data stewards to measure, monitor, and report on data quality.<br />\r\n    Represent the IT functional/project management group and assists, develop and maintain IT processes and procedures to help govern data;<br />\r\n    Collaborate with data stewards from the business to gain an understanding of business needs related to the quality of information (such as the downstream consequences of bad data and rules that help define the constraints of \"what is good data?\");<br />\r\n    Ensure that best practices regarding data quality incidents are being followed;<br />\r\n    Work closely with the data stewards and business application owners to implement data governance policies and data owner requirements, and carry out the data delivery function;<br />\r\n<br />\r\nKey Competencies and KPIs:<br />\r\n<br />\r\nEducation: Bachelor\'s Degree in science or business / May have post-graduate education or training<br />\r\n<br />\r\nExperience / Background:<br />\r\n<br />\r\n    10-15 years of previous experience in project, program or portfolio management<br />\r\n    Sales & Marketing business experience, as well as extensive previous management of Sales & Marketing projects/systems<br />\r\n    Management experience (projects, processes and people)<br />\r\n    Experience interacting with various corporate profiles: technical personnel, end users, high profile executives, and outside vendors and supplier contracts<br />\r\n    Strong business experience in the Distribution/Consumer Goods industry (preferably in the Spirits Industry)<br />\r\n    Experience in using at least one major BI tool on the market<br />\r\n    Solid knowledge of existing Sales/Marketing tools available on the market (e.g. CRM, Digital solutions...etc.)', '', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '16 March, 2017', '2017-03-16', 62, '2017-03-16 02:55:25', 'US', 'Y', '', '', '', ''),
