(83422891, 0, 'Fresher Software Tester QA Software Quality Assurance', 'Amar Technolabs Private Limited', '', '1', '0', '', '0', '2', 'Full-Time', '', '', '', '', '', '', '', '', 'Ahmedabad', 'Training Testing Manual  Automated Testing', '', '23', '22', '', '', '', '', '', '', 'We Required Software Tester as QA, software Quality Analysis, Assurance as Fresher.<br />\r\n<br />\r\n1. Any Graduation / under Graduation Fresher can apply who wanted to make his Career on IT Sector.<br />\r\n<br />\r\n2. having Good Quality skills over Internet surfing, Computer operating and basic English understanding can apply.<br />\r\n<br />\r\n3. BE/MCA/BCA/ME/Msc IT / Bsc IT / B com anyone can apply.<br />\r\n<br />\r\n4. If having skills over IT Sector as C, C++, HTML, CSS, can understanding IT workflow would be best.<br />\r\n<br />\r\nRole and responsibilities as:<br />\r\n<br />\r\n1. need to test Web application, mobile apps, Software Life cycle Development as Manual and Automation tools.<br />\r\n<br />\r\nApply as Fresher and we provide Training to Fresher and then can directly work with us. apply today limited vacancies onl', 'Email: vipul@amarinfotech.com<br />\r\nTelephone: 07926400298', 'BE/BTech', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '22 February, 2017', '2017-02-22', 84, '2017-02-22 01:41:46', 'IN', 'Y', '', '', '', ''),
(83548014, 13565, 'Asst. Sales Manager', 'Conjugate HR Services ', '', '', '0', '', '0', '1', 'Full-Time', '', '', '', '', '3', '', '', '', 'Pune, ', '', '', '10', 'Select Functional Area', '', '', 'Y', '', '', '', 'Designation â€“ Assistant Sales Manager <br />\r\nRole â€“ Agency development <br />\r\nNeed to build a team of Insurance advisors<br />\r\nDrive business through the team<br />\r\nEnsure team productivity<br />\r\nQualification <br />\r\n10th Pass + any vocational or diploma courses approved by state or central government/AICTE<br />\r\n10th Pass + 12th Pass<br />\r\nGraduate<br />\r\nMust have completed courses successfully<br />\r\nNeed to proved highest  qualification <br />\r\nExperience â€“ 6 months to 2 years<br />\r\nIndustry â€“ BFSI only<br />\r\nCTC-2.4-4.25 Lac P.A (Fixed+Variable) <br />\r\nCANDIDATE ASSESSMENT<br />\r\n<br />\r\nÂ·         Willingness to work in insurance sector.<br />\r\n<br />\r\nÂ·         Basic understanding of financial products specially insurance.<br />\r\n<br />\r\nÂ·         Understanding of local market<br />\r\n<br />\r\nÂ·         Attitude towards employment<br />\r\n<br />\r\nÂ·         Willingness to learn<br />\r\n<br />\r\nÂ·         Communication skills (Regional or any language)<br />\r\n', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '09 January, 2017', '2017-01-09', 128, '2017-01-09 03:33:31', 'IN', 'Y', '', '', '', ''),
(83666229, 0, 'BUSINESS ANALYST/SBA/TEAM LEADER- Indore', 'Indian Advisory', '', '1', '90', '05 Jul, 2017', '0', '4', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Indore', 'Business Analyst Team Leader Equity Shares Equity', '', '10', '96', '', '', '', '', '', '', 'Dear Candidate,<br />\r\n<br />\r\nGreetings from Indian Advisory!!!!!!!!!<br />\r\n<br />\r\nWe are Hiring for the mention below profiles :<br />\r\n<br />\r\nPROFILE:- BUSINESS ANALYST/SBA/TEAM LEADER<br />\r\n<br />\r\n QUALIFICATION:- Minimum Graduates.<br />\r\n<br />\r\nEXPERIENCE:- 0-6 years.<br />\r\n<br />\r\nSALARY:-20-30% hike on current salary<br />\r\n<br />\r\nFOR FRESHERS:- 14K + Incentive<br />\r\n<br />\r\nROLES AND RESPONSIBILITIES OF A BUSINESS ANALYST:-<br />\r\n<br />\r\n1. Convert Leads to Sale (Telephonic).<br />\r\n<br />\r\n2. Communicate to clients the products & services of company.<br />\r\n<br />\r\n3. Will generate the business as per target assigned by reporting authority.<br />\r\n<br />\r\n4. Follow-up with clients for updating products and services.<br />\r\n<br />\r\n5. Customer Relationship Management (CRM).<br />\r\n<br />\r\n6. Identify business opportunities and analyzing sales options.<br />\r\n<br />\r\n7. Assisting in implementing the sales strategy as set by the Senior Manager.<br />\r\n<br />\r\n8. Generate Revenue.<br />\r\n<br />\r\nIF INTERESTED COME FOR THE WALK-INS AT THE BELOW MENTIONED ADDRESS.<br />\r\n<br />\r\nVENUE:- Dhan Trident Block No. B-3 PU-4 2nd-Floor Office No. 232, 233Vijay Nagar -Indore- 452001<br />\r\n<br />\r\nCONTACT:-9301921458,8602035148<br />\r\n<br />\r\nINTERVIEW TIMINGS:-<br />\r\n<br />\r\nMON- FRI:-10a.m.-5 p.m.<br />\r\n<br />\r\nSat:- 10 a.m.-2p.m', 'Email: hr@indianadvisory.com<br />\r\nTelephone: 8602035148', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '06 April, 2017', '2017-04-06', 41, '2017-04-05 22:53:19', 'IN', 'Y', '', '', '', ''),
(83745202, 87339, ' BACK OFFICE DATA ENTRY OPERATOR', 'Airtel', '', '', '0', '', '0', '1', 'Contract', '', '', '', '', '4', '', '', '', 'Anywhere in India', '', '', '9', 'Select Functional Area', '', '', 'Y', 'Preeti (HR) <br />\r\nContact This person 8860998314<br />\r\n<br />\r\n', '', '', 'AIRTEL HIRING FOR BACK OFFICE DATA ENTRY OPERATOR<br />\r\nFOR MALE AND FEMALE CANDIDATES WITH KNOWLEDGE OF <br />\r\nCOMPUTER ', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '17 October, 2016', '2016-10-17', 212, '2016-10-16 18:49:59', 'IN', 'D', '', '', '', ''),
