(92024138, 0, 'Executive Assistant & Office Coordinator - Female', 'Unimax. Hiring For Unimax.', '', '2', '90', '18 Jun, 2017', '10', '15', 'Full-Time', '', '', '', '', '3', 'IN', '', '', 'Faridabad', 'Executive Assistant Executive Secretary EA PA Steno Stenographer Office Coordinator ', '', '10', '64', '', '', '', '', '', '', 'Job Description<br />\r\n<br />\r\nInterview for the post of Female Executive Assistant / Office Coordinator with Reputed company Location at Karol Bagh, New Delhi. Interested send resume at freshjobs@gmail.com & Contact Vinod Jain Ph. 9899546490<br />\r\n<br />\r\nJob Profile :-<br />\r\n â€¢ Candidate shall be Female, Graduate with 10 to 15 yrs of experience as Executive Assistant<br />\r\n â€¢ Require a competent and experienced person, to assist Managing Director in office management work.<br />\r\n â€¢ who can work along in office and client coordination and routine Executive assistant duties,<br />\r\n â€¢ Good at MS Office, and calendar management, well versed in independent correspondence.<br />\r\n â€¢ Salary Rs. 20000 to Rs. 25000 PM.', 'Interested send resume at freshjobs@gmail.com & contact Vinod Jain Ph. 9899546490', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '20 March, 2017', '2017-03-20', 58, '2017-03-20 02:14:58', 'IN', 'Y', '', '', '', ''),
(92174177, 16600, 'DISTRICT MANAGER', 'OCS', '', '10', '0', '', '2', '3', 'Full-Time', '', '', '', '', '4', '', '', '', 'JAMNAGAR, RAJKOT, AHMEDABAD, VADODARA, SURAT, NAVSARI, VAPI', 'CANDIDATE SHOULD HAVE EXPERIENCE IN MICRO FINANCE(MINIMUM 2 YEARS EXPERIENCE REQUIRED)', '', '2', '5', '', '', 'Y', 'BIGGEST BENIFIT IS CANDIDATE WILL GET CHANCE TO WORK IN THE LEADING FINANCIAL COMPANY IN AHMEDABAD WITH BEST SALARY PACKAGE.', '2 YEARS OF EXPERIENCE IN MICRO FINANCE', '', 'â€¢      <br/>\r\n        Branch expansion as per business plan based on proper market survey and <br/>\r\n        analysis of areas business potential.<br/>\r\n																			<br/>\r\nâ€¢       Managing disbursement targets and client acquisition targets.<br/>\r\n																			<br/>\r\nâ€¢       Ensure implementation and compliance of HO policies in branch both in letter and <br/>\r\n         in spirit and in case of any deviation rectify the same at the earliest.<br/>\r\n																			<br/>\r\nâ€¢       To ensure productivity levels are achieved as download by the HO from time to time <br/>\r\n																			<br/>\r\nâ€¢       To ensure all processes laid down by HO are followed regularly by the branches<br/>\r\n																			<br/>\r\nâ€¢       Ensure budgets are maintains and expenditures are minimized where ever it is possible<br/>\r\n																			<br/>\r\nâ€¢       To ensure unproductive staff and activities are identifies and eliminated<br/>\r\n																			<br/>\r\nâ€¢       To ensure portfolio quality of his region remains under control.<br/>\r\n																			<br/>\r\nâ€¢       Delinquency Management as laid down by HO from time to time.<br/>\r\n																			<br/>\r\nâ€¢       Any early indicators of issues are intimated to HO immediately<br/>\r\n																			<br/>\r\nâ€¢       Immediate action is taken to prevent fraud and default.<br/>\r\n																			<br/>\r\nâ€¢       Preventive and proactive measures are taken to ensure  delinquency is kept under control<br/>\r\n																			<br/>\r\nâ€¢       Ensuring 100% center attendance is maintained In his region<br/>\r\n																			<br/>\r\nâ€¢       Ensuring proper documentation is done with all the clients and there is no miscommunication <br/>\r\n         or  commitments is made with the clients <br/>\r\n', 'CALL ON 7227866563 OR SEND CV ON HR1CALLSOLUTIONMEHUL@GMAIL.COM.', 'CANDIDIATE SHOULD BE GRADUATE.', 'NA', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '06 December, 2016', '2016-12-06', 162, '2016-12-06 04:26:30', 'IN', 'Y', '', '', '', ''),
(92228771, 43706, 'SEO Executive', 'Euclide Software Solutions', '', '2', '0', '', '1', '2', 'Full-Time', '', '', '', '', '', '', '', '', 'Mohali(punjab)', '', '', '41', 'Select Functional Area', '', '', 'Y', '', '', '', 'We are looking for experienced SEO executives who have excellent communication skills and<br />\r\n<br />\r\ndedication towards work. The candidates should have all essential knowledge about the following:<br />\r\n<br />\r\n    Candidate must have excellent communication & writing skills for content writing.<br />\r\n    Should be strong with all techniques related to SEO ON PAGE & OFF PAGE optimization methods.<br />\r\n    Social medial marketing.<br />\r\n    Should be well knowledge in keywords research and analysis.<br />\r\n    Creation & timely evaluation of digital marketing strategies to get the best results.<br />\r\n    Proven track record with demonstrated ability to increase traffic.<br />\r\n    Know about social media, blog post etc.<br />\r\n<br />\r\nExperience: 1 to 2 years<br />\r\n<br />\r\nSalary: Negotiable ( No bar for deserving candidates)<br />\r\n<br />\r\nQualification: Graduation', 'E-mail at hr@euclidesolutions.co.in  or Contact at 0172-4661172 ', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '06 December, 2016', '2016-12-06', 162, '2016-12-06 04:01:39', 'IN', 'Y', '', '', '', ''),
(92360265, 0, 'DEVOPS ENGINEER', 'Orcapod software Consulting pvt ltd', '', '1', '90', '25 Jul, 2017', '6', '12', 'Full-Time', '', '', '', '', '4', 'IN', '', '', 'Bangalore', 'W king experience with Unix Linux environments ', '', '23', '56', '', '', '', '', '', '', '1. knowledge of Atlassian Tool stack- Jira, Bamboo, Confluence, BitBucket (Stash)<br />\r\n2. Ansible knowledge. Additionally good to have are : Ruby and python<br />\r\n3. Working experience with Unix / Linux environments.<br />\r\n4. Beneficial to have AWS skills (Mandatory)<br />\r\n5. Good communication , should know what is meant by continuous integration/ continuous deployment / DevOps / Agile', 'Orcapod software Consulting pvt ltd<br />\r\nEmail: priyanka.bhatt@orcapodservices.com<br />\r\nTelephone: 7600083198', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '18 April, 2017', '2017-04-18', 29, '2017-04-18 06:30:25', 'IN', 'Y', '', '', '', ''),
(92379596, 0, 'Data Specialist', 'ECRI Institute', '', '1', '90', '29 Jun, 2017', '6', '13', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Plymouth Meeting, PA', 'administrative functions for the Manager and Project Manager ', '', '28', '140', '', '', '', '', '', '', 'Are you seeking employment with an organization that focuses on improving healthcare, values and respects its staff, and remains staunchly independent and unbiased? Would you like to work in a collegial work environment that encourages teamwork and an open exchange of ideas? Then ECRI Institute\'s 12-acre research facility in Plymouth Meeting, Pennsylvania, is your place to work. ECRI Institute, an independent nonprofit organization that researches the best approaches to improving patient care, offers a relaxed working environment and a competitive compensation package. Our over 400 dedicated full-time staff blend extraordinary scope and depth of clinical, management, and technical expertise with a wide range of experienced healthcare professionals.<br />\r\n<br />\r\nECRI Institute is seeking an entry-level Data Specialist to be responsible for following changes in the medical device industry, particularly capital medical equipment, to help support two databases (one of medical device specifications and one of device manufacturers). The successful candidate will be expected to research and interact with international medical device manufacturers and gather/maintain data on these companies and their respective products via an internal database system. This position is located in Plymouth Meeting, PA.<br />\r\n<br />\r\nDuties and Responsibilities:<br />\r\n<br />\r\nSourcebase<br />\r\n<br />\r\n    Update and add supplier and device listings for the Sourcebase database<br />\r\n    Continually search for new domestic and international suppliers to be added to the database; ensure Sourcebase meets enterprise-wide data needs<br />\r\n    Maintain accurate device listings, trade names, and general profile details for Sourcebase companies<br />\r\n    Perform data proofing of Sourcebase profiles for members\' website data uploads<br />\r\n    Support UMDNS proposals by performing company research<br />\r\n    Assist with revision and possible creation of UMDNS device terms<br />\r\n<br />\r\nHealthcare Product Comparison System (HPCS)<br />\r\n<br />\r\n    Research, edit and write new and updated Product Comparison text and charts following a monthly and as needed production schedule<br />\r\n    Contact U.S. and international companies for model-specific specifications and information<br />\r\n    Data entry skills with a high degree of accuracy and ability to interpret data<br />\r\n    Standardize models in HPCS with our enterprise-wide Products Catalog<br />\r\n    Obtain reviews of reports from ECRI Institute personnel, manufacturers, and any appropriate outside contacts<br />\r\n    Perform literature searches (e.g., library, internet); and, read library-circulated journals to track changes in the medical device industry<br />\r\n    Attend appropriate ECRI Institute seminars, workshops, and equipment demonstrations for continuing education<br />\r\n    Maintain monthly HPCS milestone logs to track progress and aid in time management and organization<br />\r\n    Maintain complete records for all assigned projects, including product specifications, brochures, supplier correspondence, and records of discussions and telephone conversations; organize files according to the HPCS filing system<br />\r\n    Ability to work well with technical and non-technical individuals, has strong interpersonal relations<br />\r\n    Exceptional phone manners and presence<br />\r\n    Detail-oriented with ability to multi-task while meeting deadlines<br />\r\n    Good time management skills are necessary in order to move among the various ongoing tasks assigned and keep them moving toward successful and timely completion<br />\r\n<br />\r\nProduct Catalog<br />\r\n<br />\r\n    Perform administrative functions for the Manager and Project Manager<br />\r\n    Provide data entry support for Product Catalog needs<br />\r\n    Show willingness to take on new tasks or special projects as they arise<br />\r\n    Maintain a positive attitude and work well under pressure <br />\r\n<br />\r\nRequirements:<br />\r\n<br />\r\n    Bachelor\'s degree, preferably in one of the life sciences or technical/scientific writing and 6 months to a year minimum work experience.<br />\r\n    Proficiency in MS Office required in Excel, Word, SharePoint.Access experience a plus.<br />\r\n    Seeking candidates who are critical thinkers with good phone presence and interpersonal skills, effective verbal and written communication skills, exceptional data entry skills with a high degree of accuracy, detail-oriented with proven ability to multi-task while meeting deadlines, can work independently or within a team, manage changing priorities for multiple simultaneous tasks, has strong customer service skills, and has a positive attitude. <br />\r\n<br />\r\nAbout ECRI Institute: ECRI Institute is a nonprofit organization that researches the best approaches to improving patient safety and care. It has its headquarters in Plymouth Meeting, Pennsylvania. We have a diverse working environment that encourages teamwork and an open exchange of ideas. Over 400 dedicated staff blend extraordinary scope and depth of clinical, management, and technical expertise with a wide range of experienced healthcare professionals. Our competitive benefit package for full-time and benefit-eligible part-time employees includes medical, dental, vision, and prescription coverage which begin on the first day of employment.<br />\r\n<br />\r\nFor nearly 50 years, ECRI Institute has dedicated itself to bringing the discipline of applied scientific research to healthcare. Through rigorous, evidence-based patient safety research, ECRI Institute has recommended actionable solutions that have saved countless lives. ECRI Institute is designated an Evidence-Based Practice Center by the U.S. Agency for Healthcare Research and Quality. ECRI Institute PSO is listed as a federally certified Patient Safety Organization by the U.S. Department of Health and Human Services and strives to achieve the highest levels of safety and quality in healthcare by collecting and analyzing patient safety information and sharing best practices and lessons learned. Qualified applicants must be legally authorized to work in the United States.<br />\r\n<br />\r\nECRI Institute is an equal opportunity and affirmative action employer and does not discriminate against otherwise qualified applicants on the basis of race, color, creed, religion, ancestry, age, sex, sexual orientation, marital status, national origin, disability or handicap, or veteran status. If you need a reasonable accommodation for any part of the application and/or hiring process, please contact the Human Resources Department at 610-825-6000.<br />\r\n<br />\r\nTo be considered further for this opportunity interested candidates must apply directly to our website.<br />\r\n<br />\r\n<br />\r\nEOE Minority/Female/Disability/Veteran', 'please contact the Human Resources Department at 610-825-6000. ', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '31 March, 2017', '2017-03-31', 47, '2017-03-31 04:02:04', 'US', 'Y', '', '', '', ''),
(92485356, 0, 'Principal Designer, Footwear, Running', 'Reebok International, LTD', '', '', '90', '02 Jul, 2017', '10', '13', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Canton, MA', 'footwear and graphic designers ', '', '18', '93', '', '', '', '', 'Key Responsibilities<br />\r\n<br />\r\n    You will work as part of a small team including footwear and graphic designers within seasonal design themes to create statement, brand-driving products as well as to challenge and create volume product that keeps the lights burning.<br />\r\n    You will help us identify design collaborations as well as identify opportunities to connect apparel and footwear collections through common elements and stories.<br />\r\n    You will have a solid track record of working successfully on multi-disciplinary design teams. An understanding of performance footwear needs, materials, and be up to speed with new production processes will all be key. We\'re seeking a person with a positive and professional attitude, a strong sense of team spirit, a history of taking initiative, and who shows strong technical capabilities with an understanding of manufacturing - as well as a desire to challenge convention. We are also looking for someone who has experience leading and mentoring junior designers.<br />\r\n    You will travel regularly with the design, development and marketing teams for market/consumer/trend research, as well as seasonally for factory visits and product design follow-up.', '', 'Position Summary<br />\r\n<br />\r\nWe are seeking a Principal Designer for our running footwear design team who has the ability to create compelling designs that sit at the intersection of sport and fashion. You will bring a creative, innovative and proactive approach to the running range as well as have a passion for sport and fashion. In this role, a hyper-awareness of the competitive landscape for running is essential and this includes a strong feel for trends, both product and style. <br />\r\n<br />\r\nKnowledge, Skills and Abilities<br />\r\n<br />\r\n    Strong team player as well as the ability to work independently<br />\r\n    Ability to manage more junior members\' workload and timelines as needed and escalate deadline issues to the Design Manager and Director<br />\r\n    Strong negotiating and influencing skills<br />\r\n    Presentation and Storytelling skills<br />\r\n<br />\r\nQualifications:<br />\r\n<br />\r\n    10+ years of footwear design experience<br />\r\n    Advanced level Adobe Illustrator; Photoshop and 3D software a plus<br />\r\n    Understanding of materials and their application to footwear designs; understanding of material development processes and footwear construction<br />\r\n    Well established knowledge of the footwear manufacturing process<br />\r\n    Bachelor\'s degree in product, industrial, automotive or interior design<br />\r\n    Prior management or mentoring of more junior designers a plus<br />\r\n<br />\r\n<br />\r\nWe are intensely proud of the progress weâ€™ve made creating a diverse and inclusive culture at the adidas Group. But there is always more work to be done. Our goal is an adidas Group where every single person feels welcome. We believe in equality for all, regardless of race, age, abilities, gender, gender identity, sexual orientation, ethnicity or religion. We hold ourselves to the same high standard for all our workplaces around the world, without exception.<br />\r\n', '', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '03 April, 2017', '2017-04-03', 44, '2017-04-03 02:34:34', 'US', 'Y', '', '', '', ''),
(92679878, 0, 'Interim Senior Accountant', 'Baker Tilly Search & Staffing, LLC', '', '2', '90', '20 Jun, 2017', '6', '10', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Waukesha, WI', 'sales, marketing and manufacturing', '', '2', '80', '', '', '', '', '', '', 'Interim Senior Accountant  <br />\r\nOur client in the Waukesha area is looking to add an Interim Senior Accountant to their team. We are looking for a seasoned accountant who is looking for work during the busy season. This is a temporary position (6-8 weeks), but could become permanent for the right person! Interviews will begin immediately.<br />\r\n <br />\r\nRESPONSIBILITIES<br />\r\n <br />\r\n<br />\r\n    Interprets operating results as they affect the organization and make recommendations for improvement<br />\r\n    Support sales, marketing and manufacturing functions with financial analysis<br />\r\n    Participate in strategic planning process and budgeting process<br />\r\n    Develops accounting principles to comply with GAAP, tax requirements, and SOX requirements<br />\r\n    Administers general accounting, internal auditing, and record retention programs while acting as immediate contact with organizationâ€™s independent auditors on accounting matters<br />\r\n    Directs preparation of periodic and yearly financial statements in accordance to GAAP and SEC requirements<br />\r\n<br />\r\n <br />\r\n <br />\r\nEXPERIENCE REQUIRED<br />\r\n <br />\r\n<br />\r\n    Excellent written and verbal communication skills<br />\r\n    Ability to interact with multiple levels of management<br />\r\n    Solid computer skills including proficiency in Excel<br />\r\n<br />\r\n <br />\r\n <br />\r\n <br />\r\nPlease attach your most recent resume and references with your application.<br />\r\n <br />\r\nNote:  Your resume will not be presented to a client without your prior approval.', 'http://www.bakertilly.com/contact/', 'Graduation / PG', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '22 March, 2017', '2017-03-22', 56, '2017-03-22 01:22:00', 'US', 'Y', '', '', '', ''),
(93060859, 0, 'Accountancy/Finance Recruitment Consultant', ' Ruth Moran Consulting', '', '1', '90', '25 Jul, 2017', '7', '13', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'West New York, NJ', '\'recruitment team leader\' \'recruitment regional manager', '', '2', '1', '', '', '', '', '', '', 'Accountancy/Finance Recruitment Consultants NEW YORK OTE Â£200,000 USD<br />\r\n<br />\r\nEXPERIENCE OF WORKING WITHIN RECRUITMENT IS ESSENTIAL.<br />\r\n<br />\r\nOur client is a market leader in its sector. They have experienced over 100% growth year on year Based at their expanding New York site, they genuinely focus on offering a quality service to both clients and candidates, their aim being to provide the best candidates at all times for their clients via both a superb candidate database and a variety of marketing tools As a result of this they have some extremely strong markets and have significant connections to attract the very best.<br />\r\n<br />\r\nFor further information please contact Ruth Moran weekdays 8am-9pm or apply online. You can also visit the Ruth Moran Consulting website.<br />\r\n<br />\r\nRuth Moran Consulting, founded in 1999, is one of the longest established recruitment to recruitment consultancies, working across the UK and Internationally. If you are an experienced recruitment professional looking for advice and guidance about the market and your next role, please do not hesitate to contact us in the strictest of confidence.<br />\r\n<br />\r\nPlease note we are only able to respond to Candidates who have Recruitment Agency experience. If you have not heard from us within three working days, unfortunately, on this occasion, your application has not been successful.<br />\r\n<br />\r\n\'recruitment consultant\' \'senior recruitment consultant\' \'recruiter\' \'senior recruiter\' \'senior consultant\' \'HR\' \'Legal\' \'Accountancy and Finance\' \'Sales and Marketing\' \'Executive Search and Selection\' \'recruitment managerâ€™ \'branch managerâ€™ \'team leader\' \'recruitment branch managerâ€™ \'recruitment team leader\' \'recruitment regional managerâ€™ \'recruitment area managerâ€™ \'divisional managerâ€™ \'area managerâ€™ \'managerâ€™ \'recruitmentâ€™ \'Resourcer\' \'Researcher\'', '', 'Graduation', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '11 April, 2017', '2017-04-11', 36, '2017-04-11 05:24:04', 'US', 'Y', '', '', '', ''),
(93142412, 0, 'Product Manager', 'Verifi, Inc', '', '1', '90', '25 Jul, 2017', '2', '5', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', 'Los Angeles, CA', 'Agile, Business Requirements, Development, Ecommerce, Manager, Management, MS Office, Release, Risk Management, Scrum, Testing ', '', '1', '37', '', '', '', '', '', '', 'Verifi is looking for talented Product Managers to join our company.<br />\r\n<br />\r\nAt Verifi you can have an immediate impact on product creation and client satisfaction. In a company with an energetic environment, you will have an opportunity to work amongst individuals considered to be seasoned experts within the payment industry.<br />\r\n<br />\r\nJoin Verifi and you join the leading solution in the eCommerce marketplace for payment and risk management.<br />\r\n<br />\r\nYour responsibilities will include:<br />\r\n<br />\r\nSupporting the Product team through all phases of the product life cycle including:<br />\r\n* Assisting with defining product features and requirements and user stories<br />\r\n* Actively participating in interviews with internal and external stakeholders to identify business requirements.<br />\r\n* Participating with scrum team(s) through monthly release planning, sprints, retrospectives, Sprint activities, reviewing and acceptance testing user stories for completion.<br />\r\n* Managing backlog of user stories<br />\r\n* Participating in progress monitoring and constant adjustments to fit larger objectives<br />\r\n* Any additional duties as assigned<br />\r\n<br />\r\nYou bring to the table your:<br />\r\n* Bachelor\'s degree in business, engineering or similar fields<br />\r\n* Minimum of 1 year of experience in product management, preferably with payment products<br />\r\n* Previous experience working in an Agile software development process<br />\r\n* Excellent communicator, both oral and written, with ability to build relationships at all levels and in various departments<br />\r\n* Experience writing user stories and working with development teams<br />\r\n* Results oriented, highly self-motivated, and quick-to-learn personality<br />\r\n* Proficiency with MS Office<br />\r\n<br />\r\nWe are located in Los Angeles and offer<br />\r\n* Dynamic, stimulating and open environment with opportunity for personal development.<br />\r\n* Medical, Dental, Vision, Life Insurance<br />\r\n* 401k w/ match, Paid Time Off, and Paid Holidays<br />\r\n* Paid parking and complimentary food<br />\r\n* Socially conscious and community oriented company<br />\r\n* Energized employment filled with activities and events<br />\r\n* Competitive Base Salary, plus bonus, and stock options', 'USA: (323) 655-5789', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '26 April, 2017', '2017-04-26', 21, '2017-04-26 08:07:02', 'US', 'Y', '', '', '', ''),
(93303596, 88320, 'digital marketing', 'aileensoft solution', '', '3', '0', '', '0', '1', 'Full-Time', '', '', '', '', '', '', '', '', 'Ahmedabad, ', '', '', '23', '71', '', '', 'Y', '', '', '', 'we want passionate candidate for digital marketing..', '', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '07 February, 2017', '2017-02-07', 99, '2017-02-07 08:06:15', 'IN', 'Y', '', '', '', ''),
(93342657, 75712, 'Sr Php Developer', 'Staffing Solution and Services', '', '', '0', '', '3', '8', 'Full-Time', '', '', '', '', '4', '', '', '', 'Delhi, ', '', '', '23', '41', '', '', 'Y', '', '  Strong concepts working with Object Oriented Programming.<br />\r\n    Experience working with latest social networking technologies.<br />\r\n    Ability to write W3C standards compliant, cross browser compatible (IE7+, Firefox, Safari, Chrome) front-end markup in XHTML/CSS/AJAX (Jquery).<br />\r\n    Can work with a number of MVC frameworks and write strong, scalable code.<br />\r\n    Ability to write and performance optimize SQL queries for MySQL (PostgreSQL a plus)<br />\r\n    Mobile application development a big plus (iPhone, Android, Blackberry, WinMo)<br />\r\n    Experience programming APIs<br />\r\n    Strong work ethic and ability to construct complex projects quickly<br />\r\n    You should be enthusiastic about your work, results-driven and keen on developing in an agile environment.<br />\r\n    An ardent problem-solver.', '', '  Strong concepts working with Object Oriented Programming.<br />\r\n    Experience working with latest social networking technologies.<br />\r\n    Ability to write W3C standards compliant, cross browser compatible (IE7+, Firefox, Safari, Chrome) front-end markup in XHTML/CSS/AJAX (Jquery).<br />\r\n    Can work with a number of MVC frameworks and write strong, scalable code.<br />\r\n    Ability to write and performance optimize SQL queries for MySQL (PostgreSQL a plus)<br />\r\n    Mobile application development a big plus (iPhone, Android, Blackberry, WinMo)<br />\r\n    Experience programming APIs<br />\r\n    Strong work ethic and ability to construct complex projects quickly<br />\r\n    You should be enthusiastic about your work, results-driven and keen on developing in an agile environment.<br />\r\n    An ardent problem-solver.', '', 'Bachelors', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '24 October, 2016', '2016-10-24', 205, '2016-10-24 05:22:00', 'IN', 'Y', '', '', '', ''),
(93393583, 0, 'Incident Manager - ITIL - $49.30/hr - 3+ month contract', 'Irvine Technology Corporation', '', '1', '90', '25 Jul, 2017', '9', '12', 'Contract', '', '0 - 3 Months', '', '', 'Market', 'US', '', '', ' Santa Ana, CA ', '-Service oriented, adaptable and resilient -Results oriented with personal accountability', '', '2', '100', '', '', '', '', '', '', '3 months+ (contracts usually get extended and there is always a chance for conversion)<br />\r\nPay rate: up to $49.30/hr<br />\r\nLocation: Santa Ana<br />\r\nBackground Check: Criminal, Education, Employment<br />\r\n<br />\r\nDuties:<br />\r\nPrincipal Responsibilities and Accountabilities<br />\r\n-Facilitate the recovery of all Priority 1 & 2 incidents with appropriate reporting and notifications to key stakeholders<br />\r\n-Manage major incidents by providing bridge leadership, focus, and driving service restoration<br />\r\n-Ensure accurate documentation in the Incident Management database for reporting and trend analysis of persistent incidents, and Problem Management root cause analysis<br />\r\n-Ensure adherence to established Service Recovery Management policies and procedures and as well as Change Management process where a change is required to restore service<br />\r\n-Ensure key performance indicators are measured for Incidents and report trends of process maturity levels and tool adoption<br />\r\n-Align and deliver targets set out by Executive Management team<br />\r\n-Ownership of the incident lifecycle to satisfactory resolution as confirmed by Service<br />\r\n<br />\r\nManagement<br />\r\n-Ensure all Support contact information and coverage schedules are being maintained by designated leads and readily accessible for use in incident escalation or automated notification in xMatters<br />\r\n-Consolidate knowledge sources including predefined diagnostic procedures, known errors database and incident workarounds (CMDB) used in service restoration. Guide resolver groups and provide input into future functionality and features through Service Management.<br />\r\n-Proactively manage incidents to satisfactory resolution in a timely manner, ensuring minimal business impact, and initiate escalation procedure as appropriate<br />\r\n-Manage the Incident SLAs, Key Performance Indicators where appropriate, with accurate reporting to key stakeholders<br />\r\n-Understand and appreciate the impact of incidents on SLA targets, allowing prioritization and direction<br />\r\n-Conduct Major Incident Reviews (MIR) with key incident participants to verify incident facts, gauge recovery team performance, identify gaps in the process, reinforce positive actions and drive service improvement.<br />\r\n-Manage internal process assessment surveys with regards to handling of major Incidents to identify deficiencies and areas of improvement<br />\r\n-Document and make transparent all relevant processes and procedures for the provision of Service Recovery Management<br />\r\n-Ensure that Operational Acceptance Criteria delivers the quality of handover from projects and / or major releases for processes owned<br />\r\n-Provide timely reporting to management of IM KPI Dashboard reporting<br />\r\n-Provide training and job aids where required for team members and support groups participating in the Service Recovery Management process.<br />\r\n<br />\r\nSkills:<br />\r\nCompetencies<br />\r\n-Excellent relationship management skills with the ability to build a \'one team\' mentality<br />\r\n-Excellent written and oral communication skills; calm, polite and professional<br />\r\n-Service oriented, adaptable and resilient<br />\r\n-Results oriented with personal accountability<br />\r\n-Excellent attention to detail, quality and control<br />\r\n-Analytical thinker with the ability to define and present information (e.g. KPIs and performance metrics)<br />\r\n-Excellent interpersonal skills including listening, building rapport and an awareness of<br />\r\n<br />\r\nProfessional / Technical Skills<br />\r\n-Experience with Service Desk tools; preferably Service Now with relevant processes<br />\r\n-Knowledge and understanding of Title/Specialty Insurance, Real Estate settlement services, their technologies and applications<br />\r\n-Knowledge of Networking, Server, Voice and Communications Infrastructure<br />\r\n<br />\r\nEducation:<br />\r\nTechnology Degree / Bachelors Degree or 5+ years of related experience<br />\r\nProfessional Qualifications: ITIL v3 and or Incident/Problem Management accredited<br />\r\nDemonstrate proven experience and management in the area ITIL Incident Management', '', '', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '11 April, 2017', '2017-04-11', 36, '2017-04-11 05:49:43', 'US', 'Y', '', '', '', ''),
(93462995, 0, 'HR Technical Developer/ Analyst', 'Cal State University, Chancellors Office', '', '1', '90', '25 Jun, 2017', '3', '5', 'Full-Time', '', '', '', '', 'Market', 'US', '', '', ' Long Beach, CA', 'HR Technical Analyst/Programmer.', '', '21', '115', '', '', '', '', 'Under the general direction of the Project Manager, the HR Technical Analyst/Programmer will: provide technical production support for 23 CSU campuses and the Chancellor\'s Office by analyzing and troubleshooting campus application issues reported through Service-now cases; adhere to published Service Level Agreements (SLAs) and Application Development procedures; conduct unit, system, integration and regression testing of Oracle/PeopleSoft bundles, maintenance pack releases, PeopleTools and Oracle upgrades, and CSU updates and fixes; coordinate program and technical specification development/testing as well as time and cost estimates for customizations, upgrades and other project activity; this includes conducting conference calls or webinars with the HUG (HR User Group), sub-committees and campus representatives; participate on project teams as appropriate to implement new system functionality within the Oracle/PeopleSoft HR application; analyze, test and document custom modifications required to address CSU business requirements; support the HR / SA split activities as well as the CHRS implementation project; create and maintain technical documentation required to support the CSU Oracle/PeopleSoft HR application; collaborate with all Application Development teams to understand and resolve campus application issues as needed; produce deliverables that adhere to quality standards and comply with Application Development procedures and practices; undertake special projects as directed including working with other SME teams to facilitate cross training and coverage of all application areas.<br />\r\n	<br />\r\nQualifications<br />\r\n	<br />\r\nThis position requires a Bachelor\'s degree in Computer Science or a related field or an equivalent combination of education and experience, as well as course work in the Oracle/PeopleSoft HR application; minimum 3-5 years of HR technical experience working with the Oracle PeopleSoft HCM application or other similar ERP is required; in-depth technical knowledge and experience with at least one HR module, such as Absence Management, Faculty, Security, etc. is preferred; excellent application implementation life cycle skills including experience developing requirements, fit/gap analysis, application configurations, technical specifications and the ability to translate business requirements into technical designs; excellent written and advanced verbal communication skills (including exceptional listening mentoring and collaboration abilities); working knowledge and experience with Human Resources practices and systems in a higher education environment and proficient knowledge of PeopleSoft rules based processing is preferred.', '', 'oin our team at the California State University, Office of the Chancellor, and make a difference in providing access to higher education. We are currently seeking experienced candidates for the position of HR Technical Analyst/Programmer. The CSU Chancellor\'s Office, located on the waterfront adjacent to the Aquarium of the Pacific in downtown Long Beach, is the headquarters for the nation\'s largest and most diverse system of higher education. The CSU Chancellor\'s Office offers a premium benefit package that includes outstanding vacation, health, and dental plans; a fee waiver education program; membership in the California Public Employees Retirement System (PERS); and 14 paid holidays a year.<br />\r\n	<br />\r\nSalary<br />\r\n	<br />\r\nThe salary range for this classification is $4,372 to $9,401 per month.<br />\r\n	<br />\r\nPosition Information<br />\r\n	<br />\r\nThe California State University, Office of the Chancellor, is seeking a HR Technical Analyst/Programmer to provide technical support for CSU\'s Oracle / PeopleSoft HCM application within Information Systems. Information Systems\' Application Development area encompasses application support and upgrade activities for 23 campuses and the CSU Chancellor\'s Office (CO), integration with other third-party/external and/or internal systems, the consolidation of the HR databases implementation (CHRS Completion Project), and the HR/Student split project. The technical analyst requires proactive initiative to resolve the most complex HCM application issues in support/development areas that include implementation, system analysis, planning, design, development and support of the HR application. Specific technical support assignments may change at any time based on Application Development\'s projects and priorities, including supporting other applications within the area.', '', ' Bachelor\'s degree in Computer Science', 'Formal', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '27 March, 2017', '2017-03-27', 51, '2017-03-27 02:36:44', 'US', 'Y', '', '', '', ''),
(93495889, 0, 'Senior Accountant', 'Manufacturing Industry', '', '2', '90', '06 Jun, 2017', '2', '4', 'Full-Time', '', '', '', '', '11', 'US', '', '', 'Burlington, WI', 'Accounting - General, Accounting - Taxes and Preparation, Accounting - Management', '', '10', '1', '', '', '', '', '', '', 'Senior Accountant:<br />\r\n<br />\r\nSeeking a success-driven Senior Accountant that will provide coverage for key accounting functions and assist with miscellaneous projects: Duties May Include:<br />\r\n<br />\r\nâ€¢ Variance analysis, control and costing.<br />\r\nâ€¢ Monitoring of purchase variances<br />\r\nâ€¢ Sales / Use / Payroll Tax<br />\r\nâ€¢ Internal / Divisional reporting<br />\r\nâ€¢ Maintain, analyze, and reconcile general ledger accounts and activities ensuring each account has proper documentation and complies with GAAP<br />\r\nâ€¢ Accounts Receivable / Payables<br />\r\nâ€¢ Contribute to the year-end audit process.<br />\r\nâ€¢ Assistance with system enhancements and implementations â€¢ Mentoring of junior accountants<br />\r\nâ€¢ Backup for other senior accountants Education, Experience, and Skills Required:<br />\r\nâ€¢ Bachelorâ€™s Degree in Accounting from an accredited program<br />\r\nâ€¢ Minimum 2 years of accounting experience within a manufacturing environment<br />\r\nâ€¢ Inventory Experience is required<br />\r\nâ€¢ Project management experience preferred<br />\r\nâ€¢ Microsoft Word, Excel & Access required<br />\r\nâ€¢ Microsoft Dynamic GP and SQL experience a plus<br />\r\nâ€¢ Ability to meet deadlines, multi-task and have strong attention to detail<br />\r\nâ€¢ Must be able to problem solve, identify discrepancies and make recommendations.<br />\r\nâ€¢ Excellent interpersonal communication skills<br />\r\nâ€¢ Self-Driven, Organized, Analytical Minded, Fast-Leaner<br />\r\nâ€¢ Minimum 60 WPM / 10,000 KPH<br />\r\n<br />\r\nWe are  an Equal Opportunity Employer. Qualified females, members of ethnic and racial minority groups, persons with disabilities and veterans are encouraged to apply', '', 'Graduation / PG', 'Formal', 'US Citizen', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '08 March, 2017', '2017-03-08', 70, '2017-03-08 03:55:24', 'US', 'Y', '', '', '', ''),
(93672502, 28595, 'Hiring PHP Developer with Experience 1- 3 yrs', 'Browsewire Consulting Pvt. Ltd.', '', '', '0', '', '1', '3', 'Full-Time', '', '', '', '', '', '', '', '', 'Chandigarh, mohali', '', '', '23', '16', '', '', 'Y', '', '', '', '<br />\r\nBrowsewire Consulting Pvt Ltd is India-based global IT solution provider focused on providing Web Application Development, Design, and IT Consulting Solutions to SMEs across the globe. Globally, Browsewire customers benefit from the exceptional experience. Our focus is mutual growth for the employees and the customers.<br />\r\n<br />\r\nBrowsewire has an extensive services portfolio spanning: Web Application Development, Web Designing, Mobile App Development and Digital Marketing.<br />\r\n<br />\r\nPosition: PHP Developer (Junior to Senior Level)<br />\r\nJOB DESCRIPTION:<br />\r\n1. We are looking for self-motivated and resourceful PHP Developers having knowledge in Wordpress and at least one framework (CodeIgniter, Laravel, CakePHP, Yii)<br />\r\n<br />\r\n2. Programming of all PHP based projects<br />\r\n<br />\r\n3. Writing Clean well designed code<br />\r\n<br />\r\n4. Passion for best design and coding practices and a desire to develop new bold ideas.<br />\r\n<br />\r\nTECHNICAL QUALIFICATIONS:<br />\r\n1. Excellent verbal and written communication skills<br />\r\n<br />\r\n2. Experience with DevOps practices and toolset Experience with Typescript, Bootstrap Experience.<br />\r\n<br />\r\n3. High degree of competency in core software development concepts<br />\r\n<br />\r\n4. Knowledge about Angular JS<br />\r\n<br />\r\n5. Understanding of MVC design patterns & frameworks<br />\r\n<br />\r\n6. Good hands on WordPress, Plugin Development, Customization & One framework is mandatory<br />\r\n<br />\r\n7. Experience in HTML, CSS, Jquery, JavaScript & Ajax<br />\r\n<br />\r\nEXPERIENCE AND ABILITIES:<br />\r\n1. 1-4 years of experience in Web Development using PHP and Frameworks (Codeigniter, Laravel, CakePHP, Yii) and/or CMS (Wordpress, Magento)<br />\r\n<br />\r\n2. Must be able to interact effectively with all levels of management and staff<br />\r\n<br />\r\n3. Must be adaptable, professional, courteous and motivated.<br />\r\n<br />\r\n4. Strong programming skills desired.<br />\r\n<br />\r\n5. Excellent verbal and written communication skills.<br />\r\n<br />\r\nKEYSKILLS :<br />\r\n1. PHP<br />\r\n<br />\r\n2. Wordpress<br />\r\n<br />\r\n3. Yii<br />\r\n<br />\r\n4. Codeigniter<br />\r\n<br />\r\n5. Laravel<br />\r\n<br />\r\n6. MySQL<br />\r\n<br />\r\n7. Cake PHP<br />\r\n<br />\r\nEDUCATION :<br />\r\nUG: B.Tech/B.E.-Computers, B.Sc - Computers<br />\r\n<br />\r\nPG: MCA - Computers, M.Tech - Computers, M.Sc- Computers<br />\r\n<br />\r\nBENEFITS: Monthly Appraisal + Unlimited Planned Leaves<br />\r\nOpportunity to learn from teams working in varied technologies<br />\r\n<br />\r\nSALARY: 30% hike in current salary for experienced candidates<br />\r\nJob Type: Full-time<br />\r\n<br />\r\n', 'ishar@browsewire.net', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '12 January, 2017', '2017-01-12', 125, '2017-01-12 04:42:14', 'IN', 'Y', '', '', '', ''),
(94048367, 21094, 'Python Developer', 'Activesoftinc', '', '1', '0', '', '4', '9', 'Full-Time', '', '', '', '', '10', 'US', '2998', '1180898', 'Cincotta, ', 'Java, Python& SQL', '', '23', '40', '', '', '', '', '', '', 'Java, Python, strong SQL<br />\r\nBig Data experience is a plus Big Data technology project- data addition & data transformation.<br />\r\nSupporting existing applications in Python.<br />\r\nBusiness enhancements and maintenance.<br />\r\nVery fluent in Python, existing programs.<br />\r\nInteract with the business day-to-day, deliver quality work on time, on budget.<br />\r\nFinancial Industry experience a plus<br />\r\nAgile Environment', 'Activesoft Activesoft<br />\r\nActivesoft, Inc<br />\r\nAtlanta, GA<br />\r\nwww.activesoftinc.com<br />\r\n +1-404-496-4368', 'MCA/B Tech./ M Tech.', 'Formal', 'US Citizen, GC', 'Contract to Hire', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '13 February, 2017', '2017-02-13', 93, '2017-02-13 02:45:10', 'US', 'Y', '', '', '', ''),
(94096151, 40613, 'Bidders / BDM ', 'Daksha Web Technology Pvt. Ltd.', '', '2', '0', '', '1', '4', 'Full-Time', '', '', '', '', '3', '', '', '', 'Mohali, Punjab', '', '', '41', '123', '', '', 'Y', '', '', '', 'Responsibilities:<br />\r\n- Bidding on Upwork, Elance, Guru<br />\r\n- Lead generation<br />\r\n- Setting up appointments with clients, client visits & giving company presentation<br />\r\n- Have experience with daily cold calling and field prospecting<br />\r\n- Follow up, negotiate and convert the client<br />\r\n- Filling in sales reports and documentation<br />\r\n- Excellent communication & presentation skills.<br />\r\n- Ability to attract and retain customers<br />\r\n- Willing to take risk and plan and achieve individual & company targets<br />\r\n- Ensure tasks are completed correctly and on time.<br />\r\n- Excellent communication skills<br />\r\n', 'Interested candidates can mail their resumes at hr@dakshadesign.com', '', '', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '06 February, 2017', '2017-02-06', 100, '2017-02-06 06:45:42', 'IN', 'Y', '', '', '', '');
