(99172177, 0, 'Accounts Manager', 'Three Star Consultancy Services', '', '1', '0', '', '4', '5', 'Full-Time', '', '', '', '', '3', '', '', '', 'Malappuram', '', '', '2', '113', '', 'Y', 'Y', '', '', '', 'Greetings from Three Star Consultancy Services\r\n\r\nThe Urgent requirement for Accounts Manager in a well reputed Builders and Developers firm at Edapally\r\n\r\nJob Profile: Accounts Manager\r\n\r\nQualification: PG\r\n\r\nExperience :above 4-5 years\r\n\r\nSalary: Upto 40 k(Depends on the current ctc)\r\n\r\nJob Location : Kochi\r\n\r\nAge: 40 years\r\n\r\nInterested candidates are requested to forward their updated resume as soon as possible to the id given below\r\n\r\nannmerin@threestar.in\r\n\r\n8113940444\r\n\r\nAnn Merin Toms\r\n\r\nAssistant Manager-HR\r\n\r\nThree star Consultancy Services', 'Email: annmerin@threestar.in\r\nTelephone: 8113940444', 'P.G', 'Formal', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '09 February, 2017', '', 17303, '2017-02-09 02:07:42', 'IN', 'Y', '', '', '', ''),
(99172178, 0, 'Accounts Manager', 'Innovative Recruitments', '', '1', '0', '', '2', '5', 'Full-Time', '', '', '', '', '', '', '', '', 'Mohali', 'Accounts  Scheduling  Manufacturing', '', '2', 'Select Functional Area', '', 'Y', 'Y', '', '', '', 'We require an accounts manager . preferably CA inter with 2-3 years experience in manufacturing and trading accounts. Achieves accounting operational objectives by contributing accounting information and recommendations to strategic plans and reviews; preparing and completing action plans; implementing production, productivity, quality, and customer-service standards; resolving problems; completing audits; identifying trends; determining system improvements; implementing change.\r\nMeets accounting financial objectives by forecasting requirements; preparing an annual budget; scheduling expenditures; analyzing variances; initiating corrective actions.\r\nConfirms financial status by monitoring revenue and expenses; coordinating the collection, consolidation, and evaluation of financial data; preparing special reports.', 'Email: innovativerecruitments25@gmail.com\r\nTelephone: 8054777366', 'P.G', 'Formal', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '09 February, 2017', '', 17303, '2017-02-09 02:09:24', 'IN', 'Y', '', '', '', ''),
(99172179, 0, 'BULK HIRING IN HT MEDIA( FIELD SALES) SALARY UPTO 20K WITH ATTRACTIVE INCENTIVES', 'EQS Placement Pvt Limited Hiring For B2B sales process', '', '1', '0', '', '1', '5', 'Full-Time', '', '', '', '', '3', '', '', '', 'Noida', 'Direct  sales BD ESales', '', '28', '82', '', 'Y', 'Y', '', '', '', 'Dear Candidates,\r\n\r\n \r\n\r\nWe are hiring for a Field sales in HINDUSTAN TIMES\r\n\r\n\r\n \r\n\r\nProcess: FIELD SALES\r\n\r\nExperience:  minimum 1 year of experience\r\n\r\nSalary 15K TO 18K \r\n\r\nFixedshift: MORNING SHIFT\r\n\r\n \r\n\r\n*DAY SHIFT\r\n\r\n*ATTRACTIVE INCENTIVES\r\n\r\n*\r\n\r\n  \r\n\r\nFor more details\r\n\r\n \r\n\r\nCall -PRASHANT: 8130199014\r\n\r\nEmail: Prashant@eqsplacements.com', 'Email: prashant@eqsplacements.com\r\nTelephone: 8130199014', '', 'Formal', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '09 February, 2017', '', 17303, '2017-02-09 02:11:30', 'IN', 'Y', '', '', '', ''),
(99172180, 0, 'HIRING FOR FIELD SALES EXECUTIVES FOR DELHI,NOIDA,GURGAON,', 'EQS Placement Pvt Limited Hiring For EQS Placement Pvt Limited', '', '1', '0', '', '0', '5', 'Full-Time', '', '', '', '', '3', '', '', '', 'Noida', '', '', '28', '82', '', 'Y', 'Y', '', '', '', '******CALL ABHISHEK 8130199020*****\r\n\r\nDear candidates,\r\n\r\n\"Greetings Of The Day\",\r\n\r\nWe are hiring for sales & Marketing executive for Delhi/NCR Location,\r\n\r\n\"GREAT OPPORTUNITY TO WORK WITH REPUTED COMPANY \",\r\n\r\nJob Description :\r\n\r\n Outbound sales/Sales & Marketing Executive\r\n\r\nLocation: Delhi, NCR/Gurgaon\r\n\r\n1 YEAR EXPERIENCE REQUIRED\r\n\r\n**SHOULD BE GRADUATE**\r\n\r\nSalary : 15k-18kMax \r\n\r\nUnlimited incentives\r\n\r\nCOMPANY NAME : HT MEDIA\r\n\r\nShift Timing : Day Shift\r\n\r\nSHOULD BE GRADUATE.\r\n\r\n\"Groom Your career in Marketing\"\r\n\r\nFor More Details Call :-ABHISHEK : 8130199020\r\n\r\nOR E-MAIL : abhishek3@placements.com\r\n\r\n ', 'Email: abhishek3@eqsplacements.com\r\nTelephone: 8130199020', 'Graduate', 'Formal', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '09 February, 2017', '', 17303, '2017-02-09 02:13:08', 'IN', 'Y', '', '', '', ''),
(99172181, 0, 'Admin Executive for Real Estate Industry at Malad (W)', 'Excellence Recruitment Solution Hiring For Admin Executive for Real Estate Industry at Malad (W)', '', '1', '0', '', '1', '5', 'Full-Time', '', '', '', '', '3', '', '', '', 'Navi Mumbai', 'ADMINISTRATION', '', '12', '62', '', 'Y', 'Y', '', '', '', 'Greeting of the dayâ€¦.!!!!!!\r\n\r\nOne of our clients in leading Real Estate Industry is looking for Admin Executive\r\n\r\nDesignation: Admin Executive (Exp must be in Real Estate Industry)\r\n\r\nExperience: 2+ Years\r\n\r\n \r\n\r\n Company Profile: - We are into residential Real Estate development in Western Mumbai. We have Completed 51 projects till date and have another 23 in pipeline.\r\n\r\n \r\n\r\nSkills: - 1) Presentable, 2) Smart & Sophisticated, 3) Dynamic & Result Oriented, 4) Self Motivated, 5) Excellent communication skills, 6) good interpersonal, 7) organizational skills\r\n\r\nJob Description:-\r\n\r\n1) Administrative Tasks â€“ Will be responsible for co-ordination between client & management, 2) Letter Drafting and Filing,\r\n\r\n3) Maintaining Official Documents & stationery,\r\n\r\n4) Daily Reports\r\n\r\n5) Should be able to provide good administrative support to ensure efficient operation of the office\r\n\r\n \r\n\r\n Industry Preferred: (Experience in Real Estate& Property Industry)\r\n\r\nSalary: 10k to 15k\r\n\r\nJob Location: Malad (W)\r\n\r\nWorking Days:-Mon to Sat 10.30 to 7.00 PM\r\n\r\n \r\n\r\nInterested please forward youâ€™re CV at poonam@jobproffer.me\r\n\r\nKindly confirm your interest by sending your CV mentioning the following details:-\r\n\r\nCandidate Name:\r\n\r\nQualification:\r\n\r\nTotal Experience:\r\n\r\nCurrent Company:\r\n\r\nCurrent Salary pm:\r\n\r\nExpected salary:\r\n\r\nNotice period:\r\n\r\nCurrent Position:\r\n\r\nCurrent Location:\r\n\r\nWork Location:\r\n\r\n With Best Regards,\r\n\r\nPoonam\r\n Sr. Recruitment Executive\r\n 8976519773\r\n Excellence Recruitment Solutions', 'Email: poonam@jobproffer.me\r\nTelephone: 8976519773', '', 'Formal', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', 'N', '10 February, 2017', '', 17303, '2017-02-10 06:27:09', 'IN', 'Y', '', '', '', '');
